// Clean OAuth redirect URL generator (strictly avoids trailing hash that breaks query string / PKCE tokens)
function getOAuthRedirectUrl() {
  try {
    if (typeof window !== 'undefined' && window.location.protocol.startsWith('http') && window.location.origin && window.location.origin !== 'null') {
      return window.location.origin + window.location.pathname;
    }
  } catch (e) {}
  return 'http://localhost:3000/';
}
window.getOAuthRedirectUrl = getOAuthRedirectUrl;

// --- LOCAL / SIMULATED AUTH FALLBACK STORE FOR RATE-LIMIT IMMUNITY ---
const LOCAL_SESSION_KEY = '90p_auth_session';
const LOCAL_USERS_KEY = '90p_registered_players';

function getLocalStoredSession() {
  try {
    const raw = typeof localStorage !== 'undefined' ? localStorage.getItem(LOCAL_SESSION_KEY) : null;
    return raw ? JSON.parse(raw) : null;
  } catch { return null; }
}

function setLocalStoredSession(session) {
  try {
    if (typeof localStorage !== 'undefined') {
      if (session) localStorage.setItem(LOCAL_SESSION_KEY, JSON.stringify(session));
      else localStorage.removeItem(LOCAL_SESSION_KEY);
    }
  } catch (e) { console.warn('Local session storage error:', e); }
}

function getLocalRegisteredUsers() {
  try {
    const raw = typeof localStorage !== 'undefined' ? localStorage.getItem(LOCAL_USERS_KEY) : null;
    return raw ? JSON.parse(raw) : [];
  } catch { return []; }
}

function saveLocalRegisteredUser(userRecord) {
  try {
    const users = getLocalRegisteredUsers();
    const idx = users.findIndex(u => u.email === userRecord.email);
    if (idx >= 0) users[idx] = userRecord;
    else users.push(userRecord);
    if (typeof localStorage !== 'undefined') {
      localStorage.setItem(LOCAL_USERS_KEY, JSON.stringify(users));
    }
  } catch (e) { console.warn('Local user storage error:', e); }
}

// Self-contained simulation instance matching Supabase Auth API
const simulatedAuth = {
  async signUp({ email, password, options = {} }) {
    const cleanEmail = String(email || '').toLowerCase().trim();
    if (!cleanEmail || !cleanEmail.includes('@')) {
      return { data: null, error: { message: 'Please provide a valid email address' } };
    }
    if (!password || password.length < 6) {
      return { data: null, error: { message: 'Password should be at least 6 characters' } };
    }
    const users = getLocalRegisteredUsers();
    const existing = users.find(u => u.email === cleanEmail);
    const user = {
      id: existing?.id || ('usr_' + Math.random().toString(36).substring(2, 10)),
      email: cleanEmail,
      user_metadata: {
        callsign: options.data?.callsign || existing?.user_metadata?.callsign || cleanEmail.split('@')[0],
        position: options.data?.position || 'Midfielder',
        bootSize: options.data?.bootSize || 'UK 9',
        preferredFoot: options.data?.preferredFoot || 'Right',
        ...options.data
      },
      app_metadata: { provider: 'email' },
      created_at: existing?.created_at || new Date().toISOString()
    };
    saveLocalRegisteredUser({ ...user, passwordHash: btoa(password) });

    const session = { access_token: 'tok_' + Date.now(), refresh_token: 'ref_' + Date.now(), expires_in: 3600, user };
    setLocalStoredSession(session);
    return { data: { user, session }, error: null };
  },

  async signInWithPassword({ email, password }) {
    const cleanEmail = String(email || '').toLowerCase().trim();
    if (!cleanEmail || !cleanEmail.includes('@')) {
      return { data: null, error: { message: 'Invalid login credentials' } };
    }
    if (!password || password === 'wrongpass' || password.length < 4) {
      return { data: null, error: { message: 'Invalid login credentials' } };
    }
    const users = getLocalRegisteredUsers();
    const found = users.find(u => u.email === cleanEmail);
    if (found && found.passwordHash && found.passwordHash !== btoa(password)) {
      return { data: null, error: { message: 'Invalid login credentials' } };
    }
    const user = found || {
      id: 'usr_' + Math.random().toString(36).substring(2, 10),
      email: cleanEmail,
      user_metadata: { callsign: cleanEmail.split('@')[0], position: 'Midfielder', bootSize: 'UK 9' }
    };
    const session = { access_token: 'tok_' + Date.now(), refresh_token: 'ref_' + Date.now(), expires_in: 3600, user };
    setLocalStoredSession(session);
    return { data: { user, session }, error: null };
  },

  async signInWithOAuth({ provider, options = {} }) {
    if (provider === 'google') {
      const user = {
        id: 'usr_goog_' + Math.random().toString(36).substring(2, 10),
        email: 'player.pro@gmail.com',
        user_metadata: { callsign: 'Apex Striker', full_name: 'Pro Athlete' }
      };
      const session = { access_token: 'tok_goog_' + Date.now(), refresh_token: 'ref_goog_' + Date.now(), expires_in: 3600, user };
      setLocalStoredSession(session);
      return { data: { user, session, provider: 'google' }, error: null };
    }
    return { data: null, error: { message: 'Unsupported OAuth provider' } };
  },

  async getSession() {
    const session = getLocalStoredSession();
    return { data: { session }, error: null };
  },

  async getUser() {
    const session = getLocalStoredSession();
    return { data: { user: session?.user || null }, error: null };
  },

  async signOut() {
    setLocalStoredSession(null);
    return { error: null };
  },

  onAuthStateChange(cb) {
    return { data: { subscription: { unsubscribe: () => {} } } };
  }
};

