const THREE = typeof window.THREE !== 'undefined' ? window.THREE : null;
const OrbitControls = (THREE && THREE.OrbitControls) ? THREE.OrbitControls : (window.OrbitControls || class BuiltinOrbitControls {
  constructor(camera, domElement) {
    this.camera = camera;
    this.domElement = domElement;
    this.enabled = true;
    this.enableDamping = false;
    this.dampingFactor = 0.05;
    this.enableZoom = true;
    this.enableRotate = true;
    this.enablePan = false;
    this.autoRotate = false;
    this.autoRotateSpeed = 2.0;
    this.minDistance = 0.5;
    this.maxDistance = 100;
    this.minPolarAngle = 0;
    this.maxPolarAngle = Math.PI;
    this.target = THREE ? new THREE.Vector3() : { x: 0, y: 0, z: 0 };

    let isDragging = false;
    let prevMouse = { x: 0, y: 0 };
    let spherical = {
      radius: (camera && camera.position && camera.position.distanceTo) ? camera.position.distanceTo(this.target) : 5,
      theta: (camera && camera.position) ? Math.atan2(camera.position.x, camera.position.z) : 0,
      phi: (camera && camera.position && camera.position.distanceTo) ? Math.acos(camera.position.y / Math.max(0.001, camera.position.distanceTo(this.target))) : Math.PI / 2
    };

    const onPointerDown = e => {
      if (!this.enabled) return;
      isDragging = true;
      prevMouse = { x: e.clientX, y: e.clientY };
    };
    const onPointerMove = e => {
      if (!isDragging || !this.enabled) return;
      const dx = e.clientX - prevMouse.x;
      const dy = e.clientY - prevMouse.y;
      prevMouse = { x: e.clientX, y: e.clientY };
      spherical.theta -= dx * 0.008;
      spherical.phi = Math.max(0.1, Math.min(Math.PI - 0.1, spherical.phi - dy * 0.008));
      this.updateCamera();
    };
    const onPointerUp = () => { isDragging = false; };
    const onWheel = e => {
      if (!this.enableZoom) return;
      e.preventDefault();
      spherical.radius = Math.max(this.minDistance, Math.min(this.maxDistance, spherical.radius + e.deltaY * 0.005));
      this.updateCamera();
    };

    if (domElement) {
      domElement.addEventListener('pointerdown', onPointerDown);
      window.addEventListener('pointermove', onPointerMove);
      window.addEventListener('pointerup', onPointerUp);
      domElement.addEventListener('wheel', onWheel, { passive: false });
    }

    this.updateCamera = () => {
      if (!camera) return;
      const sinPhi = Math.sin(spherical.phi);
      camera.position.x = this.target.x + spherical.radius * sinPhi * Math.sin(spherical.theta);
      camera.position.y = this.target.y + spherical.radius * Math.cos(spherical.phi);
      camera.position.z = this.target.z + spherical.radius * sinPhi * Math.cos(spherical.theta);
      camera.lookAt(this.target);
    };
    this.update = () => {
      if (this.autoRotate && !isDragging) {
        spherical.theta += 0.01 * (this.autoRotateSpeed / 2);
        this.updateCamera();
      }
    };
  }
});

