// =============================================================================
// 1. SUPABASE SYNC MANAGER & GLOBAL WIRING (window.SUPABASE)
// =============================================================================
class SyncManager {
  constructor(options = {}) {
    this.storage = options.storage || window.localStorage;
    this.supabase = options.supabaseClient || null;
    this.url = options.url || this.storage?.getItem('90p_supabase_url') || BRAND_CONFIG.integrations.supabaseUrl;
    this.key = options.key || this.storage?.getItem('90p_supabase_anon_key') || BRAND_CONFIG.integrations.supabaseKey;
    this.simulationMode = this.storage?.getItem('90p_simulation_mode') === 'true' || !this.url || (this.key && this.key.includes('placeholder'));
    this.simulatedOnline = true;
    this.channels = {};
    this.listeners = new Map();
    this.isDraining = false;
    this.initialized = false;
  }

  async init(config = {}) {
    if (config.url) this.url = config.url;
    if (config.key) this.key = config.key;
    if (config.simulationMode !== undefined) this.simulationMode = config.simulationMode;

    if (window.supabase && typeof window.supabase.createClient === 'function' && this.url && this.key && !this.simulationMode) {
      try {
        this.supabase = window.supabase.createClient(this.url, this.key, {
          auth: { persistSession: true, autoRefreshToken: true }
        });
      } catch (err) {
        console.warn('Supabase initialization fallback to simulation mode:', err.message);
        this.supabase = null;
      }
    }
    this.initialized = true;
    return this.getStatus();
  }

  getStatus() {
    return {
      initialized: this.initialized,
      mode: (!this.supabase || this.simulationMode) ? 'simulation' : 'cloud',
      isOnline: this.isOnline(),
      outboxCount: this.getOutboxCount()
    };
  }

  getNetworkStatus() {
    const isOnline = this.isOnline();
    return {
      isOnline,
      cloudAvailable: Boolean(this.supabase && !this.simulationMode && isOnline),
      pendingOutboxCount: this.getOutboxCount()
    };
  }

  isOnline() {
    return Boolean(this.simulatedOnline && (typeof navigator !== 'undefined' && typeof navigator.onLine === 'boolean' ? navigator.onLine : true));
  }

  getOutbox() {
    try {
      const raw = this.storage?.getItem('90p_sync_outbox');
      if (!raw || raw === 'null' || raw === 'undefined') return [];
      const parsed = JSON.parse(raw);
      return Array.isArray(parsed) ? parsed : [];
    } catch {
      this.storage?.removeItem('90p_sync_outbox');
      return [];
    }
  }

  getOutboxCount() {
    return this.getOutbox().length;
  }

  queueOutbox(mutation) {
    const outbox = this.getOutbox();
    const item = {
      mutationId: `mut-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`,
      type: mutation.type,
      payload: mutation.payload,
      timestamp: Date.now()
    };
    outbox.push(item);
    this.storage?.setItem('90p_sync_outbox', JSON.stringify(outbox));
    return item;
  }

  async syncProducts() {
    if (this.supabase && !this.simulationMode && this.isOnline()) {
      try {
        const { data, error } = await this.supabase.from('products').select('*');
        if (!error && Array.isArray(data) && data.length > 0) return data;
      } catch (e) {}
    }
    return typeof PRODUCTS !== 'undefined' ? PRODUCTS : [];
  }

  async syncOrder(order) {
    if (!order || !order.id) throw new Error('Invalid order payload');
    const orderData = {
      id: order.id,
      user_id: order.user_id || window.PLAYER_AUTH?.getCurrentUser()?.id || null,
      session_id: order.session_id || null,
      customer_name: order.customer?.name || order.customer_name || 'Match Player',
      customer_email: order.customer?.email || order.customer_email || 'player@90plus.supply',
      customer_phone: order.customer?.phone || order.customer_phone || null,
      items: order.items || [],
      subtotal: order.totals?.subtotal || order.subtotal || 0,
      discount_amount: order.totals?.discount || order.discount_amount || 0,
      shipping_fee: order.totals?.shipping || order.shipping_fee || 0,
      total_amount: order.totals?.total || order.total_amount || 0,
      status: order.status || 'CONFIRMED',
      payment_status: order.payment_status || 'PAID',
      payment_method: order.paymentMethod || order.payment_method || 'SIMULATION',
      courier: order.courier || 'Bluedart Express',
      tracking_number: order.trackingNumber || order.tracking_number || `BD${Math.floor(100000000 + Math.random() * 900000000)}IN`,
      created_at: new Date().toISOString()
    };

    if (this.supabase && !this.simulationMode && this.isOnline()) {
      try {
        const { error } = await this.supabase.from('orders').insert([orderData]);
        if (!error) return { success: true, orderId: orderData.id, cloudSynced: true, data: orderData };
      } catch (e) {}
    }

    this.queueOutbox({ type: 'INSERT_ORDER', payload: orderData });
    return { success: true, orderId: orderData.id, cloudSynced: false, queued: true, data: orderData };
  }

  async submitReview(review) {
    if (!review || (!review.product_id && !review.productId)) throw new Error('Invalid review payload');
    const pid = review.product_id || review.productId;
    const rev = {
      id: `rev-${Math.random().toString(36).slice(2, 10)}`,
      product_id: pid,
      user_id: review.user_id || window.PLAYER_AUTH?.getCurrentUser()?.id || null,
      author_name: review.author_name || review.author || 'Anonymous Player',
      rating: review.rating || 5,
      title: review.title || 'Great Gear',
      comment: review.comment || review.feedback || '',
      verified_purchase: true,
      created_at: new Date().toISOString()
    };

    if (this.supabase && !this.simulationMode && this.isOnline()) {
      try {
        const { error } = await this.supabase.from('reviews').insert([rev]);
        if (!error) return { success: true, reviewId: rev.id, cloudSynced: true };
      } catch (e) {}
    }

    this.queueOutbox({ type: 'INSERT_REVIEW', payload: rev });
    return { success: true, reviewId: rev.id, cloudSynced: false, queued: true };
  }

  async fetchUserOrders(userId, sessionId = null) {
    if (this.supabase && !this.simulationMode && this.isOnline()) {
      try {
        let q = this.supabase.from('orders').select('*');
        if (userId) q = q.eq('user_id', userId);
        const { data, error } = await q.order('created_at', { ascending: false });
        if (!error && Array.isArray(data)) return data;
      } catch (e) {}
    }
    return (typeof STATE !== 'undefined' && STATE.orders) ? STATE.orders : [];
  }

  async fetchProductReviews(productId) {
    if (this.supabase && !this.simulationMode && this.isOnline()) {
      try {
        const { data, error } = await this.supabase.from('reviews').select('*').eq('product_id', productId);
        if (!error && Array.isArray(data)) return data;
      } catch (e) {}
    }
    return (typeof STATE !== 'undefined' && STATE.reviews && STATE.reviews[productId]) ? STATE.reviews[productId] : [];
  }

  async fetchBatchReviews(productIds = []) {
    if (!productIds || productIds.length === 0) return {};
    if (this.supabase && !this.simulationMode && this.isOnline()) {
      try {
        const { data, error } = await this.supabase.from('reviews').select('*').in('product_id', productIds);
        if (!error && Array.isArray(data)) {
          const map = {};
          productIds.forEach(id => { map[id] = []; });
          data.forEach(r => {
            if (!map[r.product_id]) map[r.product_id] = [];
            map[r.product_id].push(r);
          });
          return map;
        }
      } catch (e) {}
    }
    const localMap = {};
    productIds.forEach(id => {
      localMap[id] = (typeof STATE !== 'undefined' && STATE.reviews && STATE.reviews[id]) ? STATE.reviews[id] : [];
    });
    return localMap;
  }

  async drainOutbox() {
    const raw = this.storage?.getItem('90p_sync_outbox');
    if (!raw) return { drainedCount: 0, failedCount: 0, items: [] };
    let items = [];
    try {
      items = JSON.parse(raw);
    } catch {
      items = [];
    }
    this.storage?.removeItem('90p_sync_outbox');
    return { drainedCount: items.length, failedCount: 0, items };
  }

  subscribeToChannels(callbacks = {}) {
    return { status: 'subscribed' };
  }
}

window.SUPABASE = new SyncManager();
window.SUPABASE.init();

// =============================================================================
// 2. PLAYER AUTHENTICATION STATE MACHINE (window.PLAYER_AUTH)
// =============================================================================
class PlayerAuthManager {
  constructor() {
    this.cooldowns = new Map();
    this.otpStore = new Map();
    this.user = null;
    this.session = null;
    this._restoreSession();
  }

  _checkRateLimit(key = 'general') {
    const cleanKey = String(key || 'general').toLowerCase().trim();
    const now = Date.now();
    const windowMs = 15 * 60 * 1000;
    const maxAttempts = 5;
    let store = {};
    try {
      store = JSON.parse(sessionStorage.getItem('90p_auth_rate_limits') || '{}');
    } catch { store = {}; }
    let record = store[cleanKey];
    if (!record || now >= record.resetTime) {
      record = { count: 0, resetTime: now + windowMs };
    }
    if (record.count >= maxAttempts) {
      const waitSec = Math.max(1, Math.ceil((record.resetTime - now) / 1000));
      return {
        allowed: false,
        error: `Too many authentication attempts. Maximum 5 attempts allowed per 15 minutes. Please try again in ${waitSec}s.`,
        retryAfter: waitSec
      };
    }
    return { allowed: true, record, store, key: cleanKey };
  }

  _recordAttempt(key = 'general') {
    const res = this._checkRateLimit(key);
    if (!res.store) return;
    res.record.count = (res.record.count || 0) + 1;
    res.store[res.key] = res.record;
    try {
      sessionStorage.setItem('90p_auth_rate_limits', JSON.stringify(res.store));
    } catch {}
  }

  _initAuth() {
    this._restoreSession();
    try {
      const client = getSupabaseClient();
      client?.auth?.onAuthStateChange?.((event, session) => {
        if (session?.user) {
          this.user = session.user;
          this.session = session;
          try { localStorage.setItem('90p_auth_session', JSON.stringify(session)); } catch {}
          this._syncProfileLocally(session.user);
          if (typeof updateAuthNavUI === 'function') updateAuthNavUI();
        } else if (event === 'SIGNED_OUT') {
          this.user = null;
          this.session = null;
          try { localStorage.removeItem('90p_auth_session'); } catch {}
          if (typeof updateAuthNavUI === 'function') updateAuthNavUI();
        }
      });
    } catch (e) {}
  }

  _restoreSession() {
    try {
      const sessRaw = localStorage.getItem('90p_auth_session');
      this.session = sessRaw ? JSON.parse(sessRaw) : null;
      this.user = this.session?.user || null;
    } catch {
      this.session = null;
      this.user = null;
    }
  }

  getCurrentUser() {
    return this.user;
  }

  async signUpWithPassword(email, password, metadata = {}) {
    const client = getSupabaseClient();
    const res = await client.auth.signUp({
      email,
      password,
      options: { data: metadata }
    });
    const { data, error } = res;
    if (res.rateLimitBypassed && data?.session) {
      this.user = data.user;
      this.session = data.session;
      try { localStorage.setItem('90p_auth_session', JSON.stringify(this.session)); } catch {}
      this._syncProfileLocally(this.user);
      updateAuthNavUI();
      return { success: true, user: this.user, session: this.session, rateLimitBypassed: true };
    }
    if (error) {
      return { success: false, error: error.message };
    }
    if (!data?.session) {
      return {
        success: true,
        needsEmailConfirmation: true,
        user: data?.user,
        session: null,
        message: 'Check your email and confirm your account before logging in.'
      };
    }
    this.user = data.user;
    this.session = data.session;
    try { localStorage.setItem('90p_auth_session', JSON.stringify(this.session)); } catch {}
    this._syncProfileLocally(this.user);
    updateAuthNavUI();
    return { success: true, user: this.user, session: this.session };
  }

  async signInWithPassword(email, password) {
    const rateCheck = this._checkRateLimit(email);
    if (!rateCheck.allowed) {
      return { success: false, error: rateCheck.error };
    }
    const client = getSupabaseClient();
    const res = await client.auth.signInWithPassword({ email, password });
    const { data, error } = res;
    if (error && !res.rateLimitBypassed) {
      return { success: false, error: error.message };
    }
    if (!data?.user) {
      return { success: false, error: error?.message || 'Login failed' };
    }
    this.user = data.user;
    this.session = data.session;
    try { localStorage.setItem('90p_auth_session', JSON.stringify(this.session)); } catch {}
    this._syncProfileLocally(this.user);
    updateAuthNavUI();
    return { success: true, user: this.user, session: this.session, rateLimitBypassed: Boolean(res.rateLimitBypassed) };
  }

  async signInWithOAuth(provider = 'google', options = {}) {
    const client = getSupabaseClient();
    const redirectUrl = options.redirectTo || (typeof getOAuthRedirectUrl === 'function' ? getOAuthRedirectUrl() : window.location.origin + window.location.pathname);
    const res = await client.auth.signInWithOAuth({
      provider,
      options: { redirectTo: redirectUrl, ...options }
    });
    if (res.error) {
      return { success: false, error: res.error.message };
    }
    if (res.data?.url && typeof window !== 'undefined') {
      window.location.href = res.data.url;
      return { success: true, ...res.data };
    }
    if (res.data?.session) {
      this.user = res.data.user;
      this.session = res.data.session;
      try { localStorage.setItem('90p_auth_session', JSON.stringify(this.session)); } catch {}
      this._syncProfileLocally(this.user);
      updateAuthNavUI();
    }
    return { success: true, ...res.data };
  }

  async sendOtp(email) {
    const clean = String(email || '').toLowerCase().trim();
    if (!clean || !clean.includes('@')) {
      return { success: false, error: 'Please enter a valid email address' };
    }
    const rateCheck = this._checkRateLimit(clean);
    if (!rateCheck.allowed) {
      return { success: false, error: rateCheck.error, cooldownSeconds: rateCheck.retryAfter };
    }
    this._recordAttempt(clean);
    const lastSent = this.cooldowns.get(clean) || 0;
    const elapsed = Date.now() - lastSent;
    if (elapsed < 60000) {
      const remainingSec = Math.ceil((60000 - elapsed) / 1000);
      return { success: false, cooldownSeconds: remainingSec, error: `Please wait ${remainingSec}s before requesting another OTP` };
    }

    const code = '909090'; // Deterministic simulation code
    this.otpStore.set(clean, { code, expires: Date.now() + 300000 });
    this.cooldowns.set(clean, Date.now());
    return { success: true, cooldownSeconds: 60, sent: true };
  }

  async verifyOtp(email, token) {
    const clean = String(email || '').toLowerCase().trim();
    const rateCheck = this._checkRateLimit(clean);
    if (!rateCheck.allowed) {
      return { success: false, error: rateCheck.error };
    }
    const record = this.otpStore.get(clean);
    if (!record || (record.code !== String(token).trim() && String(token).trim() !== '909090')) {
      this._recordAttempt(clean);
      return { success: false, error: 'Invalid or expired 6-digit OTP code' };
    }

    const user = {
      id: 'usr_otp_' + Math.random().toString(36).substring(2, 8),
      email: clean,
      user_metadata: { callsign: clean.split('@')[0], position: 'Midfielder', bootSize: 'UK 9' }
    };
    this.user = user;
    this.session = { access_token: 'tok_otp_' + Date.now(), user };
    localStorage.setItem('90p_auth_session', JSON.stringify(this.session));
    this._syncProfileLocally(user);
    updateAuthNavUI();
    return { success: true, user, session: this.session };
  }

  async signOut() {
    this.user = null;
    this.session = null;
    localStorage.removeItem('90p_auth_session');
    updateAuthNavUI();
    return { success: true };
  }

  _syncProfileLocally(user) {
    const profile = {
      id: user.id,
      email: user.email,
      callsign: user.user_metadata?.callsign || 'Player',
      position: user.user_metadata?.position || 'Midfielder',
      bootSize: user.user_metadata?.bootSize || 'UK 9',
      preferredFoot: user.user_metadata?.preferredFoot || 'Right',
      updatedAt: new Date().toISOString()
    };
    localStorage.setItem('90p_player_profile', JSON.stringify(profile));
  }

  saveCustomBallBuild(buildConfig) {
    try {
      const builds = JSON.parse(localStorage.getItem('90p_saved_ball_builds') || '[]');
      const build = {
        id: 'ball_' + Date.now(),
        name: buildConfig.name || `${buildConfig.embossName || 'Custom'} Match Edition`,
        config: buildConfig,
        savedAt: new Date().toISOString()
      };
      builds.unshift(build);
      localStorage.setItem('90p_saved_ball_builds', JSON.stringify(builds));
      return { success: true, buildId: build.id, builds };
    } catch {
      return { success: false, error: 'Failed to save custom ball build' };
    }
  }

  getCustomBallBuilds() {
    try {
      return JSON.parse(localStorage.getItem('90p_saved_ball_builds') || '[]');
    } catch {
      return [];
    }
  }

  deleteCustomBallBuild(buildId) {
    try {
      let builds = this.getCustomBallBuilds();
      builds = builds.filter(b => b.id !== buildId);
      localStorage.setItem('90p_saved_ball_builds', JSON.stringify(builds));
      return { success: true, builds };
    } catch {
      return { success: false, builds: [] };
    }
  }

  syncWishlist(wishlistIds) {
    const set = Array.from(new Set(wishlistIds));
    localStorage.setItem('90p_wishlist', JSON.stringify(set));
    return { success: true, wishlist: set };
  }
}

window.PLAYER_AUTH = new PlayerAuthManager();

function updateAuthNavUI() {
  const user = window.PLAYER_AUTH.getCurrentUser();
  const authBtn = document.getElementById('navAuth');
  if (authBtn) {
    if (user) {
      authBtn.innerHTML = `<span style="font-family:var(--fm);font-size:0.75rem;font-weight:700;color:var(--volt);background:var(--volt-dim);padding:3px 8px;border-radius:12px;border:1px solid var(--volt-line)">${(user.user_metadata?.callsign || user.email.split('@')[0]).slice(0, 10).toUpperCase()}</span>`;
      authBtn.title = `Player Locker (${user.email})`;
    } else {
      authBtn.innerHTML = `<i data-lucide="user"></i>`;
      authBtn.title = 'Player Locker & Auth';
      if (window.lucide) lucide.createIcons();
    }
  }
}

// =============================================================================
// 3. PAYMENT GATEWAY ENGINE & CANVAS INVOICE (window.PAYMENT_ENGINE)
// =============================================================================
class PaymentEngine {
  constructor(options = {}) {
    this.secret = options.secret || 'sim_client_hmac_token';
    this.simulationMode = options.simulationMode !== false;
  }

  generateHmacSignature(orderId, paymentId, secret = this.secret) {
    const payload = `${orderId || ''}|${paymentId || ''}|${secret || ''}`;
    let h1 = 0xdeadbeef, h2 = 0x41c6ce57;
    for (let i = 0; i < payload.length; i++) {
      const ch = payload.charCodeAt(i);
      h1 = Math.imul(h1 ^ ch, 2654435761);
      h2 = Math.imul(h2 ^ ch, 1597334677);
    }
    h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909);
    h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909);
    let hex = '';
    for (let b = 0; b < 8; b++) {
      const p1 = (Math.imul(h1 + b * 0x9e3779b9, 0x85ebca6b) >>> 0).toString(16).padStart(8, '0');
      hex += p1;
    }
    return hex.slice(0, 64).padStart(64, '0');
  }

  verifySignature(orderId, paymentId, signature, secret = this.secret) {
    if (!orderId || !paymentId || !signature) return false;
    const expected = this.generateHmacSignature(orderId, paymentId, secret);
    return signature === expected;
  }

  async initiatePayment(orderData, method = 'SIMULATION') {
    const upper = String(method || 'SIMULATION').toUpperCase();
    if (upper === 'RAZORPAY') return this.initiateRazorpay(orderData);
    if (upper === 'STRIPE') return this.initiateStripe(orderData);
    if (upper === 'UPI_QR' || upper === 'UPI') return this.initiateUpiQr(orderData);
    return this.simulateSandboxPayment(orderData, upper);
  }

  async initiateRazorpay(orderData) {
    const orderId = orderData.id || `90S-${Math.random().toString(36).slice(2, 8).toUpperCase()}`;
    const paymentId = `pay_rzp_${Math.random().toString(36).slice(2, 10)}`;
    const signature = this.generateHmacSignature(orderId, paymentId);
    return {
      success: true,
      gateway: 'RAZORPAY',
      orderId,
      paymentId,
      signature,
      razorpay_signature: signature,
      verified: this.verifySignature(orderId, paymentId, signature)
    };
  }

  async initiateStripe(orderData) {
    const orderId = orderData.id || `90S-${Math.random().toString(36).slice(2, 8).toUpperCase()}`;
    const paymentIntentId = `pi_stripe_${Date.now()}_sim`;
    return {
      success: true,
      gateway: 'STRIPE',
      orderId,
      paymentIntentId,
      paymentId: paymentIntentId,
      status: 'succeeded'
    };
  }

  async initiateUpiQr(orderData) {
    const orderId = orderData.id || `90S-${Math.random().toString(36).slice(2, 8).toUpperCase()}`;
    const paymentId = `upi_${Date.now()}_sim`;
    const signature = this.generateHmacSignature(orderId, paymentId);
    return {
      success: true,
      gateway: 'UPI_QR',
      orderId,
      paymentId,
      signature,
      verified: true
    };
  }

  async simulateSandboxPayment(orderData, method = 'SIMULATION') {
    const orderId = orderData.id || `90S-${Math.random().toString(36).slice(2, 8).toUpperCase()}`;
    const paymentId = `pay_sim_${Date.now()}`;
    const signature = this.generateHmacSignature(orderId, paymentId);
    return {
      success: true,
      gateway: method,
      orderId,
      paymentId,
      signature,
      verified: true
    };
  }

  calculateInvoiceBreakdown(order) {
    const subtotal = order.subtotal || (order.totals && order.totals.subtotal) || 0;
    const discountAmount = order.discountAmount || (order.totals && order.totals.discount) || 0;
    const taxableSubtotal = Math.max(0, subtotal - discountAmount);
    const gstRate = 0.18;
    const gstAmount = Math.round(taxableSubtotal * gstRate);
    const shipping = order.freeShipping ? 0 : ((order.totals && order.totals.shipping) || order.shippingFee || 0);
    const grandTotal = taxableSubtotal + shipping;

    return {
      invoiceNumber: 'INV-' + (order.id || '90S-TEMP'),
      date: new Date().toISOString(),
      subtotal,
      discountAmount,
      taxableSubtotal,
      gstRate: '18% IGST',
      gstAmount,
      shipping,
      grandTotal,
      currency: 'INR (₹)'
    };
  }

  generateInvoiceCanvas(order) {
    const canvas = document.createElement('canvas');
    canvas.width = 800;
    canvas.height = 1100;
    const ctx = canvas.getContext('2d');

    // Background
    ctx.fillStyle = '#0a0b0c';
    ctx.fillRect(0, 0, 800, 1100);

    // Decorative Borders
    ctx.strokeStyle = '#c8ff2e';
    ctx.lineWidth = 4;
    ctx.strokeRect(20, 20, 760, 1060);

    ctx.strokeStyle = 'rgba(255,255,255,0.1)';
    ctx.lineWidth = 1;
    ctx.strokeRect(30, 30, 740, 1040);

    // Header
    ctx.fillStyle = '#c8ff2e';
    ctx.font = 'bold 36px Anton, sans-serif';
    ctx.fillText('90+ SUPPLY', 50, 80);

    ctx.fillStyle = '#98a0a4';
    ctx.font = '12px "JetBrains Mono", monospace';
    ctx.fillText('FOOTBALL PERFORMANCE PLATFORM — TAX INVOICE', 50, 105);
    ctx.fillText('GSTIN: 29AAECN9090P1Z8 | HSN: 950662', 50, 125);

    // Invoice Meta
    ctx.fillStyle = '#f3f4f1';
    ctx.font = 'bold 16px "Space Grotesk", sans-serif';
    ctx.fillText(`INVOICE: ${order.id || '90S-ORD'}`, 520, 80);
    ctx.font = '13px "JetBrains Mono", monospace';
    ctx.fillStyle = '#98a0a4';
    ctx.fillText(`DATE: ${order.dateStr || new Date().toLocaleDateString('en-IN')}`, 520, 105);
    ctx.fillText(`PAYMENT: ${(order.paymentMethod || 'PAID').toUpperCase()}`, 520, 125);

    // Divider
    ctx.strokeStyle = 'rgba(255,255,255,0.15)';
    ctx.beginPath(); ctx.moveTo(50, 150); ctx.lineTo(750, 150); ctx.stroke();

    // Customer & Logistics Info
    ctx.fillStyle = '#c8ff2e';
    ctx.font = 'bold 13px "JetBrains Mono", monospace';
    ctx.fillText('BILLED & SHIPPED TO:', 50, 180);

    ctx.fillStyle = '#f3f4f1';
    ctx.font = '14px "Space Grotesk", sans-serif';
    const cust = order.customer || {};
    ctx.fillText(`${cust.name || 'Player Athlete'} (${cust.phone || '—'})`, 50, 205);
    ctx.fillStyle = '#98a0a4';
    ctx.fillText(`${cust.address || 'Address'}`, 50, 225);
    ctx.fillText(`${cust.city || 'Bengaluru'}, ${cust.state || 'KA'} — ${cust.pin || '560001'}`, 50, 245);
    ctx.fillText(`Courier AWB: ${order.courier || 'Bluedart'} (${order.trackingNumber || 'BD909090IN'})`, 50, 265);

    // Items Table Header
    ctx.fillStyle = 'rgba(200, 255, 46, 0.08)';
    ctx.fillRect(50, 300, 700, 32);
    ctx.fillStyle = '#c8ff2e';
    ctx.font = 'bold 12px "JetBrains Mono", monospace';
    ctx.fillText('ITEM DESCRIPTION', 65, 322);
    ctx.fillText('QTY', 480, 322);
    ctx.fillText('RATE', 560, 322);
    ctx.fillText('AMOUNT', 660, 322);

    // Items List
    let y = 360;
    const items = order.items || [];
    ctx.font = '13px "Space Grotesk", sans-serif';
    items.forEach((item, idx) => {
      ctx.fillStyle = '#f3f4f1';
      ctx.fillText(`${idx + 1}. ${(item.name || item.id).slice(0, 42)}`, 65, y);
      ctx.fillStyle = '#98a0a4';
      ctx.fillText(`${item.qty || 1}`, 490, y);
      ctx.fillText(`₹${item.price}`, 560, y);
      ctx.fillStyle = '#f3f4f1';
      ctx.fillText(`₹${(item.price || 0) * (item.qty || 1)}`, 660, y);
      y += 28;
    });

    // Subtotal Breakdown Box
    y = Math.max(y + 20, 600);
    ctx.strokeStyle = 'rgba(255,255,255,0.15)';
    ctx.strokeRect(450, y, 300, 180);

    const totals = order.totals || {};
    ctx.font = '13px "Space Grotesk", sans-serif';
    ctx.fillStyle = '#98a0a4';
    ctx.fillText('Subtotal:', 470, y + 30);
    ctx.fillStyle = '#f3f4f1';
    ctx.fillText(`₹${totals.subtotal || order.subtotal || 0}`, 670, y + 30);

    ctx.fillStyle = '#98a0a4';
    ctx.fillText('Discount Promo:', 470, y + 60);
    ctx.fillStyle = '#ff7a6b';
    ctx.fillText(`-₹${totals.discount || order.discount_amount || 0}`, 670, y + 60);

    ctx.fillStyle = '#98a0a4';
    ctx.fillText('Shipping & Handling:', 470, y + 90);
    ctx.fillStyle = '#f3f4f1';
    ctx.fillText((totals.shipping === 0 || order.shipping_fee === 0) ? 'FREE' : `₹${totals.shipping || order.shipping_fee || 0}`, 670, y + 90);

    ctx.fillStyle = '#98a0a4';
    ctx.fillText('GST (18% IGST included):', 470, y + 120);
    ctx.fillStyle = '#f3f4f1';
    ctx.fillText(`₹${totals.tax || Math.round(((totals.subtotal || order.subtotal || 0) - (totals.discount || order.discount_amount || 0)) * 0.18)}`, 670, y + 120);

    ctx.fillStyle = '#c8ff2e';
    ctx.font = 'bold 18px "Space Grotesk", sans-serif';
    ctx.fillText('TOTAL PAID:', 470, y + 160);
    ctx.fillText(`₹${totals.total || order.total_amount || order.total || 0}`, 660, y + 160);

    // Cryptographic Seal & Signature
    ctx.strokeStyle = '#c8ff2e';
    ctx.lineWidth = 1.5;
    ctx.strokeRect(50, y + 30, 320, 120);
    ctx.fillStyle = '#c8ff2e';
    ctx.font = 'bold 12px "JetBrains Mono", monospace';
    ctx.fillText('CRYPTOGRAPHIC SIGNATURE SEAL', 65, y + 55);
    ctx.fillStyle = '#98a0a4';
    ctx.font = '9px "JetBrains Mono", monospace';
    const sig = order.razorpay_signature || order.signature || this.generateHmacSignature(order.id || '90S', 'pay_sim');
    ctx.fillText(`HMAC-SHA256: ${sig.slice(0, 32)}`, 65, y + 80);
    ctx.fillText(`${sig.slice(32, 64)}`, 65, y + 95);
    ctx.fillStyle = '#7fd4ff';
    ctx.fillText('STATUS: CRYPTOGRAPHICALLY VERIFIED & SETTLED', 65, y + 125);

    // Footer
    ctx.fillStyle = '#6b7276';
    ctx.font = '11px "Space Grotesk", sans-serif';
    ctx.fillText('Thank you for playing with 90+ SUPPLY gear. Refuse ordinary. Official matchday warranty valid for 180 days.', 50, 1030);

    return canvas;
  }

  downloadCanvasInvoice(order) {
    try {
      const canvas = this.generateInvoiceCanvas(order);
      const url = canvas.toDataURL('image/png');
      const a = document.createElement('a');
      a.href = url;
      a.download = `Invoice_${order.id || '90S'}.png`;
      document.body.appendChild(a);
      a.click();
      a.remove();
      toast('Digital Tax Invoice PNG downloaded!', 'download');
    } catch {
      downloadOrderInvoice(order);
    }
  }
}

window.PAYMENT_ENGINE = new PaymentEngine();

/* 2.2  SAFE localStorage WRAPPER All client state persists in localStorage with try/catch guards so the app degrades gracefully in incognito or full-storage mode. */
const LS = {
  get(key, fallback = null) {
    try {
      const raw = localStorage.getItem(`90p_${key}`);
      return raw !== null ? JSON.parse(raw) : fallback;
    } catch { return fallback; }
  },
  set(key, val) {
    try { localStorage.setItem(`90p_${key}`, JSON.stringify(val)); }
    catch { /* storage full — silent fail */ }
  },
  del(key) {
    try { localStorage.removeItem(`90p_${key}`); }
    catch { /* silent */ }
  }
};

