/* 2.6  TOAST NOTIFICATION SYSTEM Stacked glass toasts at bottom-center with auto-dismiss. */
function toast(msg, icon = 'check') {
  const el = document.createElement('div');
  el.className = 'toast';
  el.innerHTML = `<i data-lucide="${icon}"></i><span>${msg}</span>`;
  DOM.toasts.appendChild(el);
  if (window.lucide) lucide.createIcons({ nodes: [el] });
  playSound('pop');
  setTimeout(() => {
    el.classList.add('out');
    el.addEventListener('animationend', () => el.remove());
  }, TOAST_MS);
}

/* 2.7  WEB AUDIO API — PROCEDURAL SOUND ENGINE All UI sounds are synthesized at runtime. Zero audio files. */
function initAudio() {
  if (STATE.audioCtx) return;
  try {
    STATE.audioCtx = new (window.AudioContext || window.webkitAudioContext)();
    STATE.audioGain = STATE.audioCtx.createGain();
    STATE.audioGain.gain.value = 0.15;
    STATE.audioGain.connect(STATE.audioCtx.destination);
  } catch { STATE.audioEnabled = false; }
}

function playSound(type) {
  if (!STATE.audioEnabled || !STATE.audioCtx) return;
  const ctx = STATE.audioCtx;
  const gain = STATE.audioGain;
  const now = ctx.currentTime;
  try {
    switch (type) {
      case 'pop': {
        const osc = ctx.createOscillator();
        const g = ctx.createGain();
        osc.type = 'sine';
        osc.frequency.setValueAtTime(880, now);
        osc.frequency.exponentialRampToValueAtTime(440, now + 0.08);
        g.gain.setValueAtTime(0.12, now);
        g.gain.exponentialRampToValueAtTime(0.001, now + 0.12);
        osc.connect(g).connect(gain);
        osc.start(now);
        osc.stop(now + 0.12);
        break;
      }
      case 'click': {
        const osc = ctx.createOscillator();
        const g = ctx.createGain();
        osc.type = 'square';
        osc.frequency.setValueAtTime(1200, now);
        osc.frequency.exponentialRampToValueAtTime(600, now + 0.04);
        g.gain.setValueAtTime(0.06, now);
        g.gain.exponentialRampToValueAtTime(0.001, now + 0.05);
        osc.connect(g).connect(gain);
        osc.start(now);
        osc.stop(now + 0.05);
        break;
      }
      case 'success': {
        [660, 880, 1100].forEach((freq, i) => {
          const osc = ctx.createOscillator();
          const g = ctx.createGain();
          osc.type = 'sine';
          osc.frequency.value = freq;
          g.gain.setValueAtTime(0, now + i * 0.08);
          g.gain.linearRampToValueAtTime(0.1, now + i * 0.08 + 0.02);
          g.gain.exponentialRampToValueAtTime(0.001, now + i * 0.08 + 0.18);
          osc.connect(g).connect(gain);
          osc.start(now + i * 0.08);
          osc.stop(now + i * 0.08 + 0.18);
        });
        break;
      }
      case 'error': {
        const osc = ctx.createOscillator();
        const g = ctx.createGain();
        osc.type = 'sawtooth';
        osc.frequency.setValueAtTime(220, now);
        osc.frequency.linearRampToValueAtTime(110, now + 0.15);
        g.gain.setValueAtTime(0.08, now);
        g.gain.exponentialRampToValueAtTime(0.001, now + 0.2);
        osc.connect(g).connect(gain);
        osc.start(now);
        osc.stop(now + 0.2);
        break;
      }
      case 'bounce': {
        const osc = ctx.createOscillator();
        const g = ctx.createGain();
        osc.type = 'sine';
        osc.frequency.setValueAtTime(200, now);
        osc.frequency.exponentialRampToValueAtTime(80, now + 0.3);
        g.gain.setValueAtTime(0.15, now);
        g.gain.exponentialRampToValueAtTime(0.001, now + 0.35);
        osc.connect(g).connect(gain);
        osc.start(now);
        osc.stop(now + 0.35);
        break;
      }
      case 'whoosh': {
        const bufferSize = ctx.sampleRate * 0.12;
        const buffer = ctx.createBuffer(1, bufferSize, ctx.sampleRate);
        const data = buffer.getChannelData(0);
        for (let i = 0; i < bufferSize; i++) data[i] = (Math.random() * 2 - 1) * (1 - i / bufferSize);
        const src = ctx.createBufferSource();
        const filt = ctx.createBiquadFilter();
        const g = ctx.createGain();
        src.buffer = buffer;
        filt.type = 'bandpass';
        filt.frequency.setValueAtTime(2000, now);
        filt.frequency.exponentialRampToValueAtTime(500, now + 0.1);
        filt.Q.value = 1.2;
        g.gain.setValueAtTime(0.08, now);
        g.gain.exponentialRampToValueAtTime(0.001, now + 0.12);
        src.connect(filt).connect(g).connect(gain);
        src.start(now);
        break;
      }
      case 'coin': {
        [1318, 1568, 2093].forEach((freq, i) => {
          const osc = ctx.createOscillator();
          const g = ctx.createGain();
          osc.type = 'sine';
          osc.frequency.value = freq;
          g.gain.setValueAtTime(0, now + i * 0.06);
          g.gain.linearRampToValueAtTime(0.08, now + i * 0.06 + 0.01);
          g.gain.exponentialRampToValueAtTime(0.001, now + i * 0.06 + 0.15);
          osc.connect(g).connect(gain);
          osc.start(now + i * 0.06);
          osc.stop(now + i * 0.06 + 0.15);
        });
        break;
      }
      case 'kick': {
        const osc = ctx.createOscillator();
        const g = ctx.createGain();
        osc.type = 'sine';
        osc.frequency.setValueAtTime(400, now);
        osc.frequency.exponentialRampToValueAtTime(30, now + 0.25);
        g.gain.setValueAtTime(0.2, now);
        g.gain.exponentialRampToValueAtTime(0.001, now + 0.3);
        osc.connect(g).connect(gain);
        osc.start(now);
        osc.stop(now + 0.3);
        break;
      }
    }
  } catch { /* audio error — silent */ }
}

/* Audio toggle button */
DOM.navAudio.addEventListener('click', () => {
  initAudio();
  STATE.audioEnabled = !STATE.audioEnabled;
  DOM.audioIcon.setAttribute('data-lucide', STATE.audioEnabled ? 'volume-2' : 'volume-x');
  if (window.lucide) lucide.createIcons({ nodes: [DOM.navAudio] });
  toast(STATE.audioEnabled ? 'Sound effects enabled' : 'Sound effects muted', STATE.audioEnabled ? 'volume-2' : 'volume-x');
});

/* 2.8  THREE.JS STAGE FACTORY Creates managed WebGL renderer + scene + camera combos. All stages register in a global array. IntersectionObserver pauses rendering when scrolled out of view to save GPU. */
const STAGES = [];
let globalRendererCount = 0;

class Stage {
  constructor(canvas, { fov = 45, near = 0.1, far = 100, antialias = true, alpha = true, dpr = null } = {}) {
    this.canvas = canvas;
    this.id = globalRendererCount++;
    this.alive = true;
    this.visible = true; // Always start visible for instant render
    this.needsRender = true;
    this.clock = new THREE.Clock();
    this.animCallbacks = [];

    /* Renderer */
    this.renderer = new THREE.WebGLRenderer({
      canvas,
      antialias: antialias && window.innerWidth >= 900,
      alpha,
      powerPreference: 'high-performance',
    });
    const effectiveDpr = dpr || Math.min(window.devicePixelRatio || 1, window.innerWidth < 800 ? 1 : 1.25);
    this.renderer.setPixelRatio(effectiveDpr);
    this.renderer.outputColorSpace = THREE.SRGBColorSpace;
    this.renderer.toneMapping = THREE.ACESFilmicToneMapping;
    this.renderer.toneMappingExposure = 1.15;
    this.renderer.shadowMap.enabled = false;
    this.renderer.shadowMap.type = THREE.PCFSoftShadowMap;

    /* Scene */
    this.scene = new THREE.Scene();

    /* Camera */
    const aspect = canvas.clientWidth / canvas.clientHeight || (window.innerWidth / window.innerHeight) || 1.6;
    this.camera = new THREE.PerspectiveCamera(fov, aspect, near, far);

    /* Resize handling */
    this._resizeObserver = new ResizeObserver(this._onResize.bind(this));
    this._resizeObserver.observe(canvas.parentElement || canvas);
    this._onResize();

    /* Visibility observer — pause when far offscreen */
    this._intObs = new IntersectionObserver(entries => {
      if (entries && entries[0]) {
        this.visible = entries[0].isIntersecting;
      }
    }, { threshold: 0.01, rootMargin: '100px 0px 100px 0px' });
    this._intObs.observe(canvas);

    STAGES.push(this);
  }

  _onResize() {
    const parent = this.canvas.parentElement || this.canvas;
    let w = parent.clientWidth || window.innerWidth;
    let h = parent.clientHeight || window.innerHeight;
    if (w === 0) w = 800;
    if (h === 0) h = 600;
    const dpr = this.renderer.getPixelRatio() || 1;
    this.canvas.width = w * dpr;
    this.canvas.height = h * dpr;
    this.canvas.style.width = w + 'px';
    this.canvas.style.height = h + 'px';
    this.renderer.setSize(w, h, false);
    this.camera.aspect = w / h;
    this.camera.updateProjectionMatrix();
    this.needsRender = true;
  }

  onAnim(cb) { this.animCallbacks.push(cb); }

  tick() {
    if (!this.alive || !this.visible) return;
    const dt = this.clock.getDelta();
    const elapsed = this.clock.getElapsedTime();
    for (const cb of this.animCallbacks) {
      try { cb(dt, elapsed); } catch(e) {}
    }
    try {
      this.renderer.render(this.scene, this.camera);
    } catch(e) {}
  }

  dispose() {
    this.alive = false;
    this._resizeObserver.disconnect();
    this._intObs.disconnect();
    this.renderer.dispose();
    const idx = STAGES.indexOf(this);
    if (idx !== -1) STAGES.splice(idx, 1);
  }
}

/* Master animation loop — drives ALL stages */
function masterLoop() {
  if (document.hidden) return;
  requestAnimationFrame(masterLoop);
  for (const stage of STAGES) stage.tick();
}
masterLoop();
document.addEventListener('visibilitychange', () => {
  if (!document.hidden) requestAnimationFrame(masterLoop);
});

/* 2.9  PROCEDURAL TEXTURE GENERATOR Generates football panel textures entirely on an offscreen canvas. Each colorway produces a unique albedo map at runtime. Zero external image files needed. */
const TEX_CACHE = new Map();

function generateBallTexture(opts = {}) {
  const {
    width = 512,
    height = 256,
    baseColor = '#1a1d21',
    panelColor = '#c8ff2e',
    seamColor = '#333840',
    seamWidth = 2,
    dimpleIntensity = 0.12,
    glossHighlight = true,
    label = '',
    labelNumber = '',
    stampFont = '600 42px "Space Grotesk", sans-serif',
    stampColor = '#ffffff',
    logoText = '90+',
    logoFont = 'bold 72px "Anton", sans-serif',
    logoColor = '#c8ff2e',
  } = opts;

  const cacheKey = JSON.stringify(opts);
  if (TEX_CACHE.has(cacheKey)) return TEX_CACHE.get(cacheKey);

  const c = new OffscreenCanvas(width, height);
  const ctx = c.getContext('2d');

  /* Base fill */
  ctx.fillStyle = baseColor;
  ctx.fillRect(0, 0, width, height);

  /* Subtle noise grain */
  const imgData = ctx.getImageData(0, 0, width, height);
  const px = imgData.data;
  for (let i = 0; i < px.length; i += 4) {
    const noise = (Math.random() - 0.5) * 18;
    px[i]     = clamp(px[i] + noise, 0, 255);
    px[i + 1] = clamp(px[i + 1] + noise, 0, 255);
    px[i + 2] = clamp(px[i + 2] + noise, 0, 255);
  }
  ctx.putImageData(imgData, 0, 0);

  /* Pentagon panel pattern */
  const panelRows = 4;
  const panelCols = 6;
  const pw = width / panelCols;
  const ph = height / panelRows;

  ctx.strokeStyle = seamColor;
  ctx.lineWidth = seamWidth;
  ctx.lineJoin = 'round';

  for (let row = 0; row < panelRows; row++) {
    for (let col = 0; col < panelCols; col++) {
      const cx2 = col * pw + pw / 2;
      const cy2 = row * ph + ph / 2;
      const isAccent = (row + col) % 3 === 0;

      if (isAccent) {
        /* Filled accent panel */
        ctx.beginPath();
        const sides = 5;
        const r = pw * 0.32;
        for (let s = 0; s < sides; s++) {
          const angle = (TAU / sides) * s - PI / 2 + (col % 2) * 0.3;
          const px2 = cx2 + r * Math.cos(angle);
          const py2 = cy2 + r * Math.sin(angle);
          s === 0 ? ctx.moveTo(px2, py2) : ctx.lineTo(px2, py2);
        }
        ctx.closePath();
        ctx.fillStyle = panelColor;
        ctx.fill();
        ctx.stroke();
      } else {
        /* Hexagonal seam outline */
        ctx.beginPath();
        const sides = 6;
        const r = pw * 0.36;
        for (let s = 0; s < sides; s++) {
          const angle = (TAU / sides) * s + (row % 2) * (PI / 6);
          const px2 = cx2 + r * Math.cos(angle);
          const py2 = cy2 + r * Math.sin(angle);
          s === 0 ? ctx.moveTo(px2, py2) : ctx.lineTo(px2, py2);
        }
        ctx.closePath();
        ctx.stroke();
      }
    }
  }

  /* Micro-dimple overlay */
  if (dimpleIntensity > 0) {
    for (let i = 0; i < 800; i++) {
      const dx = Math.random() * width;
      const dy = Math.random() * height;
      const dr = Math.random() * 2.8 + 0.5;
      ctx.beginPath();
      ctx.arc(dx, dy, dr, 0, TAU);
      ctx.fillStyle = `rgba(0,0,0,${dimpleIntensity * Math.random()})`;
      ctx.fill();
    }
  }

  /* Gloss specular highlight band */
  if (glossHighlight) {
    const grad = ctx.createLinearGradient(0, height * 0.2, 0, height * 0.5);
    grad.addColorStop(0, 'rgba(255,255,255,0)');
    grad.addColorStop(0.3, 'rgba(255,255,255,0.06)');
    grad.addColorStop(0.7, 'rgba(255,255,255,0.04)');
    grad.addColorStop(1, 'rgba(255,255,255,0)');
    ctx.fillStyle = grad;
    ctx.fillRect(0, 0, width, height);
  }

  /* 90+ Logo stamp */
  ctx.save();
  ctx.font = logoFont;
  ctx.fillStyle = logoColor;
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.globalAlpha = 0.85;
  ctx.fillText(logoText, width * 0.5, height * 0.38);
  ctx.restore();

  /* Custom player name stamp */
  if (label) {
    ctx.save();
    ctx.font = stampFont;
    ctx.fillStyle = stampColor;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.globalAlpha = 0.92;
    ctx.fillText(label.toUpperCase(), width * 0.5, height * 0.58);
    ctx.restore();
  }

  /* Custom number stamp */
  if (labelNumber) {
    ctx.save();
    ctx.font = `bold 78px "Anton", sans-serif`;
    ctx.fillStyle = panelColor;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.globalAlpha = 0.75;
    ctx.fillText(labelNumber, width * 0.5, height * 0.76);
    ctx.restore();
  }

  /* Equator seam line */
  ctx.beginPath();
  ctx.moveTo(0, height * 0.5);
  ctx.lineTo(width, height * 0.5);
  ctx.strokeStyle = seamColor;
  ctx.lineWidth = 1.5;
  ctx.globalAlpha = 0.5;
  ctx.stroke();
  ctx.globalAlpha = 1;

  /* Create THREE.js texture */
  const bmp = c.transferToImageBitmap();
  const tex = new THREE.CanvasTexture(bmp);
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.wrapS = THREE.RepeatWrapping;
  tex.wrapT = THREE.ClampToEdgeWrapping;
  tex.anisotropy = 4;
  tex.needsUpdate = true;

  TEX_CACHE.set(cacheKey, tex);
  return tex;
}

/* Procedural normal map for surface detail */
function generateNormalMap(width = 512, height = 256) {
  const c = new OffscreenCanvas(width, height);
  const ctx = c.getContext('2d');

  /* Base neutral normal (flat = rgb(128,128,255)) */
  ctx.fillStyle = '#8080ff';
  ctx.fillRect(0, 0, width, height);

  /* Perturb with dimple-like normals */
  const imgData = ctx.getImageData(0, 0, width, height);
  const px = imgData.data;
  for (let i = 0; i < px.length; i += 4) {
    const nx = (Math.random() - 0.5) * 16;
    const ny = (Math.random() - 0.5) * 16;
    px[i]     = clamp(128 + nx, 0, 255);
    px[i + 1] = clamp(128 + ny, 0, 255);
    /* z-component stays high for mostly-flat surface */
  }
  ctx.putImageData(imgData, 0, 0);

  /* Add structured seam bumps */
  const panelCols = 6;
  const panelRows = 4;
  const pw = width / panelCols;
  const ph = height / panelRows;
  for (let r = 0; r < panelRows; r++) {
    for (let ci = 0; ci < panelCols; ci++) {
      const cx2 = ci * pw + pw / 2;
      const cy2 = r * ph + ph / 2;
      const sides = (r + ci) % 3 === 0 ? 5 : 6;
      const radius = pw * ((r + ci) % 3 === 0 ? 0.32 : 0.36);
      ctx.beginPath();
      for (let s = 0; s < sides; s++) {
        const angle = (TAU / sides) * s - PI / 2;
        const px2 = cx2 + radius * Math.cos(angle);
        const py2 = cy2 + radius * Math.sin(angle);
        s === 0 ? ctx.moveTo(px2, py2) : ctx.lineTo(px2, py2);
      }
      ctx.closePath();
      ctx.strokeStyle = '#6060ff';
      ctx.lineWidth = 3;
      ctx.stroke();
    }
  }

  const bmp = c.transferToImageBitmap();
  const tex = new THREE.CanvasTexture(bmp);
  tex.wrapS = THREE.RepeatWrapping;
  tex.wrapT = THREE.ClampToEdgeWrapping;
  return tex;
}

