/* Universal 3D Equipment Dispatcher */
function buildProductMesh(product) {
  if (!product) return buildBallMesh(1.0);

  const cat = product.category;
  const id = product.id;

  if (cat === 'balls' || cat === 'training' || cat === 'skills') {
    return buildBallMesh(1.0, product.colorwayIdx || 0, product.finishIdx || 0, product.name.slice(0, 10), '90');
  } else if (cat === 'guards') {
    return buildShinGuardMesh();
  } else if (cat === 'gloves') {
    return buildGloveMesh();
  } else if (cat === 'bags') {
    return buildBagMesh();
  } else if (cat === 'socks' || cat === 'sleeves') {
    const isVolt = product.name.toLowerCase().includes('volt');
    const isWhite = product.name.toLowerCase().includes('white');
    const color = isVolt ? 0xc8ff2e : isWhite ? 0xf0f0f0 : 0x1a1d20;
    return buildGripSockMesh({ color });
  } else if (cat === 'agility') {
    if (id.includes('cones')) return buildConeMesh({ color: 0xc8ff2e });
    if (id.includes('hurdle')) return buildHurdleMesh();
    if (id.includes('ladder')) return buildLadderMesh();
    return buildConeMesh({ color: 0xfb923c });
  } else if (cat === 'recovery') {
    return buildRollerMesh();
  } else if (cat === 'accessories') {
    if (id.includes('gauge')) return buildGaugeMesh();
    return buildBallMesh(0.8, 0, 0, 'PRO ACC', '90');
  }

  return buildBallMesh(1.0);
}

/* 2.12  STANDARD LIGHTING RIG Reusable 3-point lighting setup for all 3D stages. */
function addLightingRig(scene, opts = {}) {
  const { intensity = 1.0, shadowRes = 1024, ambient = 0.2 } = opts;

  /* Ambient base */
  const amb = new THREE.AmbientLight(0xffffff, ambient);
  scene.add(amb);

  /* Key light — warm top-right */
  const key = new THREE.DirectionalLight(0xfff8e8, 1.2 * intensity);
  key.position.set(4, 6, 3);
  key.castShadow = true;
  key.shadow.mapSize.set(shadowRes, shadowRes);
  key.shadow.camera.near = 0.5;
  key.shadow.camera.far = 30;
  key.shadow.camera.left = -5;
  key.shadow.camera.right = 5;
  key.shadow.camera.top = 5;
  key.shadow.camera.bottom = -5;
  key.shadow.bias = -0.002;
  key.shadow.radius = 4;
  scene.add(key);

  /* Fill light — cool left */
  const fill = new THREE.DirectionalLight(0xd0e8ff, 0.5 * intensity);
  fill.position.set(-3, 2, -2);
  scene.add(fill);

  /* Rim/back light — volt accent */
  const rim = new THREE.PointLight(0xc8ff2e, 0.6 * intensity, 20);
  rim.position.set(-1, 3, -5);
  scene.add(rim);

  /* Bottom bounce — subtle ground reflection */
  const bounce = new THREE.HemisphereLight(0x1a1d21, 0x0a0b0c, 0.3 * intensity);
  scene.add(bounce);

  return { amb, key, fill, rim, bounce };
}

/* 2.13  GROUND PLANE (shadow receiver) */
function addGround(scene, y = -1.6) {
  const geo = new THREE.PlaneGeometry(20, 20);
  const mat = new THREE.ShadowMaterial({ opacity: 0.35 });
  const plane = new THREE.Mesh(geo, mat);
  plane.rotation.x = -PI / 2;
  plane.position.y = y;
  plane.receiveShadow = true;
  scene.add(plane);
  return plane;
}

/* 2.14  ENVIRONMENT MAP BUILDER Generates a simple procedural cubemap for reflections. */
function buildEnvMap(renderer) {
  if (!renderer) return null;
  try {
    const pmremGen = new THREE.PMREMGenerator(renderer);
    pmremGen.compileEquirectangularShader();

    /* Procedural gradient scene for environment */
    const envScene = new THREE.Scene();
    envScene.background = new THREE.Color(0x0d0e12);

    /* Add some colored area lights to give reflections variation */
    const envLights = [
      { color: 0xffffff, intensity: 0.6, pos: [0, 5, 0] },
      { color: 0xc8ff2e, intensity: 0.3, pos: [-3, 2, -3] },
      { color: 0xd0e8ff, intensity: 0.2, pos: [3, 1, 4] },
    ];
    envLights.forEach(({ color, intensity, pos }) => {
      const l = new THREE.PointLight(color, intensity, 20);
      l.position.set(...pos);
      envScene.add(l);
    });

    /* Large sphere for backdrop */
    const bgGeo = new THREE.SphereGeometry(10, 32, 16);
    const bgMat = new THREE.MeshBasicMaterial({ color: 0x0e1014, side: THREE.BackSide });
    envScene.add(new THREE.Mesh(bgGeo, bgMat));

    const envMap = pmremGen.fromScene(envScene, 0.04).texture;
    pmremGen.dispose();
    return envMap;
  } catch (e) {
    console.warn('PMREM procedural map fallback:', e);
    return null;
  }
}

/* 2.15  SNAPSHOT RENDERER (SNAP) Renders product images at runtime on a dedicated offscreen WebGL context. Every product card image is a 3D snapshot. */
let snapRenderer = null;
let snapScene = null;
let snapCamera = null;
let snapEnv = null;

function initSnap() {
  if (snapRenderer) return;
  const c = new OffscreenCanvas(SNAP_SIZE, SNAP_SIZE);
  snapRenderer = new THREE.WebGLRenderer({ canvas: c, antialias: true, alpha: true, preserveDrawingBuffer: true });
  snapRenderer.setSize(SNAP_SIZE, SNAP_SIZE, false);
  snapRenderer.outputColorSpace = THREE.SRGBColorSpace;
  snapRenderer.toneMapping = THREE.ACESFilmicToneMapping;
  snapRenderer.toneMappingExposure = 1.2;

  snapScene = new THREE.Scene();
  snapCamera = new THREE.PerspectiveCamera(38, 1, 0.1, 50);
  snapCamera.position.set(0, 0.5, 3.8);
  snapCamera.lookAt(0, 0, 0);

  addLightingRig(snapScene, { intensity: 1.2, ambient: 0.3, shadowRes: 512 });
  snapEnv = buildEnvMap(snapRenderer);
  snapScene.environment = snapEnv;
}

function snapProduct(product) {
  initSnap();

  /* Clear previous objects */
  const toRemove = [];
  snapScene.traverse(child => {
    if (child.isMesh && child.userData.isProduct) toRemove.push(child);
  });
  toRemove.forEach(m => {
    m.geometry.dispose();
    if (m.material.map) m.material.map.dispose();
    m.material.dispose();
    snapScene.remove(m);
  });

  /* Build the product mesh */
  const cwIdx = product.colorwayIdx || 0;
  const finIdx = product.finishIdx || 0;
  const mesh = buildBallMesh(1.2, cwIdx, finIdx, '', '');
  mesh.userData.isProduct = true;
  mesh.rotation.y = product.snapAngle || 0.6;
  mesh.rotation.x = product.snapTilt || 0.15;
  snapScene.add(mesh);

  /* Render */
  snapRenderer.render(snapScene, snapCamera);

  /* Extract image via helper canvas */
  const c = snapRenderer.domElement;
  const bmp = c.transferToImageBitmap();
  const helper = document.createElement('canvas');
  helper.width = SNAP_SIZE;
  helper.height = SNAP_SIZE;
  const hCtx = helper.getContext('2d');
  hCtx.drawImage(bmp, 0, 0);
  const dataURL = helper.toDataURL('image/png');
  bmp.close();
  return dataURL;
}

/* Batch snapshot queue — runs async to avoid blocking UI */
const SNAP_QUEUE = [];
let snapRunning = false;
const SNAP_IO = ('IntersectionObserver' in window)
  ? new IntersectionObserver((entries) => {
      entries.forEach((entry) => {
        if (!entry.isIntersecting) return;
        const run = entry.target._lazySnap;
        if (typeof run === 'function') {
          entry.target._lazySnap = null;
          SNAP_IO.unobserve(entry.target);
          run();
        }
      });
    }, { rootMargin: '280px 0px', threshold: 0.01 })
  : null;

function applySnapImage(wrap, product, dataURL) {
  if (!wrap || !dataURL) return;
  wrap.innerHTML = `<img src="${dataURL}" alt="${escapeHtml(product.name || '')}" class="snap-img" loading="lazy" decoding="async" width="400" height="400" />`;
}

function lazyQueueSnap(product, wrapId) {
  const wrap = document.getElementById(wrapId);
  const run = () => queueSnap(product, (dataURL) => applySnapImage(document.getElementById(wrapId), product, dataURL));
  if (!wrap) { run(); return; }
  if (!SNAP_IO) { run(); return; }
  wrap._lazySnap = run;
  SNAP_IO.observe(wrap);
}

function initLazyImages() {
  const upgrade = (img) => {
    if (!img || img.tagName !== 'IMG') return;
    if (!img.hasAttribute('loading')) img.setAttribute('loading', 'lazy');
    if (!img.hasAttribute('decoding')) img.setAttribute('decoding', 'async');
    const src = img.getAttribute('data-src');
    if (src && !img.getAttribute('src')) {
      const io = new IntersectionObserver((ents) => {
        ents.forEach((e) => {
          if (!e.isIntersecting) return;
          const node = e.target;
          const next = node.getAttribute('data-src');
          if (next) {
            node.src = next;
            node.removeAttribute('data-src');
          }
          io.unobserve(node);
        });
      }, { rootMargin: '240px 0px' });
      io.observe(img);
    }
  };
  document.querySelectorAll('img').forEach(upgrade);
  if (typeof MutationObserver === 'function') {
    const mo = new MutationObserver((muts) => {
      muts.forEach((m) => {
        m.addedNodes.forEach((n) => {
          if (n.nodeType !== 1) return;
          if (n.tagName === 'IMG') upgrade(n);
          else if (n.querySelectorAll) n.querySelectorAll('img').forEach(upgrade);
        });
      });
    });
    mo.observe(document.body, { childList: true, subtree: true });
  }
}

async function queueSnap(product, callback) {
  SNAP_QUEUE.push({ product, callback });
  if (!snapRunning) processSnapQueue();
}

async function processSnapQueue() {
  snapRunning = true;
  while (SNAP_QUEUE.length > 0) {
    const { product, callback } = SNAP_QUEUE.shift();
    await raf();
    try {
      const url = snapProduct(product);
      callback(url);
    } catch (e) {
      console.warn('Snap failed for', product.name, e);
      callback(null);
    }
    if (SNAP_QUEUE.length > 0 && SNAP_QUEUE.length % 2 === 0) await wait(8);
  }
  snapRunning = false;
}

/* 2.16  HERO SCENE — FLOATING BALL WITH AMBIENT ANIMATION */
let heroStage = null;
let heroBall = null;

function initHero2DFallback() {
  const canvas = DOM.heroCanvas;
  if (!canvas) return;
  const ctx = canvas.getContext('2d');
  let angle = 0;
  let particles = Array.from({ length: 60 }, () => ({
    x: Math.random() * (window.innerWidth || 800),
    y: Math.random() * (window.innerHeight || 600),
    r: Math.random() * 2.5 + 1,
    vy: Math.random() * 0.5 + 0.2,
    alpha: Math.random() * 0.6 + 0.2
  }));

  function resize() {
    canvas.width = (canvas.parentElement?.clientWidth || window.innerWidth || 800) * (window.devicePixelRatio || 1);
    canvas.height = (canvas.parentElement?.clientHeight || window.innerHeight || 600) * (window.devicePixelRatio || 1);
  }
  window.addEventListener('resize', resize);
  resize();

  function draw() {
    const w = canvas.width;
    const h = canvas.height;
    ctx.clearRect(0, 0, w, h);

    // Floating volt particles
    ctx.fillStyle = '#c8ff2e';
    particles.forEach(p => {
      ctx.globalAlpha = p.alpha;
      ctx.beginPath();
      ctx.arc(p.x, p.y, p.r, 0, Math.PI * 2);
      ctx.fill();
      p.y -= p.vy;
      if (p.y < 0) p.y = h;
    });

    // 3D Sphere geometry
    const cx = w * 0.65;
    const cy = h * 0.48 + Math.sin(angle * 1.5) * 16;
    const r = Math.min(w, h) * 0.28;

    // Drop Shadow
    const shadowGrad = ctx.createRadialGradient(cx, cy + r * 1.15, 0, cx, cy + r * 1.15, r);
    shadowGrad.addColorStop(0, 'rgba(0,0,0,0.7)');
    shadowGrad.addColorStop(1, 'rgba(0,0,0,0)');
    ctx.globalAlpha = 0.8;
    ctx.fillStyle = shadowGrad;
    ctx.beginPath();
    ctx.ellipse(cx, cy + r * 1.15, r * 0.9, r * 0.2, 0, 0, Math.PI * 2);
    ctx.fill();

    // Sphere Shading Base
    ctx.globalAlpha = 1.0;
    const ballGrad = ctx.createRadialGradient(cx - r * 0.35, cy - r * 0.35, r * 0.05, cx, cy, r);
    ballGrad.addColorStop(0, '#383d42');
    ballGrad.addColorStop(0.5, '#16181b');
    ballGrad.addColorStop(1, '#08090a');
    ctx.fillStyle = ballGrad;
    ctx.beginPath();
    ctx.arc(cx, cy, r, 0, Math.PI * 2);
    ctx.fill();

    // Rotating Neon Seams & Hexagons
    ctx.save();
    ctx.beginPath();
    ctx.arc(cx, cy, r - 1, 0, Math.PI * 2);
    ctx.clip();

    ctx.strokeStyle = '#c8ff2e';
    ctx.lineWidth = 4;
    ctx.shadowColor = '#c8ff2e';
    ctx.shadowBlur = 18;

    for (let i = -2; i <= 2; i++) {
      const xOffset = ((angle * 60 + i * (r * 0.8)) % (r * 3)) - r * 1.5;
      ctx.beginPath();
      ctx.ellipse(cx + xOffset, cy, r * 0.45, r * 0.9, 0, 0, Math.PI * 2);
      ctx.stroke();
    }

    // Logo text
    ctx.fillStyle = '#ffffff';
    ctx.font = `bold ${Math.round(r * 0.16)}px "Anton", sans-serif`;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.shadowBlur = 0;
    ctx.fillText('90+ SUPPLY', cx, cy);

    ctx.restore();

    angle += 0.015;
    requestAnimationFrame(draw);
  }
  requestAnimationFrame(draw);
}

function initHero() {
  if (!DOM.heroCanvas) return;
  if (!THREE || !THREE.WebGLRenderer) {
    initHero2DFallback();
    return;
  }
  try {
    heroStage = new Stage(DOM.heroCanvas, { fov: 42, dpr: Math.min(window.devicePixelRatio || 1, 1.5) });
    const { scene, camera } = heroStage;

    camera.position.set(2.4, 1.2, 4.8);
    camera.lookAt(0, 0, 0);

    const env = buildEnvMap(heroStage.renderer);
    if (env) scene.environment = env;

    addLightingRig(scene, { intensity: 1.2, ambient: 0.35 });
    addGround(scene, -2.5);

    /* Particles — floating dust motes */
    const particleCount = 120;
    const particleGeo = new THREE.BufferGeometry();
    const positions = new Float32Array(particleCount * 3);
    for (let i = 0; i < particleCount; i++) {
      positions[i * 3]     = rand(-8, 8);
      positions[i * 3 + 1] = rand(-3, 5);
      positions[i * 3 + 2] = rand(-6, 6);
    }
    particleGeo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
    const particleMat = new THREE.PointsMaterial({
      color: 0xc8ff2e, size: 0.035, transparent: true, opacity: 0.45,
      sizeAttenuation: true, blending: THREE.AdditiveBlending, depthWrite: false,
    });
    scene.add(new THREE.Points(particleGeo, particleMat));

    heroBall = buildBallMesh(HERO_BALL_RADIUS, 0, 0, '90+ SUPPLY', '10');
    scene.add(heroBall);

    heroStage.onAnim((dt, elapsed) => {
      if (heroBall) {
        heroBall.rotation.y += 0.35 * dt;
        heroBall.rotation.x = Math.sin(elapsed * 0.5) * 0.12;
        heroBall.position.y = Math.sin(elapsed * 0.8) * 0.18;
      }
      const pos = particleGeo.attributes.position;
      for (let i = 0; i < particleCount; i++) {
        pos.array[i * 3 + 1] += 0.004;
        if (pos.array[i * 3 + 1] > 5) pos.array[i * 3 + 1] = -3;
      }
      pos.needsUpdate = true;
    });
  } catch (e) {
    console.warn('Hero 3D WebGL fallback triggered:', e);
    initHero2DFallback();
  }
}

/* 2.17  LAB SCENE — CONFIGURATOR WITH ORBIT CONTROLS */
let labStage = null;
let labBall = null;
let labControls = null;
let labLights = null;
let labLightMode = 0;
const LAB_LIGHT_MODES = ['Stadium', 'Sunset', 'Night', 'Studio'];

function initLab() {
  if (!DOM.labCanvas) return;
  if (labStage) return;
  try {
    labStage = new Stage(DOM.labCanvas, { fov: 40 });
    const { scene, camera, renderer } = labStage;

    camera.position.set(0, 1.2, 5);
    camera.lookAt(0, 0, 0);

    const env = buildEnvMap(renderer);
    if (env) scene.environment = env;

    labLights = addLightingRig(scene, { intensity: 1.0, shadowRes: 1024, ambient: 0.2 });
    addGround(scene, -2.2);

    labBall = buildBallMesh(LAB_BALL_RADIUS, STATE.labConfig.colorway, STATE.labConfig.finish, STATE.labConfig.name, STATE.labConfig.number);
    scene.add(labBall);

    labControls = new OrbitControls(camera, DOM.labCanvas);
    labControls.enableDamping = true;
    labControls.dampingFactor = 0.08;
    labControls.enablePan = false;
    labControls.enableZoom = true;
    labControls.minDistance = 2.8;
    labControls.maxDistance = 9;
    labControls.minPolarAngle = 0.3;
    labControls.maxPolarAngle = PI * 0.72;
    labControls.autoRotate = true;
    labControls.autoRotateSpeed = 1.5;
    labControls.target.set(0, 0, 0);

    DOM.labCanvas.addEventListener('pointerdown', () => {
      DOM.labCanvas.classList.add('grabbing');
      labControls.autoRotate = false;
    });
    DOM.labCanvas.addEventListener('pointerup', () => {
      DOM.labCanvas.classList.remove('grabbing');
      setTimeout(() => { if (labControls) labControls.autoRotate = true; }, 3000);
    });

    /* Physics state */
    let physicsActive = false;
    let physicsType = null;
    let velocity = { x: 0, y: 0, z: 0 };
    let angularVel = { x: 0, y: 0, z: 0 };
    const gravity = -9.81;
    const bounceDamping = 0.72;
    const floorY = -2.2 + LAB_BALL_RADIUS;
    const dragCoeff = 0.02;
    const magnusCoeff = 0.0008;

    function startBounce() {
      physicsActive = true;
      physicsType = 'bounce';
      labBall.position.set(0, 3, 0);
      velocity = { x: rand(-0.5, 0.5), y: 0, z: 0 };
      angularVel = { x: rand(-2, 2), y: rand(-2, 2), z: 0 };
      labControls.autoRotate = false;
      playSound('kick');
    }

    function startSpin() {
      physicsActive = true;
      physicsType = 'spin';
      labBall.position.set(0, 0, 0);
      velocity = { x: 0, y: 0, z: 0 };
      angularVel = { x: 0, y: 18, z: 3 };
      labControls.autoRotate = false;
      playSound('whoosh');
    }

    DOM.btnBounce.addEventListener('click', () => { initAudio(); startBounce(); DOM.btnBounce.classList.add('active'); setTimeout(() => DOM.btnBounce.classList.remove('active'), 2000); });
    DOM.btnSpin.addEventListener('click', () => { initAudio(); startSpin(); DOM.btnSpin.classList.add('active'); setTimeout(() => DOM.btnSpin.classList.remove('active'), 2000); });

    DOM.btnLight.addEventListener('click', () => {
      labLightMode = (labLightMode + 1) % LAB_LIGHT_MODES.length;
      applyLightMode(labLightMode);
      playSound('click');
      toast(`Lighting: ${LAB_LIGHT_MODES[labLightMode]}`, 'sun');
    });

    function applyLightMode(mode) {
      if (!labLights) return;
      const { key, fill, rim, amb } = labLights;
      switch (mode) {
        case 0: key.color.set(0xfff8e8); key.intensity = 1.2; fill.color.set(0xd0e8ff); fill.intensity = 0.5; rim.color.set(0xc8ff2e); rim.intensity = 0.6; amb.intensity = 0.2; break;
        case 1: key.color.set(0xffa040); key.intensity = 1.5; fill.color.set(0x4040a0); fill.intensity = 0.3; rim.color.set(0xff6020); rim.intensity = 0.8; amb.intensity = 0.12; break;
        case 2: key.color.set(0x6080cc); key.intensity = 0.6; fill.color.set(0x202060); fill.intensity = 0.2; rim.color.set(0xc8ff2e); rim.intensity = 1.0; amb.intensity = 0.05; break;
        case 3: key.color.set(0xffffff); key.intensity = 1.8; fill.color.set(0xffffff); fill.intensity = 0.8; rim.color.set(0xffffff); rim.intensity = 0.4; amb.intensity = 0.35; break;
      }
    }

    labStage.onAnim((dt, elapsed) => {
      if (labControls) labControls.update();

      if (physicsActive && labBall) {
        const cdt = Math.min(dt, 0.05);

        if (physicsType === 'bounce') {
          velocity.y += gravity * cdt;
          velocity.x *= (1 - dragCoeff);
          velocity.z *= (1 - dragCoeff);
          velocity.x += angularVel.y * magnusCoeff;
          velocity.z -= angularVel.x * magnusCoeff;

          labBall.position.x += velocity.x * cdt;
          labBall.position.y += velocity.y * cdt;
          labBall.position.z += velocity.z * cdt;

          if (labBall.position.y <= floorY) {
            labBall.position.y = floorY;
            velocity.y = -velocity.y * bounceDamping;
            velocity.x *= 0.9;
            angularVel.x *= 0.85;
            angularVel.y *= 0.85;
            if (Math.abs(velocity.y) > 0.3) playSound('bounce');
            if (Math.abs(velocity.y) < 0.15) {
              velocity.y = 0;
              labBall.position.y = floorY;
              physicsActive = false;
              setTimeout(() => {
                labBall.position.set(0, 0, 0);
                velocity = { x: 0, y: 0, z: 0 };
                angularVel = { x: 0, y: 0, z: 0 };
                if (labControls) labControls.autoRotate = true;
              }, 1200);
            }
          }
        }

        labBall.rotation.x += angularVel.x * cdt;
        labBall.rotation.y += angularVel.y * cdt;
        labBall.rotation.z += angularVel.z * cdt;
        angularVel.x *= (1 - 0.4 * cdt);
        angularVel.y *= (1 - 0.4 * cdt);
        angularVel.z *= (1 - 0.4 * cdt);

        if (physicsType === 'spin') {
          const totalSpin = Math.abs(angularVel.x) + Math.abs(angularVel.y) + Math.abs(angularVel.z);
          if (totalSpin < 0.3) { physicsActive = false; if (labControls) labControls.autoRotate = true; }
        }
      }
    });
  } catch (e) { console.warn('Lab 3D init failed:', e); }
}

/* Rebuild lab ball and synchronize all 3D & UI telemetry */
function syncLabUI() {
  const { colorway = 0, finish = 0, name = '90+ SUPPLY', number = '10' } = STATE.labConfig || {};

  if (DOM.embossName && DOM.embossName.value !== name) DOM.embossName.value = name;
  if (DOM.embossNum && DOM.embossNum.value !== number) DOM.embossNum.value = number;

  if (DOM.cwRow) {
    $$('[data-cw]', DOM.cwRow).forEach(b => b.classList.toggle('on', parseInt(b.dataset.cw) === colorway));
  }
  if (DOM.finRow) {
    $$('[data-fin]', DOM.finRow).forEach(b => b.classList.toggle('on', parseInt(b.dataset.fin) === finish));
  }

  const cw = COLORWAYS[colorway] || COLORWAYS[0];
  const fin = FINISHES[finish] || FINISHES[0];

  if (DOM.cwName) DOM.cwName.textContent = cw.name;
  if (DOM.finName) DOM.finName.textContent = fin.name;
  if (DOM.cfgText) DOM.cfgText.textContent = `${cw.name} · ${fin.name}`;
  const stampEl = document.getElementById('cfgStamp');
  if (stampEl) stampEl.textContent = `STAMP: "${escapeHtml(name || '90+ SUPPLY')}" #${escapeHtml(number || '10')}`;
  if (DOM.labPrice) DOM.labPrice.textContent = fmt(cw.price || 1299);

  rebuildLabBall();
}

function rebuildLabBall() {
  const { colorway = 0, finish = 0, name = '90+ SUPPLY', number = '10' } = STATE.labConfig || {};
  const cw = COLORWAYS[colorway] || COLORWAYS[0];
  const fin = FINISHES[finish] || FINISHES[0];

  if (DOM.cwName) DOM.cwName.textContent = cw.name;
  if (DOM.finName) DOM.finName.textContent = fin.name;
  if (DOM.cfgText) DOM.cfgText.textContent = `${cw.name} · ${fin.name}`;
  const stampEl = document.getElementById('cfgStamp');
  if (stampEl) stampEl.textContent = `STAMP: "${escapeHtml(name || '90+ SUPPLY')}" #${escapeHtml(number || '10')}`;
  if (DOM.labPrice) DOM.labPrice.textContent = fmt(cw.price || 1299);

  if (!labStage || !labBall) return;
  const { scene } = labStage;
  try {
    labBall.geometry.dispose();
    if (labBall.material.map) labBall.material.map.dispose();
    labBall.material.dispose();
    scene.remove(labBall);

    labBall = buildBallMesh(LAB_BALL_RADIUS, colorway, finish, name, number);
    scene.add(labBall);
  } catch (e) {
    console.warn('rebuildLabBall error:', e);
  }
}

/* 2.18  CHRONO DIAL RENDERER */
function initChrono() {
  const canvas = DOM.labDial;
  if (!canvas) return;
  const ctx = canvas.getContext('2d');
  const w = canvas.width;
  const h = canvas.height;
  const cx2 = w / 2;
  const cy2 = h / 2;
  const r = Math.min(cx2, cy2) - 8;

  function drawDial() {
    ctx.clearRect(0, 0, w, h);
    const now = new Date();
    const s = now.getSeconds() + now.getMilliseconds() / 1000;
    const m = now.getMinutes() + s / 60;
    const hr = now.getHours() % 12 + m / 60;

    ctx.beginPath(); ctx.arc(cx2, cy2, r, 0, TAU); ctx.strokeStyle = 'rgba(255,255,255,0.1)'; ctx.lineWidth = 2; ctx.stroke();

    for (let i = 0; i < 60; i++) {
      const angle = (TAU / 60) * i - PI / 2;
      const isMajor = i % 5 === 0;
      const inner = r - (isMajor ? 14 : 7);
      const outer = r - 2;
      ctx.beginPath();
      ctx.moveTo(cx2 + inner * Math.cos(angle), cy2 + inner * Math.sin(angle));
      ctx.lineTo(cx2 + outer * Math.cos(angle), cy2 + outer * Math.sin(angle));
      ctx.strokeStyle = isMajor ? 'rgba(200,255,46,0.8)' : 'rgba(255,255,255,0.2)';
      ctx.lineWidth = isMajor ? 2 : 1;
      ctx.stroke();
    }

    const hrAngle = (TAU / 12) * hr - PI / 2;
    ctx.beginPath(); ctx.moveTo(cx2, cy2); ctx.lineTo(cx2 + (r * 0.5) * Math.cos(hrAngle), cy2 + (r * 0.5) * Math.sin(hrAngle));
    ctx.strokeStyle = '#f3f4f1'; ctx.lineWidth = 3; ctx.lineCap = 'round'; ctx.stroke();

    const mAngle = (TAU / 60) * m - PI / 2;
    ctx.beginPath(); ctx.moveTo(cx2, cy2); ctx.lineTo(cx2 + (r * 0.7) * Math.cos(mAngle), cy2 + (r * 0.7) * Math.sin(mAngle));
    ctx.strokeStyle = '#f3f4f1'; ctx.lineWidth = 2; ctx.stroke();

    const sAngle = (TAU / 60) * s - PI / 2;
    ctx.beginPath(); ctx.moveTo(cx2, cy2); ctx.lineTo(cx2 + (r * 0.78) * Math.cos(sAngle), cy2 + (r * 0.78) * Math.sin(sAngle));
    ctx.strokeStyle = '#c8ff2e'; ctx.lineWidth = 1.2; ctx.stroke();

    ctx.beginPath(); ctx.arc(cx2, cy2, 3, 0, TAU); ctx.fillStyle = '#c8ff2e'; ctx.fill();
    ctx.beginPath(); ctx.arc(cx2, cy2, 5, 0, TAU); ctx.fillStyle = 'rgba(200,255,46,0.2)'; ctx.fill();

    const pad2 = n => String(n).padStart(2, '0');
    if (DOM.clockText) DOM.clockText.textContent = `${pad2(now.getHours())}:${pad2(now.getMinutes())}:${pad2(now.getSeconds())}`;
    const elapsed = Math.floor((Date.now() - pageLoadTime) / 1000);
    const matchMinute = Math.floor((elapsed % (90 * 60)) / 60) + 1;
    if (DOM.matchMin) DOM.matchMin.textContent = `${pad2(matchMinute)}'`;

    requestAnimationFrame(drawDial);
  }
  drawDial();
}

const pageLoadTime = Date.now();

/* 2.19  CURSOR GLOW */
function initCursorGlow() {
  if (!DOM.cursorGlow || window.matchMedia('(hover: none)').matches) return;
  let mx = 0, my = 0, cx2 = 0, cy2 = 0;
  document.addEventListener('mousemove', e => { mx = e.clientX; my = e.clientY; }, { passive: true });
  function animate() {
    cx2 = lerp(cx2, mx, 0.12);
    cy2 = lerp(cy2, my, 0.12);
    DOM.cursorGlow.style.transform = `translate(${cx2 - 180}px, ${cy2 - 180}px)`;
    requestAnimationFrame(animate);
  }
  animate();
}

/* 2.20  SCROLL REVEAL */
function initScrollReveal() {
  const observer = new IntersectionObserver(entries => {
    entries.forEach(entry => {
      if (entry.isIntersecting) {
        entry.target.classList.add('in');
        observer.unobserve(entry.target);
      }
    });
  }, { threshold: 0.01, rootMargin: '80px 0px 80px 0px' });

  $$('.rv').forEach(el => {
    const rect = el.getBoundingClientRect();
    if (rect.top < window.innerHeight + 60 && rect.bottom > -60) {
      el.classList.add('in');
    } else {
      observer.observe(el);
    }
  });
  window.addEventListener('scroll', throttle(() => {
    $$('.rv:not(.in)').forEach(el => {
      const r = el.getBoundingClientRect();
      if (r.top < window.innerHeight + 160) el.classList.add('in');
    });
  }, 120), { passive: true });
  setTimeout(() => { $$('.rv:not(.in)').forEach(el => el.classList.add('in')); }, 2500);
}

function reObserveReveal() {
  const observer = new IntersectionObserver(entries => {
    entries.forEach(entry => {
      if (entry.isIntersecting) {
        entry.target.classList.add('in');
        observer.unobserve(entry.target);
      }
    });
  }, { threshold: 0.01, rootMargin: '80px 0px 80px 0px' });

  $$('.rv:not(.in)').forEach(el => {
    const rect = el.getBoundingClientRect();
    if (rect.top < window.innerHeight + 60 && rect.bottom > -60) {
      el.classList.add('in');
    } else {
      observer.observe(el);
    }
  });
}

/* 2.21  ANIMATED COUNTERS */
function initCounters() {
  const obs = new IntersectionObserver(entries => {
    entries.forEach(entry => {
      if (!entry.isIntersecting) return;
      const el = entry.target; obs.unobserve(el);
      const target = parseFloat(el.dataset.count);
      const dec = parseInt(el.dataset.dec || '0');
      const dur = 1600, start = performance.now();
      function step(now) {
        const t = Math.min((now - start) / dur, 1);
        const eased = 1 - Math.pow(1 - t, 3);
        el.textContent = dec > 0 ? (eased * target).toFixed(dec) : Math.floor(eased * target).toLocaleString('en-IN');
        if (t < 1) requestAnimationFrame(step);
      }
      requestAnimationFrame(step);
    });
  }, { threshold: 0.4 });
  $$('[data-count]').forEach(el => obs.observe(el));
}

