/* 2.24  CARD TILT TRACKING */
function initCardTracking() {
  document.addEventListener('mousemove', e => {
    const cards = $$('.cat-card, .pcard-media');
    for (const card of cards) {
      const rect = card.getBoundingClientRect();
      if (e.clientX >= rect.left && e.clientX <= rect.right && e.clientY >= rect.top && e.clientY <= rect.bottom) {
        card.style.setProperty('--mx', ((e.clientX - rect.left) / rect.width * 100).toFixed(1) + '%');
        card.style.setProperty('--my', ((e.clientY - rect.top) / rect.height * 100).toFixed(1) + '%');
      }
    }
  }, { passive: true });
}

/* 2.25  MOBILE MENU SYSTEM */
function initMobileMenu() {
  DOM.burger?.addEventListener('click', () => { DOM.mmenu?.classList.add('open'); playSound('whoosh'); });
  DOM.mmenuClose?.addEventListener('click', () => { DOM.mmenu?.classList.remove('open'); playSound('click'); });
  $$('#mmenu a.big').forEach(a => a.addEventListener('click', () => DOM.mmenu?.classList.remove('open')));
}

/* 2.26  PROMO PARALLAX */
function initPromoParallax() {
  if (!DOM.promoMark) return;
  window.addEventListener('scroll', throttle(() => {
    const rect = DOM.promoMark.parentElement.getBoundingClientRect();
    if (rect.top < window.innerHeight && rect.bottom > 0) {
      const progress = (window.innerHeight - rect.top) / (window.innerHeight + rect.height);
      DOM.promoMark.style.transform = `translate(-50%, -56%) translateX(${(progress - 0.5) * 60}px)`;
    }
  }, 30), { passive: true });
}

/* 2.27  LAB CONFIGURATOR UI WIRING */
function initLabUI() {
  if (DOM.cwRow) {
    DOM.cwRow.innerHTML = COLORWAYS.map((cw, i) => `
      <button class="sw ${i === STATE.labConfig.colorway ? 'on' : ''}" data-cw="${i}" title="${cw.name}">
        <div class="sw-img" style="background:linear-gradient(135deg, ${cw.base}, ${cw.panel})"></div>
        <span>${cw.name}</span>
        <span class="tick"><i data-lucide="check"></i></span>
      </button>
    `).join('');
  }

  if (DOM.finRow) {
    DOM.finRow.innerHTML = FINISHES.map((fin, i) => `
      <button class="sw ${i === STATE.labConfig.finish ? 'on' : ''}" data-fin="${i}" title="${fin.name}">
        <div class="sw-img" style="background:radial-gradient(circle at 40% 35%, rgba(255,255,255,${0.3 - fin.roughness * 0.2}), #1a1d21 70%);border:1px solid var(--line)"></div>
        <span>${fin.name}</span>
        <span class="tick"><i data-lucide="check"></i></span>
      </button>
    `).join('');
  }

  if (window.lucide) lucide.createIcons();

  DOM.cwRow?.addEventListener('click', e => {
    const btn = e.target.closest('[data-cw]');
    if (!btn) return;
    const idx = parseInt(btn.dataset.cw);
    STATE.labConfig.colorway = idx;
    syncLabUI();
    playSound('click');
  });

  DOM.finRow?.addEventListener('click', e => {
    const btn = e.target.closest('[data-fin]');
    if (!btn) return;
    const idx = parseInt(btn.dataset.fin);
    STATE.labConfig.finish = idx;
    syncLabUI();
    playSound('click');
  });

  const debouncedSync = debounce(() => syncLabUI(), 250);
  DOM.embossName?.addEventListener('input', () => { STATE.labConfig.name = DOM.embossName.value.slice(0, 14); debouncedSync(); });
  DOM.embossNum?.addEventListener('input', () => { STATE.labConfig.number = DOM.embossNum.value.slice(0, 2); debouncedSync(); });

  /* Lab Configurator Reset Button */
  $('#labReset')?.addEventListener('click', () => {
    STATE.labConfig = { colorway: 0, finish: 0, name: '90+ SUPPLY', number: '10' };
    syncLabUI();
    playSound('pop');
    toast('Customizer reset to factory default specs.', 'rotate-ccw');
  });

  /* Lab Save to Cloud Locker Button */
  $('#labSave')?.addEventListener('click', () => {
    if (window.PLAYER_AUTH) {
      const cw = COLORWAYS[STATE.labConfig.colorway] || COLORWAYS[0];
      const fin = FINISHES[STATE.labConfig.finish] || FINISHES[0];
      const buildConfig = {
        name: `${STATE.labConfig.name || 'Custom'} Match Edition`,
        colorway: STATE.labConfig.colorway,
        colorwayName: cw.name,
        finish: STATE.labConfig.finish,
        finishName: fin.name,
        embossName: STATE.labConfig.name || '90+ SUPPLY',
        embossNum: STATE.labConfig.number || '10'
      };
      const res = window.PLAYER_AUTH.saveCustomBallBuild(buildConfig);
      if (res.success) {
        playSound('success');
        toast(`Custom ball saved to Cloud Locker!`, 'bookmark');
      } else {
        toast(`Failed to save ball build`, 'alert-circle');
      }
    }
  });

  /* Lab Add to Cart Button */
  $('#labAdd')?.addEventListener('click', () => {
    const ballProd = (typeof PRODUCTS !== 'undefined' ? PRODUCTS.find(p => p.category === 'balls') : null) || (typeof PRODUCTS !== 'undefined' ? PRODUCTS[0] : null);
    const pid = ballProd ? ballProd.id : 'match-football';
    const cw = COLORWAYS[STATE.labConfig.colorway] || COLORWAYS[0];
    addToCart(pid, {
      qty: 1,
      customName: STATE.labConfig.name || '90+ SUPPLY',
      customNumber: STATE.labConfig.number || '10',
      customNum: STATE.labConfig.number || '10',
      customColorway: STATE.labConfig.colorway,
      colorway: STATE.labConfig.colorway,
      customFinish: STATE.labConfig.finish,
      finish: STATE.labConfig.finish,
      priceOverride: cw.price || 1299
    });
    playSound('success');
    toast(`Custom 3D Ball (${cw.name}) added to your Pitch Bag!`, 'shopping-bag');
    openCartDrawer();
  });

  /* Initial UI Sync */
  syncLabUI();
}

/* 2.28  SMOOTH SCROLL ANCHORS */
function initSmoothScroll() {
  document.addEventListener('click', e => {
    const link = e.target.closest('[data-scroll], a[href^="#lab"], a[href^="#/lab"]');
    if (!link) return;
    const targetId = link.dataset.scroll || 'lab';
    const target = document.getElementById(targetId);
    if (target && (!STATE.route || STATE.route === 'lab')) {
      e.preventDefault();
      target.scrollIntoView({ behavior: 'smooth', block: 'start' });
      if (window.history && window.history.pushState) {
        window.history.pushState(null, '', '#lab');
      }
    }
  });
}

/* 2.29  BOOT SEQUENCE — Initialize all Part 2 systems */
function bootPart2() {
  if (window.lucide) lucide.createIcons();
  if (window.matchMedia && window.matchMedia('(pointer:fine)').matches) initCursorGlow();
  initNavScroll();
  initTicker();
  initMobileMenu();
  initCardTracking();
  initSmoothScroll();
  initPromoParallax();
  initLabUI();
  initScrollReveal();
  initCounters();
  initLazyImages();

  /* 3D scenes — init after a short delay to not block FP */
  requestAnimationFrame(() => { try { initHero(); } catch (e) {} });
  const idle = window.requestIdleCallback || ((fn) => setTimeout(fn, 250));
  idle(() => {
    try { initChrono(); } catch (e) {}
    const labEl = document.getElementById('lab') || document.getElementById('labCanvas');
    if (!labEl) { try { initLab(); } catch (e) {} return; }
    const bootLab = () => { try { initLab(); } catch (e) {} };
    if ('IntersectionObserver' in window) {
      const io = new IntersectionObserver((ents) => {
        if (ents.some(e => e.isIntersecting)) { io.disconnect(); bootLab(); }
      }, { rootMargin: '220px' });
      io.observe(labEl);
    } else idle(bootLab);
  });
}

