function checkPincode(pinStr) {
  const clean = String(pinStr).trim().replace(/\D/g, '');
  if (clean.length !== 6) {
    return { valid: false, message: 'Please enter a valid 6-digit Indian PIN code' };
  }

  const p2 = parseInt(clean.slice(0, 2));
  const p3 = parseInt(clean.slice(0, 3));

  let match = PIN_DATABASE.find(e => e.prefix.includes(p3)) ||
              PIN_DATABASE.find(e => e.prefix.includes(p2));

  if (!match) {
    /* Fallback default zone estimation */
    match = { region: 'Standard Delivery Zone', city: 'Standard Delivery Area', tier: 2, hours: 60, cod: true, carrier: 'Delhivery Express' };
  }

  const today = new Date();
  const dispatchDate = new Date(today.getTime() + 24 * 3600 * 1000);
  const deliveryDate = new Date(today.getTime() + (match.hours + 24) * 3600 * 1000);

  const dateOptions = { weekday: 'short', month: 'short', day: 'numeric' };
  const formattedDelivery = deliveryDate.toLocaleDateString('en-IN', dateOptions);

  return {
    valid: true,
    pincode: clean,
    city: match.city,
    region: match.region,
    tier: match.tier,
    hours: match.hours,
    carrier: match.carrier || 'Bluedart Express',
    deliveryDateStr: formattedDelivery,
    codAvailable: match.cod,
    expressAvailable: match.tier <= 2,
    freeShipThreshold: FREE_SHIP_THRESHOLD,
    message: `Delivery to ${match.city} via ${match.carrier || 'Bluedart Express'} by ${formattedDelivery}`
  };
}

