/* 3.9  GLOBAL EVENT DELEGATION FOR COMMERCE ACTIONS Handles Add-to-Cart, Drawer Toggles, Quick View, Wishlist clicks */
function initCommerceEvents() {
  /* Global Click Handler */
  document.addEventListener('click', e => {
    /* Open / Close Cart Drawer */
    if (e.target.closest('#navCart') || e.target.closest('[data-action="open-cart"]')) {
      e.preventDefault();
      openCartDrawer();
      return;
    }
    if (e.target.closest('#cartClose') || (e.target.closest('#scrim') && DOM.cartDrawer?.classList.contains('open'))) {
      closeCartDrawer();
      return;
    }

    /* Open / Close Wishlist Drawer */
    if (e.target.closest('#navWish') || e.target.closest('[data-action="open-wish"]')) {
      e.preventDefault();
      openWishlistDrawer();
      return;
    }
    if (e.target.closest('#wishClose') || (e.target.closest('#scrim') && DOM.wishDrawer?.classList.contains('open'))) {
      closeWishlistDrawer();
      return;
    }

    /* Cart Quantity Modifiers */
    const incBtn = e.target.closest('[data-action="inc-qty"]');
    if (incBtn) {
      const uid = incBtn.dataset.uid;
      const item = STATE.cart.find(i => i.uid === uid);
      if (item) updateCartQty(uid, item.qty + 1);
      return;
    }
    const decBtn = e.target.closest('[data-action="dec-qty"]');
    if (decBtn) {
      const uid = decBtn.dataset.uid;
      const item = STATE.cart.find(i => i.uid === uid);
      if (item) updateCartQty(uid, item.qty - 1);
      return;
    }

    /* Cart Remove Item */
    const delBtn = e.target.closest('[data-action="remove-item"]');
    if (delBtn) {
      const uid = delBtn.dataset.uid;
      removeFromCart(uid);
      return;
    }

    /* Quick Add to Cart from Cards */
    const addBtn = e.target.closest('[data-action="quick-add"]');
    if (addBtn) {
      const pid = addBtn.dataset.id;
      addToCart(pid);
      return;
    }

    /* Wishlist Toggle Button */
    const wishBtn = e.target.closest('[data-wish-id]');
    if (wishBtn) {
      const pid = wishBtn.dataset.wishId;
      toggleWishlist(pid);
      return;
    }

    /* Wishlist Remove Button */
    const remWishBtn = e.target.closest('[data-action="remove-wish"]');
    if (remWishBtn) {
      const pid = remWishBtn.dataset.id;
      toggleWishlist(pid);
      return;
    }

    /* Explore Shop Trigger */
    if (e.target.closest('[data-action="explore-shop"]')) {
      closeCartDrawer();
      closeWishlistDrawer();
      window.location.hash = '#/shop';
      return;
    }

    /* Category Card Click */
    const catCard = e.target.closest('.cat-card');
    if (catCard) {
      const catSlug = catCard.dataset.category;
      window.location.hash = `#/shop/${catSlug}`;
      return;
    }

    /* Empty Match Bag Action */
    if (e.target.closest('#btnEmptyCart')) {
      promptClearCart();
      return;
    }

    /* Coupon Apply in Drawer */
    if (e.target.closest('#btnApplyCoupon')) {
      const input = $('#cartCouponInput');
      if (input && input.value.trim()) {
        const totals = getCartTotals();
        const res = validateCoupon(input.value, totals.subtotal, STATE.cart);
        if (res.valid) {
          STATE.coupon = res.code;
          renderCartDrawer();
          toast(res.message, 'tag');
          playSound('success');
        } else {
          toast(res.message, 'alert-circle');
          playSound('error');
        }
      }
      return;
    }

    /* Coupon Remove in Drawer */
    if (e.target.closest('#btnRemoveCoupon')) {
      STATE.coupon = null;
      renderCartDrawer();
      toast('Coupon removed', 'x');
      playSound('click');
      return;
    }

    /* Lab Add to Cart Button */
    if (e.target.closest('#labAdd')) {
      initAudio();
      const cw = COLORWAYS[STATE.labConfig.colorway] || COLORWAYS[0];
      const fin = FINISHES[STATE.labConfig.finish] || FINISHES[0];
      const customName = (STATE.labConfig.name || '90+ SUPPLY').trim();
      const customNumber = (STATE.labConfig.number || '10').trim();
      addToCart('ball-volt-pro', {
        qty: 1,
        isCustom: true,
        customName: customName,
        customNumber: customNumber,
        customColorway: STATE.labConfig.colorway,
        customFinish: STATE.labConfig.finish,
        variantName: `Custom: "${customName}" #${customNumber} (${cw.name} · ${fin.name})`,
        priceOverride: cw.price
      });
      toast(`Custom Ball "${customName}" #${customNumber} added to match bag!`, 'shopping-bag');
      return;
    }
  });
}

/* 3.10  BOOT SEQUENCE — Initialize Part 3 Systems */
