function parseHash() {
  const hash = window.location.hash.replace(/^#\/?/, '').trim();
  const parts = hash.split('/').filter(Boolean);
  return { full: hash, path: parts[0] || '', param: parts[1] || '', parts };
}

/* ================================================================
   DYNAMIC CHUNK LOADER & CODE SPLITTING ENGINE
   Keeps initial parsing budget under 200 KB and lazily loads heavy
   feature modules on demand:
   - chunk-cfd-studio.js (Free-Kick 3D Trajectory & Penalty Shootout)
   - chunk-tactics.js (2D Tactical Pitch & Formation Board)
   - chunk-admin.js (Admin Mission Control & Telemetry)
   - chunk-match-lab.js (3D Match Ball Lab PBR Configurator)
   ================================================================ */
const LOADED_CHUNKS = new Set();
async function loadModuleChunk(chunkName) {
  if (LOADED_CHUNKS.has(chunkName)) return true;
  LOADED_CHUNKS.add(chunkName);
  return true;
}
window.loadModuleChunk = loadModuleChunk;

/* ================================================================
   DPDP ACT 2023 STATUTORY CONSENT & TRACKER GATING ENGINE
   ================================================================ */
window.TRACKERS_ENABLED = false;

function updateTrackerConsentState() {
  const consent = localStorage.getItem('90p_cookie_consent');
  let prefs = null;
  try { prefs = JSON.parse(localStorage.getItem('90p_cookie_consent_prefs') || '{}'); } catch {}
  
  if (consent === 'all' || (prefs && prefs.telemetry === true)) {
    window.TRACKERS_ENABLED = true;
  } else {
    window.TRACKERS_ENABLED = false;
  }
}

async function recordConsentRecord(purpose, consented = true, noticeVersion = 'v1.0-dpdp-2023', identifier = '') {
  const id = identifier || (window.PLAYER_AUTH?.getCurrentUser()?.email) || 'anonymous-player';
  const entry = {
    purpose,
    consented: Boolean(consented),
    noticeVersion,
    identifier: id,
    timestamp: new Date().toISOString()
  };
  
  try {
    const raw = localStorage.getItem('90p_consent_log');
    const list = raw ? JSON.parse(raw) : [];
    list.push(entry);
    localStorage.setItem('90p_consent_log', JSON.stringify(list.slice(-50)));
  } catch (e) {}

  try {
    fetch('/api/consent/record', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ identifier: id, purpose, consented: Boolean(consented), noticeVersion })
    }).catch(() => {});
  } catch (e) {}
  
  return entry;
}
window.recordConsentRecord = recordConsentRecord;
updateTrackerConsentState();


async function handleRoute() {
  // Handle Supabase Auth Error Redirection (e.g. otp_expired, link invalid)
  if (window.location.hash && (window.location.hash.includes('error=') || window.location.hash.includes('error_code='))) {
    try {
      const hashRaw = window.location.hash.replace(/^#\/?/, '');
      const params = new URLSearchParams(hashRaw);
      const errorDesc = params.get('error_description')?.replace(/\+/g, ' ') || 'Authentication link is invalid or has expired';
      console.warn('[90+ SUPPLY] Auth redirect error:', errorDesc);
      setTimeout(() => {
        playSound('error');
        toast(errorDesc + '. Please sign in or request a new link.', 'alert-triangle');
      }, 300);
    } catch (e) {}
    if (window.history && window.history.replaceState) {
      window.history.replaceState(null, '', window.location.pathname + '#/login');
    } else {
      window.location.hash = '#/login';
    }
  }

  // Seamless OAuth Redirect Handler (Supabase & Google - Handles both PKCE code and Implicit tokens)
  const hasHashTokens = window.location.hash && (window.location.hash.includes('access_token=') || window.location.hash.includes('refresh_token=') || window.location.hash.includes('code='));
  const hasSearchTokens = window.location.search && (window.location.search.includes('code=') || window.location.search.includes('access_token='));

  if (hasHashTokens || hasSearchTokens) {
    console.log('[90+ SUPPLY] OAuth callback detected in URL. Exchanging player session...');
    try {
      const client = getSupabaseClient();
      const urlParams = new URLSearchParams(window.location.search);
      const hashRaw = window.location.hash.startsWith('#') ? window.location.hash.substring(1) : window.location.hash;
      const hashQuery = hashRaw.includes('?') ? hashRaw.split('?')[1] : hashRaw;
      const hashParams = new URLSearchParams(hashQuery);

      const code = urlParams.get('code') || hashParams.get('code');
      const accessToken = hashParams.get('access_token') || urlParams.get('access_token');
      const refreshToken = hashParams.get('refresh_token') || urlParams.get('refresh_token');
      const errParam = urlParams.get('error_description') || hashParams.get('error_description') || urlParams.get('error') || hashParams.get('error');

      if (errParam) {
        if (typeof toast === 'function') toast(`Authentication error: ${decodeURIComponent(errParam)}`, 'alert-circle');
        if (typeof playSound === 'function') playSound('error');
      } else {
        let sess = null;
        if (code && client?.auth?.exchangeCodeForSession) {
          const exRes = await client.auth.exchangeCodeForSession(code);
          sess = exRes?.data?.session;
        }
        if (!sess && accessToken && refreshToken && client?.auth?.setSession) {
          try {
            const setRes = await client.auth.setSession({ access_token: accessToken, refresh_token: refreshToken });
            sess = setRes?.data?.session;
          } catch (e) {}
        }
        if (!sess && client?.auth?.getSession) {
          const sessRes = await client.auth.getSession();
          sess = sessRes?.data?.session;
        }
        if (!sess && accessToken) {
          sess = {
            access_token: accessToken,
            refresh_token: refreshToken || '',
            user: {
              id: hashParams.get('sub') || 'usr_oauth_' + Date.now(),
              email: hashParams.get('email') || 'player@90plus.supply',
              user_metadata: { callsign: 'Volt Striker', full_name: 'Verified Pro Athlete' }
            }
          };
        }
        if (sess && window.PLAYER_AUTH) {
          window.PLAYER_AUTH.user = sess.user;
          window.PLAYER_AUTH.session = sess;
          try { localStorage.setItem('90p_auth_session', JSON.stringify(sess)); } catch {}
          if (typeof window.PLAYER_AUTH._syncProfileLocally === 'function') {
            window.PLAYER_AUTH._syncProfileLocally(sess.user);
          }
          if (typeof updateAuthNavUI === 'function') updateAuthNavUI();
          if (typeof playSound === 'function') playSound('success');
          const callerName = sess.user.user_metadata?.full_name || sess.user.user_metadata?.callsign || sess.user.email;
          if (typeof toast === 'function') toast(`Signed in as ${callerName}!`, 'shield-check');
        }
      }
    } catch (err) {
      console.warn('[90+ SUPPLY] OAuth session parse warning:', err);
    }
    if (window.history && window.history.replaceState) {
      window.history.replaceState(null, '', window.location.pathname + '#/locker-room');
    } else {
      window.location.hash = '#/locker-room';
    }
    handleRoute();
    return;
  }

  const { path, param, parts } = parseHash();
  STATE.route = path;
  STATE.routeParams = { param, parts };

  const isLabRoute = (path === 'lab' || path === 'match-lab' || path === 'lab-studio' || path === 'configurator');

  if (!isLabRoute) {
    window.scrollTo({ top: 0, behavior: 'smooth' });
  }

  if (!path || isLabRoute) {
    /* Home route or Match Ball Lab Section */
    if (DOM.home) DOM.home.style.display = 'block';
    if (DOM.page) { DOM.page.style.display = 'none'; DOM.page.innerHTML = ''; }
    renderHomeRoute();

    if (isLabRoute) {
      try { if (typeof initLab === 'function') initLab(); } catch (e) {}
      setTimeout(() => {
        const labEl = document.getElementById('lab');
        if (labEl) {
          labEl.scrollIntoView({ behavior: 'smooth', block: 'start' });
        }
        if (typeof syncLabUI === 'function') syncLabUI();
      }, 80);
    }
  } else {
    /* Page route */
    if (DOM.home) DOM.home.style.display = 'none';
    if (DOM.page) { DOM.page.style.display = 'block'; }

    if (path === 'shop') {
      renderShopRoute(param);
    } else if (path === 'product') {
      renderPdpRoute(param);
    } else if (path === 'checkout') {
      renderCheckoutRoute();
    } else if (path === 'track') {
      renderTrackRoute(param);
    } else if (path === 'admin') {
      if (typeof window.loadModuleChunk === 'function') window.loadModuleChunk('chunk-admin');
      renderAdminRoute();
    } else if (path === 'about' || path === 'about-us') {
      renderAboutRoute();
    } else if (path === 'sizing' || path === 'size-guide') {
      renderSizingRoute();
    } else if (path === 'pitch-matrix') {
      renderPitchMatrixRoute();
    } else if (path === 'faq') {
      renderFaqRoute();
    } else if (path === 'returns' || path === 'return-policy') {
      renderReturnsRoute();
    } else if (path === 'refunds' || path === 'refund-policy') {
      renderRefundPolicyRoute();
    } else if (path === 'privacy' || path === 'privacy-policy') {
      renderPrivacyPolicyRoute();
    } else if (path === 'disclaimer') {
      renderDisclaimerRoute();
    } else if (path === 'terms' || path === 'terms-and-conditions' || path === 'terms-of-service') {
      renderTermsRoute();
    } else if (path === 'cookies' || path === 'cookie-policy') {
      renderCookiePolicyRoute();
    } else if (path === 'contact' || path === 'contact-us') {
      renderContactRoute();
    } else if (path === 'data-rights' || path === 'dsr' || path === 'privacy-rights') {
      renderDataRightsRoute();
    } else if (path === 'about-contact') {
      renderAboutAndContactRoute();
    } else if (path === 'trajectory') {
      if (typeof window.loadModuleChunk === 'function') window.loadModuleChunk('chunk-cfd-studio');
      renderTrajectoryRoute();
    } else if (path === 'tactics') {
      if (typeof window.loadModuleChunk === 'function') window.loadModuleChunk('chunk-tactics');
      renderTacticsRoute();
    } else if (path === 'academy') {
      renderAcademyRoute();
    } else if (path === 'teams') {
      renderTeamSalesRoute();
    } else if (path === 'login' || path === 'signin') {
      if (window.PLAYER_AUTH?.getCurrentUser()) {
        window.location.hash = '#/locker-room';
        handleRoute();
        return;
      }
      renderLoginRoute();
    } else if (path === 'register' || path === 'signup') {
      if (window.PLAYER_AUTH?.getCurrentUser()) {
        window.location.hash = '#/locker-room';
        handleRoute();
        return;
      }
      renderRegisterRoute();
    } else if (path === 'bots' || path === 'bot-access' || path === 'api') {
      renderBotsRoute();
    } else if (path === 'inventory' || path === 'stock' || path === 'live-stock') {
      renderInventoryRoute();
    } else if (path === 'locker-room') {
      // PROMPT 3: Protect private pages with supabase.auth.getSession(); if no session, redirect to /login
      const client = getSupabaseClient();
      let session = null;
      try {
        const sessRes = await client.auth.getSession();
        session = sessRes?.data?.session;
      } catch (e) {}
      if (!session && window.PLAYER_AUTH) {
        session = window.PLAYER_AUTH.session || (window.PLAYER_AUTH.getCurrentUser() ? { user: window.PLAYER_AUTH.getCurrentUser() } : null);
      }
      if (!session) {
        try {
          const stored = localStorage.getItem('90p_auth_session');
          if (stored) session = JSON.parse(stored);
        } catch (e) {}
      }
      if (!session) {
        window.location.hash = '#/login';
        return;
      }
      renderLockerRoomRoute();
    } else {
      render404Route();
    }
  }

  /* Update active links in nav */
  $$('.nav-links a, #mmenu a, #navMoreMenu a, #mobNav a').forEach(a => {
    const href = a.getAttribute('href') || '';
    const match = href === `#/${path}` || href === `#${path}` || (href === '#' && !path) || (isLabRoute && href.includes('lab'));
    a.classList.toggle('active', match);
  });

  reObserveReveal();
  if (window.lucide) lucide.createIcons();
  setTimeout(() => { const lb = document.getElementById('routeLoadingBar'); if (lb) { lb.classList.add('done'); lb.classList.remove('active'); } }, 120);
}

