function renderCookiePolicyRoute() {
  if (!DOM.page) return;

  DOM.page.innerHTML = `
    <div class="content-page-wrapper">
      <div class="content-hero">
        <span class="hud-tag"><i data-lucide="cookie"></i> DATA GOVERNANCE & PRIVACY</span>
        <h1>COOKIE & TELEMETRY POLICY</h1>
        <p>Complete transparency regarding local storage tokens, session management, and DPDP Act compliance.</p>
      </div>
        <div class="last-updated-badge"><i data-lucide="clock"></i> LAST UPDATED: SEPTEMBER 8, 2026</div>
      </div>

      <div class="content-body">
        <div class="policy-grid">
          ${getPolicyNavHTML('cookies')}

          <div class="policy-content-card">
            <div class="policy-badge-row">
              <span class="policy-badge volt"><i data-lucide="shield"></i> DPDP ACT 2023 COMPLIANT</span>
              <span class="policy-badge"><i data-lucide="lock"></i> ZERO 3RD-PARTY TRACKERS</span>
              <span class="policy-badge volt"><i data-lucide="database"></i> LOCAL CLIENT-SIDE TOKENS</span>
              <span class="policy-badge"><i data-lucide="check"></i> ZERO DATA MONETIZATION</span>
            </div>

            <div class="policy-section">
              <h2><i data-lucide="cookie" style="color: #c8ff2e;"></i> 1. What Are Cookies and Local Storage?</h2>
              <p>Cookies and browser local storage (HTML5 <code>localStorage</code>) are small text fragments stored directly on your computing device by your web browser. 90+ SUPPLY minimizes reliance on traditional advertising cookies in favor of secure, client-side browser tokens designed to ensure responsive offline browsing.</p>
            </div>

            <div class="policy-section">
              <h2><i data-lucide="layers" style="color: #c8ff2e;"></i> 2. Categories of Storage Employed</h2>

              <div class="policy-table-wrap">
                <table class="policy-table">
                  <thead>
                    <tr>
                      <th>TOKEN / KEY</th>
                      <th>CATEGORY</th>
                      <th>PURPOSE & LIFESPAN</th>
                    </tr>
                  </thead>
                  <tbody>
                    <tr>
                      <td><strong>90p_cart</strong></td>
                      <td>Strictly Necessary</td>
                      <td>Preserves selected gear in your match bag across browser sessions so your cart does not reset. Permanent until cleared.</td>
                    </tr>
                    <tr>
                      <td><strong>90p_auth_session</strong></td>
                      <td>Strictly Necessary</td>
                      <td>Cryptographic session token for authenticated player locker access via Supabase. Cleared upon logout.</td>
                    </tr>
                    <tr>
                      <td><strong>90p_cookie_consent</strong></td>
                      <td>Strictly Necessary</td>
                      <td>Records your affirmative cookie and telemetry choice (<code>all</code> or <code>essential</code>). Retained for 365 days.</td>
                    </tr>
                    <tr>
                      <td><strong>90p_audio_mute</strong></td>
                      <td>Functional Preference</td>
                      <td>Remembers audio synthesizer mute/unmute state for procedural stadium audio. Persistent client-side.</td>
                    </tr>
                    <tr>
                      <td><strong>90p_telemetry_fps</strong></td>
                      <td>Performance Tuning</td>
                      <td>Measures local WebGL canvas rendering frames per second to dynamically throttle background 3D calculations and save battery.</td>
                    </tr>
                  </tbody>
                </table>
              </div>
            </div>

            <div class="policy-callout">
              <strong>ZERO THIRD-PARTY ADVERTISING OR BEHAVIORAL TRACKERS</strong>
              <p>90+ SUPPLY does not embed third-party surveillance beacons, Facebook Pixel, Google AdSense, or data broker cross-site tracking scripts. Your browsing and CFD trajectory simulations are never monetized or distributed to ad networks.</p>
            </div>

            <div class="policy-section">
              <h2><i data-lucide="sliders" style="color: #c8ff2e;"></i> 3. How to Manage or Revoke Consent</h2>
              <p>Under India's <strong>Digital Personal Data Protection (DPDP) Act 2023</strong>, you retain the absolute statutory right to manage or revoke your consent at any time:</p>
              <ul>
                <li>You can reset your consent choice by clicking the button below, which immediately clears your consent flag and re-opens the consent banner.</li>
                <li>You can configure your browser to block or delete local storage and cookies via your browser settings (Chrome: Settings > Privacy > Clear Browsing Data).</li>
              </ul>

              <div style="margin-top: 20px;">
                <button class="btn btn-outline" id="btnResetConsentInPage" onclick="openCookieConsentBanner()">
                  <i data-lucide="refresh-cw"></i><span>RECONFIGURE COOKIE PREFERENCES</span>
                </button>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  `;

  if (window.lucide) lucide.createIcons();
  // Wire Interactive Cookie Preference Center
  const consent = localStorage.getItem('90p_cookie_consent');
  const tglTelemetry = document.getElementById('prefTelemetryToggle');
  const tglAudio = document.getElementById('prefAudioToggle');
  if (tglTelemetry) tglTelemetry.checked = consent !== 'essential';
  if (tglAudio) tglAudio.checked = consent !== 'essential';

  document.getElementById('btnSaveCookiePrefs')?.addEventListener('click', () => {
    const isTelemetry = document.getElementById('prefTelemetryToggle')?.checked;
    const isAudio = document.getElementById('prefAudioToggle')?.checked;
    const choice = (isTelemetry && isAudio) ? 'all' : (isTelemetry ? 'telemetry' : 'essential');
    try {
      localStorage.setItem('90p_cookie_consent', choice);
      localStorage.setItem('90p_cookie_consent_prefs', JSON.stringify({ telemetry: isTelemetry, audio: isAudio }));
    } catch (e) {}
    if (typeof playSound === 'function') playSound('success');
    if (typeof toast === 'function') toast('Cookie and telemetry preferences successfully updated', 'check-circle');
  });

  document.getElementById('btnRejectAllOptional')?.addEventListener('click', () => {
    if (tglTelemetry) tglTelemetry.checked = false;
    if (tglAudio) tglAudio.checked = false;
    try {
      localStorage.setItem('90p_cookie_consent', 'essential');
      localStorage.setItem('90p_cookie_consent_prefs', JSON.stringify({ telemetry: false, audio: false }));
    } catch (e) {}
    if (typeof playSound === 'function') playSound('click');
    if (typeof toast === 'function') toast('Only strictly necessary local storage enabled', 'shield-check');
  });

}

