                    <input type="tel" id="retPhone" placeholder="e.g. 9876543210" maxlength="10" style="width: 100%; padding: 12px 14px; border-radius: 10px; background: rgba(255,255,255,0.05); border: 1px solid rgba(255,255,255,0.12); color: #f3f4f1; font-family: var(--fm); font-size: 0.82rem;" required />
