/* ================================================================
   CR7 HIGH-RES PBR KIT & FACIAL TEXTURE GENERATORS
   ================================================================ */
function createCr7BackTexture() {
  const canvas = document.createElement('canvas');
  canvas.width = 512;
  canvas.height = 512;
  const ctx = canvas.getContext('2d');
  ctx.clearRect(0, 0, 512, 512);

  // Curved Name Arc
  ctx.font = 'bold 52px "Space Grotesk", sans-serif';
  ctx.fillStyle = '#ffffff';
  ctx.textAlign = 'center';
  ctx.letterSpacing = '6px';
  ctx.fillText('RONALDO', 256, 100);

  // Number 7 with royal blue border and white/gold core
  ctx.font = '900 280px "Space Grotesk", sans-serif';
  ctx.strokeStyle = '#142e7b';
  ctx.lineWidth = 18;
  ctx.strokeText('7', 256, 360);
  ctx.fillStyle = '#ffffff';
  ctx.fillText('7', 256, 360);

  // Al-Nassr emblem at base of number 7
  ctx.font = 'bold 28px sans-serif';
  ctx.fillStyle = '#f7c815';
  ctx.fillText('★ ★', 256, 420);

  const tex = new THREE.CanvasTexture(canvas);
  tex.anisotropy = 8;
  return tex;
}

function createCr7FrontTexture() {
  const canvas = document.createElement('canvas');
  canvas.width = 512;
  canvas.height = 512;
  const ctx = canvas.getContext('2d');
  ctx.clearRect(0, 0, 512, 512);

  // Al-Nassr Crest Shield on Left Chest (Screen right from front)
  ctx.fillStyle = '#142e7b';
  ctx.beginPath();
  ctx.moveTo(350, 80);
  ctx.lineTo(430, 80);
  ctx.lineTo(430, 150);
  ctx.quadraticCurveTo(390, 200, 390, 200);
  ctx.quadraticCurveTo(350, 150, 350, 150);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = '#f7c815';
  ctx.lineWidth = 6;
  ctx.stroke();

  // Gold Palm & Crown
  ctx.fillStyle = '#f7c815';
  ctx.font = 'bold 36px sans-serif';
  ctx.textAlign = 'center';
  ctx.fillText('👑', 390, 130);
  ctx.font = 'bold 20px sans-serif';
  ctx.fillText('🌴', 390, 165);

  // Front Sponsor Banner ("SHURFAN" in clean navy/white bar)
  ctx.fillStyle = '#142e7b';
  ctx.beginPath();
  ctx.roundRect(76, 260, 360, 80, 14);
  ctx.fill();
  ctx.strokeStyle = '#f7c815';
  ctx.lineWidth = 4;
  ctx.stroke();

  ctx.font = 'bold 38px "Space Grotesk", sans-serif';
  ctx.fillStyle = '#ffffff';
  ctx.textAlign = 'center';
  ctx.fillText('SHURFAN', 256, 314);

  const tex = new THREE.CanvasTexture(canvas);
  tex.anisotropy = 8;
  return tex;
}

function createCr7FaceTexture() {
  const canvas = document.createElement('canvas');
  canvas.width = 256;
  canvas.height = 256;
  const ctx = canvas.getContext('2d');
  ctx.clearRect(0, 0, 256, 256);

  // Sharp Eyebrows
  ctx.fillStyle = '#15100c';
  ctx.beginPath();
  ctx.moveTo(60, 88); ctx.lineTo(108, 82); ctx.lineTo(106, 92); ctx.lineTo(62, 95); ctx.fill();
  ctx.beginPath();
  ctx.moveTo(148, 82); ctx.lineTo(196, 88); ctx.lineTo(194, 95); ctx.lineTo(150, 92); ctx.fill();

  // Determined Eyes
  ctx.fillStyle = '#ffffff';
  ctx.beginPath();
  ctx.ellipse(84, 106, 16, 7, 0, 0, Math.PI * 2);
  ctx.ellipse(172, 106, 16, 7, 0, 0, Math.PI * 2);
  ctx.fill();

  ctx.fillStyle = '#3a271d';
  ctx.beginPath();
  ctx.arc(84, 106, 6.5, 0, Math.PI * 2);
  ctx.arc(172, 106, 6.5, 0, Math.PI * 2);
  ctx.fill();

  ctx.fillStyle = '#0a0a0a';
  ctx.beginPath();
  ctx.arc(84, 106, 3, 0, Math.PI * 2);
  ctx.arc(172, 106, 3, 0, Math.PI * 2);
  ctx.fill();

  // Determined match-face lips
  ctx.fillStyle = '#a66450';
  ctx.beginPath();
  ctx.roundRect(104, 182, 48, 8, 4);
  ctx.fill();

  const tex = new THREE.CanvasTexture(canvas);
  tex.anisotropy = 8;
  return tex;
}

function buildKickerMesh(profile) {
  if (!THREE || !profile) return null;

  const rootGroup = new THREE.Group();
  const h = profile.height || 1.75;
  const scale = h / 1.75;
  const isCr7 = profile.id === 'cr7';

  // High-Fidelity PBR Materials
  const jerseyMat = new THREE.MeshStandardMaterial({
    color: profile.jerseyPrimary,
    roughness: 0.48,
    metalness: 0.08
  });
  const trimMat = new THREE.MeshStandardMaterial({
    color: profile.jerseySecondary,
    roughness: 0.42,
    metalness: 0.12
  });
  const shortsMat = new THREE.MeshStandardMaterial({
    color: profile.shortsColor,
    roughness: 0.55,
    metalness: 0.05
  });
  const skinMat = new THREE.MeshStandardMaterial({
    color: profile.skinColor,
    roughness: 0.68,
    metalness: 0.02
  });
  const socksMat = new THREE.MeshStandardMaterial({
    color: profile.socksColor,
    roughness: 0.52
  });
  const bootMat = new THREE.MeshStandardMaterial({
    color: profile.bootColor,
    roughness: 0.32,
    metalness: 0.18
  });
  const hairMat = new THREE.MeshStandardMaterial({
    color: profile.hairColor,
    roughness: 0.88
  });
  const goldMat = new THREE.MeshStandardMaterial({
    color: 0xf7c815,
    roughness: 0.35,
    metalness: 0.35
  });
  const whiteMat = new THREE.MeshStandardMaterial({
    color: 0xffffff,
    roughness: 0.30
  });

  const bodyGroup = new THREE.Group();

  // ============================================================
  // ANATOMICAL SCULPTED TORSO (ATHLETIC V-TAPER, NOT A BLOCK!)
  // ============================================================
  if (isCr7) {
    // Upper Chest & Broad Shoulders (Anatomical oval cross-section)
    const upperChestGeo = new THREE.CylinderGeometry(0.22 * scale, 0.175 * scale, 0.26 * scale, 24);
    const upperChest = new THREE.Mesh(upperChestGeo, jerseyMat);
    upperChest.scale.set(1.0, 1.0, 0.62); // Natural human flattened chest
    upperChest.position.y = 1.18 * scale;
    upperChest.castShadow = true;
    bodyGroup.add(upperChest);

    // Lower Torso & Athletic Tapered Waist
    const waistGeo = new THREE.CylinderGeometry(0.175 * scale, 0.155 * scale, 0.20 * scale, 24);
    const waist = new THREE.Mesh(waistGeo, jerseyMat);
    waist.scale.set(1.0, 1.0, 0.60);
    waist.position.y = 0.96 * scale;
    waist.castShadow = true;
    bodyGroup.add(waist);

    // Al-Nassr Royal Blue Raglan Shoulders Yoke
    const yokeGeo = new THREE.CylinderGeometry(0.225 * scale, 0.20 * scale, 0.13 * scale, 24);
    const yokeMesh = new THREE.Mesh(yokeGeo, trimMat);
    yokeMesh.scale.set(1.02, 1.0, 0.64);
    yokeMesh.position.y = 1.25 * scale;
    bodyGroup.add(yokeMesh);

    // Rounded Crew-Neck Collar with Gold Piping
    const collarGeo = new THREE.TorusGeometry(0.082 * scale, 0.014 * scale, 12, 24);
    const collarMesh = new THREE.Mesh(collarGeo, trimMat);
    collarMesh.rotation.x = Math.PI / 2;
    collarMesh.position.set(0, 1.31 * scale, 0);
    bodyGroup.add(collarMesh);

    const goldPipingGeo = new THREE.TorusGeometry(0.086 * scale, 0.006 * scale, 8, 24);
    const goldPiping = new THREE.Mesh(goldPipingGeo, goldMat);
    goldPiping.rotation.x = Math.PI / 2;
    goldPiping.position.set(0, 1.315 * scale, 0);
    bodyGroup.add(goldPiping);

    // Left & Right Deltoid Shoulder Caps (Smooth arm-torso blend)
    [-0.23, 0.23].forEach(dx => {
      const deltGeo = new THREE.SphereGeometry(0.068 * scale, 16, 16);
      const deltMesh = new THREE.Mesh(deltGeo, trimMat);
      deltMesh.position.set(dx * scale, 1.23 * scale, 0);
      bodyGroup.add(deltMesh);
    });

    // High-Resolution Front Kit Decal (Crest & Sponsor)
    const frontDecalGeo = new THREE.PlaneGeometry(0.24 * scale, 0.24 * scale);
    const frontDecalMat = new THREE.MeshBasicMaterial({ map: createCr7FrontTexture(), transparent: true });
    const frontDecal = new THREE.Mesh(frontDecalGeo, frontDecalMat);
    frontDecal.position.set(0, 1.15 * scale, 0.145 * scale);
    bodyGroup.add(frontDecal);

    // High-Resolution Back Kit Decal (RONALDO #7)
    const backDecalGeo = new THREE.PlaneGeometry(0.26 * scale, 0.26 * scale);
    const backDecalMat = new THREE.MeshBasicMaterial({ map: createCr7BackTexture(), transparent: true });
    const backDecal = new THREE.Mesh(backDecalGeo, backDecalMat);
    backDecal.rotation.y = Math.PI;
    backDecal.position.set(0, 1.18 * scale, -0.145 * scale);
    bodyGroup.add(backDecal);

    // Pelvis & Hip Core (Waistband of Shorts)
    const pelvisGeo = new THREE.CylinderGeometry(0.162 * scale, 0.165 * scale, 0.12 * scale, 24);
    const pelvisMesh = new THREE.Mesh(pelvisGeo, shortsMat);
    pelvisMesh.scale.set(1.0, 1.0, 0.62);
    pelvisMesh.position.y = 0.81 * scale;
    bodyGroup.add(pelvisMesh);

    // Gold Waistband Rim
    const waistRimGeo = new THREE.TorusGeometry(0.164 * scale, 0.008 * scale, 8, 24);
    const waistRim = new THREE.Mesh(waistRimGeo, goldMat);
    waistRim.rotation.x = Math.PI / 2;
    waistRim.scale.set(1.0, 0.62, 1.0);
    waistRim.position.set(0, 0.86 * scale, 0);
    bodyGroup.add(waistRim);

  } else {
    // Default fallback torso for other presets
    const torsoGeo = new THREE.CylinderGeometry(0.20 * scale, 0.16 * scale, 0.44 * scale, 18);
    const torso = new THREE.Mesh(torsoGeo, jerseyMat);
    torso.scale.set(1.0, 1.0, 0.62);
    torso.position.y = 1.08 * scale;
    torso.castShadow = true;
    bodyGroup.add(torso);

    const pelvisGeo = new THREE.CylinderGeometry(0.16 * scale, 0.16 * scale, 0.14 * scale, 18);
    const pelvisMesh = new THREE.Mesh(pelvisGeo, shortsMat);
    pelvisMesh.scale.set(1.0, 1.0, 0.62);
    pelvisMesh.position.y = 0.80 * scale;
    bodyGroup.add(pelvisMesh);
  }

  // Back Number Plate (#7 RONALDO)
  const numBackGeo = new THREE.PlaneGeometry(0.16 * scale, 0.20 * scale);
  const numMesh = new THREE.Mesh(numBackGeo, isCr7 ? goldMat : whiteMat);
  numMesh.rotation.y = Math.PI;
  numMesh.position.set(0, 1.10 * scale, -0.114 * scale);
  bodyGroup.add(numMesh);

  // ============================================================
  // ANATOMICAL CR7 HEAD, JAW & FADE HAIRSTYLE
  // ============================================================
  const neckGeo = new THREE.CylinderGeometry(0.062 * scale, 0.075 * scale, 0.12 * scale, 16);
  const neck = new THREE.Mesh(neckGeo, skinMat);
  neck.position.y = 1.34 * scale;
  bodyGroup.add(neck);

  if (isCr7) {
    // Cranial Head (Oval human contour)
    const headGeo = new THREE.SphereGeometry(0.105 * scale, 20, 20);
    const head = new THREE.Mesh(headGeo, skinMat);
    head.scale.set(0.88, 1.15, 0.95);
    head.position.y = 1.45 * scale;
    head.castShadow = true;
    bodyGroup.add(head);

    // Chiseled Jawline & Chin
    const jawGeo = new THREE.CylinderGeometry(0.082 * scale, 0.052 * scale, 0.09 * scale, 16);
    const jaw = new THREE.Mesh(jawGeo, skinMat);
    jaw.scale.set(0.85, 1.0, 0.88);
    jaw.position.set(0, 1.39 * scale, 0.015 * scale);
    bodyGroup.add(jaw);

    // Brow Ridge & Nose Bridge
    const noseGeo = new THREE.ConeGeometry(0.022 * scale, 0.045 * scale, 8);
    const nose = new THREE.Mesh(noseGeo, skinMat);
    nose.rotation.x = -Math.PI / 2.2;
    nose.position.set(0, 1.44 * scale, 0.095 * scale);
    bodyGroup.add(nose);

    // Athletic Ears
    [-0.092, 0.092].forEach(ex => {
      const earGeo = new THREE.SphereGeometry(0.022 * scale, 8, 8);
      const ear = new THREE.Mesh(earGeo, skinMat);
      ear.scale.set(0.5, 1.2, 0.8);
      ear.position.set(ex * scale, 1.44 * scale, 0);
      bodyGroup.add(ear);
    });

    // High Skin Fade (Sides and back of head)
    const fadeGeo = new THREE.SphereGeometry(0.108 * scale, 20, 20, 0, Math.PI * 2, 0, Math.PI * 0.52);
    const fadeMesh = new THREE.Mesh(fadeGeo, hairMat);
    fadeMesh.scale.set(0.89, 1.16, 0.96);
    fadeMesh.position.set(0, 1.455 * scale, -0.005 * scale);
    bodyGroup.add(fadeMesh);

    // Textured Pompadour Crown (Swept back and up)
    const pompadourGeo = new THREE.SphereGeometry(0.092 * scale, 16, 16);
    const pompadour = new THREE.Mesh(pompadourGeo, hairMat);
    pompadour.scale.set(0.85, 0.55, 1.20);
    pompadour.rotation.x = -0.15;
    pompadour.position.set(0.008 * scale, 1.545 * scale, -0.01 * scale);
    bodyGroup.add(pompadour);

  } else {
    // Standard head for other players
    const headGeo = new THREE.SphereGeometry(0.105 * scale, 16, 16);
    const head = new THREE.Mesh(headGeo, skinMat);
    head.position.y = 1.42 * scale;
    head.castShadow = true;
    bodyGroup.add(head);

    const hairGeo = new THREE.SphereGeometry(0.112 * scale, 16, 16, 0, Math.PI * 2, 0, Math.PI * 0.55);
    const hairMesh = new THREE.Mesh(hairGeo, hairMat);
    hairMesh.position.set(0, 1.43 * scale, -0.01 * scale);
    bodyGroup.add(hairMesh);
  }

  // ============================================================
  // ARMS, SHORT SLEEVES & CAPTAIN'S ARMBAND
  // ============================================================
  const armMat = isCr7 ? trimMat : jerseyMat;

  // Left Arm Group
  const leftArm = new THREE.Group();
  leftArm.position.set(-0.25 * scale, 1.22 * scale, 0);

  // Upper raglan sleeve
  const leftSleeveGeo = new THREE.CylinderGeometry(0.054 * scale, 0.048 * scale, 0.16 * scale, 16);
  const leftSleeve = new THREE.Mesh(leftSleeveGeo, armMat);
  leftSleeve.position.y = -0.08 * scale;
  leftArm.add(leftSleeve);

  // Left bicep
  const leftBicepGeo = new THREE.CylinderGeometry(0.046 * scale, 0.040 * scale, 0.15 * scale, 16);
  const leftBicep = new THREE.Mesh(leftBicepGeo, skinMat);
  leftBicep.position.y = -0.22 * scale;
  leftArm.add(leftBicep);

  // CR7 White Captain's Armband (Wrapped around left bicep)
  if (isCr7) {
    const bandGeo = new THREE.CylinderGeometry(0.049 * scale, 0.047 * scale, 0.065 * scale, 18);
    const band = new THREE.Mesh(bandGeo, whiteMat);
    band.position.y = -0.18 * scale;
    leftArm.add(band);

    const cEmblemGeo = new THREE.PlaneGeometry(0.035 * scale, 0.04 * scale);
    const cEmblem = new THREE.Mesh(cEmblemGeo, trimMat);
    cEmblem.rotation.y = -Math.PI / 2;
    cEmblem.position.set(-0.050 * scale, -0.18 * scale, 0);
    leftArm.add(cEmblem);
  }

  // Left Forearm & Hand
  const leftForearmGeo = new THREE.CylinderGeometry(0.040 * scale, 0.032 * scale, 0.20 * scale, 16);
  const leftForearm = new THREE.Mesh(leftForearmGeo, skinMat);
  leftForearm.position.y = -0.38 * scale;
  leftArm.add(leftForearm);

  const leftHandGeo = new THREE.SphereGeometry(0.034 * scale, 12, 12);
  const leftHand = new THREE.Mesh(leftHandGeo, skinMat);
  leftHand.scale.set(0.6, 1.2, 0.9);
  leftHand.position.y = -0.50 * scale;
  leftArm.add(leftHand);

  bodyGroup.add(leftArm);

  // Right Arm Group
  const rightArm = new THREE.Group();
  rightArm.position.set(0.25 * scale, 1.22 * scale, 0);

  const rightSleeveGeo = new THREE.CylinderGeometry(0.054 * scale, 0.048 * scale, 0.16 * scale, 16);
  const rightSleeve = new THREE.Mesh(rightSleeveGeo, armMat);
  rightSleeve.position.y = -0.08 * scale;
  rightArm.add(rightSleeve);

  const rightBicepGeo = new THREE.CylinderGeometry(0.046 * scale, 0.040 * scale, 0.15 * scale, 16);
  const rightBicep = new THREE.Mesh(rightBicepGeo, skinMat);
  rightBicep.position.y = -0.22 * scale;
  rightArm.add(rightBicep);

  const rightForearmGeo = new THREE.CylinderGeometry(0.040 * scale, 0.032 * scale, 0.20 * scale, 16);
  const rightForearm = new THREE.Mesh(rightForearmGeo, skinMat);
  rightForearm.position.y = -0.38 * scale;
  rightArm.add(rightForearm);

  const rightHandGeo = new THREE.SphereGeometry(0.034 * scale, 12, 12);
  const rightHand = new THREE.Mesh(rightHandGeo, skinMat);
  rightHand.scale.set(0.6, 1.2, 0.9);
  rightHand.position.y = -0.50 * scale;
  rightArm.add(rightHand);

  bodyGroup.add(rightArm);

  rootGroup.add(bodyGroup);

  // ============================================================
  // SPLIT SHORTS & ARTICULATED LEGS (SHORTS ROTATE WITH THIGHS!)
  // ============================================================

  // Left Leg
  const leftLeg = new THREE.Group();
  leftLeg.position.set(-0.115 * scale, 0.76 * scale, 0);

  // Left Shorts Barrel (Rotates WITH thigh — no clipping through static box!)
  const leftShortsGeo = new THREE.CylinderGeometry(0.096 * scale, 0.086 * scale, 0.18 * scale, 18);
  const leftShorts = new THREE.Mesh(leftShortsGeo, shortsMat);
  leftShorts.position.y = -0.08 * scale;
  leftLeg.add(leftShorts);

  if (isCr7) {
    // Gold speed stripe on lateral shorts seam
    const stripeGeo = new THREE.PlaneGeometry(0.02 * scale, 0.16 * scale);
    const stripeMesh = new THREE.Mesh(stripeGeo, goldMat);
    stripeMesh.rotation.y = -Math.PI / 2;
    stripeMesh.position.set(-0.097 * scale, -0.08 * scale, 0);
    leftLeg.add(stripeMesh);
  }

  // Muscular Left Thigh (Quadriceps bulge)
  const leftThighGeo = new THREE.CylinderGeometry(0.076 * scale, 0.058 * scale, 0.30 * scale, 18);
  const leftThigh = new THREE.Mesh(leftThighGeo, skinMat);
  leftThigh.position.y = -0.17 * scale;
  leftLeg.add(leftThigh);

  // Left Knee Joint
  const leftKneeGeo = new THREE.SphereGeometry(0.055 * scale, 14, 14);
  const leftKnee = new THREE.Mesh(leftKneeGeo, skinMat);
  leftKnee.position.set(0, -0.32 * scale, 0.01 * scale);
  leftLeg.add(leftKnee);

  // Left Shin & Sock Group
  const leftShinGroup = new THREE.Group();
  leftShinGroup.position.set(0, -0.32 * scale, 0);

  // Royal Blue Match Sock
  const leftShinGeo = new THREE.CylinderGeometry(0.058 * scale, 0.044 * scale, 0.32 * scale, 18);
  const leftShin = new THREE.Mesh(leftShinGeo, socksMat);
  leftShin.position.y = -0.16 * scale;
  leftShinGroup.add(leftShin);

  if (isCr7) {
    // Canary Gold Turnover Cuff
    const cuffGeo = new THREE.CylinderGeometry(0.062 * scale, 0.058 * scale, 0.045 * scale, 18);
    const cuffMesh = new THREE.Mesh(cuffGeo, goldMat);
    cuffMesh.position.y = -0.022 * scale;
    leftShinGroup.add(cuffMesh);
  }

  // Sculpted White Strike Boot (Curved football boot, not a box!)
  const bootBodyGeo = new THREE.CylinderGeometry(0.046 * scale, 0.040 * scale, 0.12 * scale, 14);
  const leftBootBody = new THREE.Mesh(bootBodyGeo, bootMat);
  leftBootBody.rotation.x = Math.PI / 2;
  leftBootBody.scale.set(0.9, 1.4, 0.8);
  leftBootBody.position.set(0, -0.33 * scale, 0.04 * scale);
  leftShinGroup.add(leftBootBody);

  const leftToeGeo = new THREE.SphereGeometry(0.038 * scale, 12, 12);
  const leftToe = new THREE.Mesh(leftToeGeo, bootMat);
  leftToe.scale.set(0.9, 0.65, 1.2);
  leftToe.position.set(0, -0.34 * scale, 0.11 * scale);
  leftShinGroup.add(leftToe);

  if (isCr7) {
    // Optic blue speed accent on boot instep
    const accentGeo = new THREE.PlaneGeometry(0.015 * scale, 0.07 * scale);
    const accent = new THREE.Mesh(accentGeo, trimMat);
    accent.rotation.set(-Math.PI / 2, 0, 0.3);
    accent.position.set(0.03 * scale, -0.32 * scale, 0.06 * scale);
    leftShinGroup.add(accent);
  }

  leftLeg.add(leftShinGroup);
  rootGroup.add(leftLeg);

  // Right Leg
  const rightLeg = new THREE.Group();
  rightLeg.position.set(0.115 * scale, 0.76 * scale, 0);

  // Right Shorts Barrel (Rotates WITH thigh!)
  const rightShortsGeo = new THREE.CylinderGeometry(0.096 * scale, 0.086 * scale, 0.18 * scale, 18);
  const rightShorts = new THREE.Mesh(rightShortsGeo, shortsMat);
  rightShorts.position.y = -0.08 * scale;
  rightLeg.add(rightShorts);

  if (isCr7) {
    const stripeGeo = new THREE.PlaneGeometry(0.02 * scale, 0.16 * scale);
    const stripeMesh = new THREE.Mesh(stripeGeo, goldMat);
    stripeMesh.rotation.y = Math.PI / 2;
    stripeMesh.position.set(0.097 * scale, -0.08 * scale, 0);
    rightLeg.add(stripeMesh);
  }

  // Muscular Right Thigh
  const rightThighGeo = new THREE.CylinderGeometry(0.076 * scale, 0.058 * scale, 0.30 * scale, 18);
  const rightThigh = new THREE.Mesh(rightThighGeo, skinMat);
  rightThigh.position.y = -0.17 * scale;
  rightLeg.add(rightThigh);

  // Right Knee Joint
  const rightKneeGeo = new THREE.SphereGeometry(0.055 * scale, 14, 14);
  const rightKnee = new THREE.Mesh(rightKneeGeo, skinMat);
  rightKnee.position.set(0, -0.32 * scale, 0.01 * scale);
  rightLeg.add(rightKnee);

  // Right Shin & Sock Group
  const rightShinGroup = new THREE.Group();
  rightShinGroup.position.set(0, -0.32 * scale, 0);

  const rightShinGeo = new THREE.CylinderGeometry(0.058 * scale, 0.044 * scale, 0.32 * scale, 18);
  const rightShin = new THREE.Mesh(rightShinGeo, socksMat);
  rightShin.position.y = -0.16 * scale;
  rightShinGroup.add(rightShin);

  if (isCr7) {
    const cuffGeo = new THREE.CylinderGeometry(0.062 * scale, 0.058 * scale, 0.045 * scale, 18);
    const cuffMesh = new THREE.Mesh(cuffGeo, goldMat);
    cuffMesh.position.y = -0.022 * scale;
    rightShinGroup.add(cuffMesh);
  }

  // Sculpted White Strike Boot
  const rightBootBody = new THREE.Mesh(bootBodyGeo, bootMat);
  rightBootBody.rotation.x = Math.PI / 2;
  rightBootBody.scale.set(0.9, 1.4, 0.8);
  rightBootBody.position.set(0, -0.33 * scale, 0.04 * scale);
  rightShinGroup.add(rightBootBody);

  const rightToe = new THREE.Mesh(leftToeGeo, bootMat);
  rightToe.scale.set(0.9, 0.65, 1.2);
  rightToe.position.set(0, -0.34 * scale, 0.11 * scale);
  rightShinGroup.add(rightToe);

  if (isCr7) {
    const accentGeo = new THREE.PlaneGeometry(0.015 * scale, 0.07 * scale);
    const accent = new THREE.Mesh(accentGeo, trimMat);
    accent.rotation.set(-Math.PI / 2, 0, -0.3);
    accent.position.set(-0.03 * scale, -0.32 * scale, 0.06 * scale);
    rightShinGroup.add(accent);
  }

  rightLeg.add(rightShinGroup);
  rootGroup.add(rightLeg);

  return {
    rootGroup,
    bodyGroup,
    leftArm,
    rightArm,
    leftLeg,
    rightLeg,
    leftShinGroup,
    rightShinGroup,
    profile,
    scale
  };
}

function spawnKicker(kickerId) {
  const profile = KICKER_PROFILES[kickerId] || KICKER_PROFILES.messi;
  currentKickerKey = profile.id;

  if (trajectKickerData && trajectKickerData.rootGroup && trajectScene) {
    trajectScene.remove(trajectKickerData.rootGroup);
    trajectKickerData = null;
  }

  trajectKickerData = buildKickerMesh(profile);
  if (trajectKickerData && trajectScene) {
    trajectScene.add(trajectKickerData.rootGroup);
    resetKickerToStance();
  }

  const nameEl = document.getElementById('trajectStrikerName');
  if (nameEl) {
    nameEl.textContent = `${profile.name.toUpperCase()} #${profile.number} ${profile.flag}`;
  }
}

function resetKickerToStance() {
  if (!trajectKickerData) return;
  const p = trajectKickerData.profile;
  const startZ = trajectMode === 'penalty' ? 13.0 : 0.0;
  const off = p.runUpOffset;

  trajectKickerData.rootGroup.position.set(off.x, 0, startZ + off.z);
  trajectKickerData.rootGroup.rotation.set(0, off.rotY, 0);

  trajectKickerData.bodyGroup.position.set(0, 0, 0);
  trajectKickerData.bodyGroup.rotation.set(0, 0, 0);

  if (p.id === 'cr7') {
    // Iconic wide-legged CR7 power stance (0.85m spread, ready for knuckleball)
    trajectKickerData.leftLeg.rotation.set(-0.06, 0, -0.28);
    trajectKickerData.rightLeg.rotation.set(-0.06, 0, 0.28);
    trajectKickerData.leftShinGroup.rotation.set(0.10, 0, 0);
    trajectKickerData.rightShinGroup.rotation.set(0.10, 0, 0);
    trajectKickerData.leftArm.rotation.set(0.14, 0, 0.26);
    trajectKickerData.rightArm.rotation.set(0.14, 0, -0.26);
  } else if (p.id === 'beckham') {
    trajectKickerData.leftLeg.rotation.set(0, 0, -0.08);
    trajectKickerData.rightLeg.rotation.set(0, 0, 0.08);
    trajectKickerData.leftShinGroup.rotation.set(0, 0, 0);
    trajectKickerData.rightShinGroup.rotation.set(0, 0, 0);
    trajectKickerData.leftArm.rotation.set(0.2, 0, 0.45);
    trajectKickerData.rightArm.rotation.set(0, 0, -0.2);
  } else if (p.id === 'carlos') {
    trajectKickerData.bodyGroup.position.y = -0.04;
    trajectKickerData.bodyGroup.rotation.x = 0.18;
    trajectKickerData.leftLeg.rotation.set(-0.18, 0, -0.12);
    trajectKickerData.rightLeg.rotation.set(0.22, 0, 0.12);
    trajectKickerData.leftShinGroup.rotation.set(0.25, 0, 0);
    trajectKickerData.rightShinGroup.rotation.set(0.10, 0, 0);
    trajectKickerData.leftArm.rotation.set(-0.3, 0, 0.2);
    trajectKickerData.rightArm.rotation.set(0.3, 0, -0.2);
  } else {
    trajectKickerData.leftLeg.rotation.set(0, 0, -0.08);
    trajectKickerData.rightLeg.rotation.set(0, 0, 0.08);
    trajectKickerData.leftShinGroup.rotation.set(0.04, 0, 0);
    trajectKickerData.rightShinGroup.rotation.set(0.04, 0, 0);
    trajectKickerData.leftArm.rotation.set(0.05, 0, 0.18);
    trajectKickerData.rightArm.rotation.set(0.05, 0, -0.18);
  }
}

function updateKickerIdle(time) {
  if (!trajectKickerData || isStriking) return;
  const p = trajectKickerData.profile;
  const breath = Math.sin(time * 2.4) * 0.016;
  trajectKickerData.bodyGroup.position.y = breath;

  if (p.id === 'cr7') {
    // Deep chest respiration & focused micro-sway
    trajectKickerData.bodyGroup.rotation.x = breath * 0.8;
    trajectKickerData.leftArm.rotation.z = 0.26 + breath * 0.5;
    trajectKickerData.rightArm.rotation.z = -0.26 - breath * 0.5;
  } else if (p.id === 'neymar') {
    const sambaShift = Math.sin(time * 3.5) * 0.04;
    trajectKickerData.leftLeg.rotation.x = sambaShift;
    trajectKickerData.rightLeg.rotation.x = -sambaShift;
  }
}

function animateKickerRunUpAndStrike(onImpact) {
  if (!trajectKickerData) {
    onImpact();
    return;
  }

  const p = trajectKickerData.profile;
  const startZ = trajectMode === 'penalty' ? 13.0 : 0.0;
  const off = p.runUpOffset;

  const startPos = new THREE.Vector3(off.x, 0, startZ + off.z);
  const isLeftFoot = p.foot === 'left';
  const plantPos = new THREE.Vector3(
    isLeftFoot ? 0.24 : -0.24,
    0,
    startZ - 0.10
  );

  // Biomechanical Run-up Duration (1.15s for full athletic stride mechanics)
  const runDuration = (p.id === 'carlos' ? 1.45 : (p.id === 'cr7' ? 1.15 : 0.95)) / (p.runUpSpeed || 1.0);
  const startTime = performance.now();
  let hasImpacted = false;

  const kickingLeg = isLeftFoot ? trajectKickerData.leftLeg : trajectKickerData.rightLeg;
  const kickingShin = isLeftFoot ? trajectKickerData.leftShinGroup : trajectKickerData.rightShinGroup;
  const plantLeg = isLeftFoot ? trajectKickerData.rightLeg : trajectKickerData.leftLeg;
  const plantShin = isLeftFoot ? trajectKickerData.rightShinGroup : trajectKickerData.leftShinGroup;

  function kickerAnimStep() {
    const elapsed = (performance.now() - startTime) / 1000;
    const progress = Math.min(1.0, elapsed / runDuration);

    // ============================================================
    // PHASE 1: DYNAMIC APPROACH RUN (0 <= progress < 0.78)
    // Full leg stride kinematics: hip flexion/extension & knee whip
    // ============================================================
    if (progress < 0.78) {
      const runFrac = progress / 0.78;
      // Smooth sprint acceleration curve
      const tNorm = runFrac * runFrac * (3 - 2 * runFrac);
      trajectKickerData.rootGroup.position.lerpVectors(startPos, plantPos, tNorm);

      const targetRotY = Math.atan2(-trajectKickerData.rootGroup.position.x, 24.0 - trajectKickerData.rootGroup.position.z) * 0.28;
      trajectKickerData.rootGroup.rotation.y = THREE.MathUtils.lerp(off.rotY, targetRotY, runFrac);

      // 4 Athletic Sprint Strides: active dual-leg pumping!
      const strideFreq = 16.5;
      const legAngle = Math.sin(elapsed * strideFreq) * 0.78;

      // Hip flexion/extension
      kickingLeg.rotation.set(legAngle, 0, isLeftFoot ? -0.05 : 0.05);
      plantLeg.rotation.set(-legAngle, 0, isLeftFoot ? 0.05 : -0.05);

      // Deep knee bending during backstride recovery
      kickingShin.rotation.set(Math.max(0, -legAngle * 1.30), 0, 0);
      plantShin.rotation.set(Math.max(0, legAngle * 1.30), 0, 0);

      // Spring-mass vertical pelvis bobbing
      trajectKickerData.bodyGroup.position.y = Math.abs(Math.sin(elapsed * strideFreq)) * 0.042;

      // Synchronized counter-balancing arm pump
      trajectKickerData.leftArm.rotation.set(-legAngle * 0.75, 0, 0.18);
      trajectKickerData.rightArm.rotation.set(legAngle * 0.75, 0, -0.18);

    // ============================================================
    // PHASE 2: PLANT FOOT GROUND REACTION & KICKING LEG BACKSWING (0.78 <= progress < 0.93)
    // Firm ground plant, torso lean, and deep elastic energy load
    // ============================================================
    } else if (progress < 0.93) {
      const plantFrac = (progress - 0.78) / 0.15;
      trajectKickerData.rootGroup.position.copy(plantPos);

      // Plant leg absorbs ground reaction force: slight knee flexion
      plantLeg.rotation.set(0.14 * plantFrac, 0, isLeftFoot ? 0.08 : -0.08);
      plantShin.rotation.set(0.12 * plantFrac, 0, 0);

      // Kicking leg deep backswing: hip hyper-extension (-58 deg) + tight knee flexion (105 deg)
      kickingLeg.rotation.set(-1.02 * plantFrac, 0, isLeftFoot ? -0.08 : 0.08);
      kickingShin.rotation.set(1.82 * plantFrac, 0, 0);

      // Torso leans over the ball to keep knuckleball low & prevent skyball
      trajectKickerData.bodyGroup.rotation.x = -0.26 * plantFrac;
      trajectKickerData.bodyGroup.rotation.z = (isLeftFoot ? -1 : 1) * 0.18 * plantFrac;

      // Non-kicking arm abducts for gyroscopic balance
      if (isLeftFoot) {
        trajectKickerData.rightArm.rotation.set(0.25 * plantFrac, 0, -0.85 * plantFrac);
      } else {
        trajectKickerData.leftArm.rotation.set(0.25 * plantFrac, 0, 0.85 * plantFrac);
      }

    // ============================================================
    // PHASE 3: EXPLOSIVE LEG WHIP ACCELERATION (0.93 <= progress < 1.0)
    // Violent knee extension snap into the ball center
    // ============================================================
    } else if (progress < 1.0) {
      const whipFrac = (progress - 0.93) / 0.07;
      const whipEase = whipFrac * whipFrac * (3 - 2 * whipFrac);

      // Thigh whips forward from -58 deg to +46 deg
      const thighAngle = THREE.MathUtils.lerp(-1.02, 0.80, whipEase);
      kickingLeg.rotation.set(thighAngle, 0, isLeftFoot ? -0.04 : 0.04);

      // Knee snaps violently forward from 105 deg flexion to 8 deg extension!
      const kneeAngle = THREE.MathUtils.lerp(1.82, 0.14, whipEase);
      kickingShin.rotation.set(kneeAngle, 0, 0);

      trajectKickerData.bodyGroup.rotation.x = THREE.MathUtils.lerp(-0.26, 0.12, whipEase);

    // ============================================================
    // PHASE 4: IMPACT MOMENT & KNUCKLEBALL PUNCH FOLLOW-THROUGH (progress >= 1.0)
    // Direct punch follow-through with minimal spin + smooth landing
    // ============================================================
    } else {
      if (!hasImpacted) {
        hasImpacted = true;
        kickingLeg.rotation.set(0.85, 0, isLeftFoot ? -0.04 : 0.04);
        kickingShin.rotation.set(0.08, 0, 0);
        trajectKickerData.bodyGroup.rotation.x = 0.14;
        onImpact(); // BALL TAKES FLIGHT INSTANTLY!
      }

      const followElapsed = elapsed - runDuration;
      const followDuration = 0.65;
      if (followElapsed < followDuration) {
        const fFrac = followElapsed / followDuration;
        const fEase = Math.sin(fFrac * Math.PI * 0.5);

        // Kicker natural deceleration step onto kicking foot
        trajectKickerData.rootGroup.position.z += 0.008 * (1 - fFrac);
        kickingLeg.rotation.x = THREE.MathUtils.lerp(0.85, 0.12, fEase);
        kickingShin.rotation.x = THREE.MathUtils.lerp(0.08, 0.05, fEase);
        plantLeg.rotation.x = THREE.MathUtils.lerp(0.14, -0.18, fEase);
        trajectKickerData.bodyGroup.rotation.x = THREE.MathUtils.lerp(0.14, 0.02, fEase);
        trajectKickerData.bodyGroup.rotation.z = THREE.MathUtils.lerp((isLeftFoot ? -1 : 1) * 0.18, 0, fEase);
      } else {
        return;
      }
    }

    requestAnimationFrame(kickerAnimStep);
  }

  requestAnimationFrame(kickerAnimStep);
}

/* BUILD HIGH-FIDELITY ARTICULATED 3D GOALKEEPER */
function buildGkMesh(profile) {
  if (!THREE || profile.name === 'Open Goal') return null;

  const rootGroup = new THREE.Group();
  const h = profile.height || 1.88;
  const scale = h / 1.88;

  // Materials
  const jerseyMat = new THREE.MeshStandardMaterial({
    color: profile.color,
    roughness: 0.45,
    metalness: 0.15
  });
  const skinMat = new THREE.MeshStandardMaterial({
    color: profile.skin || 0xd4a574,
    roughness: 0.7
  });
  const shortsMat = new THREE.MeshStandardMaterial({
    color: 0x111315,
    roughness: 0.6
  });
  const gloveMat = new THREE.MeshStandardMaterial({
    color: 0xc8ff2e,
    emissive: 0xc8ff2e,
    emissiveIntensity: 0.25,
    roughness: 0.35,
    metalness: 0.2
  });
  const bootMat = new THREE.MeshStandardMaterial({
    color: 0x0a0a0a,
    roughness: 0.3
  });

  // Articulated Sub-Group for Dives/Body Rotations
  trajectGkBody = new THREE.Group();

  // Torso (Upper body & Jersey)
  const torsoGeo = new THREE.BoxGeometry(0.50 * scale, 0.58 * scale, 0.26 * scale);
  const torso = new THREE.Mesh(torsoGeo, jerseyMat);
  torso.position.y = 1.18 * scale;
  torso.castShadow = true;
  trajectGkBody.add(torso);

  // Jersey Number / Detail Stripe
  const stripeGeo = new THREE.PlaneGeometry(0.22 * scale, 0.28 * scale);
  const stripeMat = new THREE.MeshBasicMaterial({ color: 0xffffff });
  const stripe = new THREE.Mesh(stripeGeo, stripeMat);
  stripe.position.set(0, 1.18 * scale, 0.132 * scale);
  trajectGkBody.add(stripe);

  // Head
  const headGeo = new THREE.SphereGeometry(0.12 * scale, 18, 18);
  const head = new THREE.Mesh(headGeo, skinMat);
  head.position.y = 1.58 * scale;
  head.castShadow = true;
  trajectGkBody.add(head);

  // Goalkeeper Headband / Hair
  const hairGeo = new THREE.SphereGeometry(0.124 * scale, 16, 16, 0, Math.PI * 2, 0, Math.PI * 0.5);
  const hairMat = new THREE.MeshStandardMaterial({ color: 0x1f1810, roughness: 0.9 });
  const hair = new THREE.Mesh(hairGeo, hairMat);
  hair.position.set(0, 1.59 * scale, -0.01 * scale);
  trajectGkBody.add(hair);

  // Shorts
  const shortsGeo = new THREE.BoxGeometry(0.48 * scale, 0.28 * scale, 0.25 * scale);
  const shorts = new THREE.Mesh(shortsGeo, shortsMat);
  shorts.position.y = 0.82 * scale;
  trajectGkBody.add(shorts);

  // Left & Right Legs
  [-0.14, 0.14].forEach((xOff, lIdx) => {
    const legGroup = new THREE.Group();
    // Thigh
    const thighGeo = new THREE.CylinderGeometry(0.08 * scale, 0.065 * scale, 0.38 * scale, 10);
    const thigh = new THREE.Mesh(thighGeo, skinMat);
    thigh.position.y = -0.19 * scale;
    legGroup.add(thigh);

    // Sock & Shin Guard
    const shinGeo = new THREE.CylinderGeometry(0.065 * scale, 0.055 * scale, 0.40 * scale, 10);
    const shin = new THREE.Mesh(shinGeo, jerseyMat);
    shin.position.y = -0.48 * scale;
    legGroup.add(shin);

    // Boot
    const bootGeo = new THREE.BoxGeometry(0.09 * scale, 0.08 * scale, 0.22 * scale);
    const boot = new THREE.Mesh(bootGeo, bootMat);
    boot.position.set(0, -0.68 * scale, 0.04 * scale);
    legGroup.add(boot);

    legGroup.position.set(xOff * scale, 0.72 * scale, 0);
    trajectGkBody.add(legGroup);
    if (lIdx === 0) trajectGkLeftLeg = legGroup;
    else trajectGkRightLeg = legGroup;
  });

  // Left Arm
  trajectGkLeftArm = new THREE.Group();
  const armGeo = new THREE.CylinderGeometry(0.055 * scale, 0.045 * scale, 0.48 * scale, 8);
  const leftArmMesh = new THREE.Mesh(armGeo, jerseyMat);
  leftArmMesh.position.y = -0.24 * scale;
  trajectGkLeftArm.add(leftArmMesh);

  // Left Glove
  const gloveGeo = new THREE.BoxGeometry(0.12 * scale, 0.15 * scale, 0.06 * scale);
  trajectGkLeftGlove = new THREE.Mesh(gloveGeo, gloveMat);
  trajectGkLeftGlove.position.y = -0.52 * scale;
  trajectGkLeftArm.add(trajectGkLeftGlove);
  trajectGkLeftArm.position.set(-0.30 * scale, 1.40 * scale, 0);
  trajectGkLeftArm.rotation.z = 0.55;
  trajectGkBody.add(trajectGkLeftArm);

  // Right Arm
  trajectGkRightArm = new THREE.Group();
  const rightArmMesh = new THREE.Mesh(armGeo, jerseyMat);
  rightArmMesh.position.y = -0.24 * scale;
  trajectGkRightArm.add(rightArmMesh);

  // Right Glove
  const rightGlove = new THREE.Mesh(gloveGeo, gloveMat);
  trajectGkRightGlove = new THREE.Mesh(gloveGeo, gloveMat);
  trajectGkRightGlove.position.y = -0.52 * scale;
  trajectGkRightArm.add(trajectGkRightGlove);
  trajectGkRightArm.position.set(0.30 * scale, 1.40 * scale, 0);
  trajectGkRightArm.rotation.z = -0.55;
  trajectGkBody.add(trajectGkRightArm);

  rootGroup.add(trajectGkBody);
  rootGroup.position.set(0, 0, 23.6); // Standing on the goal line
  return rootGroup;
}

/* TURF PARTICLES & GRASS SPLATTER SYSTEM */
function spawnTurfParticles(pos, count = 35) {
  if (!THREE || !trajectScene) return;

  const pMat = new THREE.MeshBasicMaterial({ color: 0x5a8a3a });
  const dMat = new THREE.MeshBasicMaterial({ color: 0x3a2818 });

  for (let i = 0; i < count; i++) {
    const isGrass = Math.random() > 0.35;
    const geo = isGrass ? new THREE.BoxGeometry(0.02, 0.08, 0.02) : new THREE.DodecahedronGeometry(0.025);
    const p = new THREE.Mesh(geo, isGrass ? pMat : dMat);
    p.position.copy(pos);
    p.position.y += 0.05;

    const angle = Math.random() * Math.PI * 2;
    const speed = 1.5 + Math.random() * 3.5;
    const vel = new THREE.Vector3(
      Math.cos(angle) * speed * 0.5,
      2.0 + Math.random() * 3.5,
      Math.sin(angle) * speed * 0.5 + 1.2
    );

    trajectScene.add(p);
    trajectParticles.push({ mesh: p, vel, life: 1.0, decay: 0.025 + Math.random() * 0.02 });
  }
}

/* Update particles each frame */
function updateParticles() {
  for (let i = trajectParticles.length - 1; i >= 0; i--) {
    const pt = trajectParticles[i];
    pt.mesh.position.addScaledVector(pt.vel, 0.016);
    pt.vel.y -= 9.81 * 0.016; // gravity
    pt.mesh.rotation.x += 0.1;
    pt.mesh.rotation.z += 0.1;
    pt.life -= pt.decay;

    if (pt.mesh.position.y <= 0.02) {
      pt.mesh.position.y = 0.02;
      pt.vel.set(0, 0, 0);
    }

    if (pt.life <= 0) {
      trajectScene.remove(pt.mesh);
      trajectParticles.splice(i, 1);
    }
  }
}

/* ================================================================
   3D GLB ASSET LOADERS: GOALPOST & MATCH FOOTBALL
   ================================================================ */
async function getGLTFLoader() {
  if (window.THREE && window.THREE.GLTFLoader) {
    return new window.THREE.GLTFLoader();
  }
  if (window.GLTFLoader) {
    return new window.GLTFLoader();
  }
  try {
    const module = await import('https://cdn.jsdelivr.net/npm/three@0.160.0/examples/jsm/loaders/GLTFLoader.js');
    if (module && module.GLTFLoader) {
      return new module.GLTFLoader();
    }
  } catch(e) {}
  return null;
}

function removeGoalModel() {
  if (trajectGoalModel && trajectScene) {
    trajectScene.remove(trajectGoalModel);
    trajectGoalModel.traverse(child => {
      if (child.isMesh) {
        if (child.geometry) child.geometry.dispose();
        if (child.material) {
          if (Array.isArray(child.material)) {
            child.material.forEach(m => {
              if (m.map) m.map.dispose();
              m.dispose();
            });
          } else {
            if (child.material.map) child.material.map.dispose();
            child.material.dispose();
          }
        }
      }
    });
    trajectGoalModel = null;
  }
}

// Base64-embedded 3D Goalpost GLB (690KB FIFA regulation 7.32m x 2.44m)
const GOAL_GLB_BASE64 = '';

function decodeBase64ToArrayBuffer(b64) {
  const binaryString = window.atob(b64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes.buffer;
}

async function loadGoalModel(scene) {
  if (trajectGoalModel || isGoalModelLoading) return;
  isGoalModelLoading = true;

  if (trajectProceduralGoal) {
    trajectProceduralGoal.visible = false;
  }

  const loader = await getGLTFLoader();
  if (!loader) {
    console.warn('[90+ SUPPLY] GLTFLoader unavailable.');
    isGoalModelLoading = false;
    return;
  }

  function setupGoalMesh(gltf, sourceDesc) {
    isGoalModelLoading = false;
    const model = gltf.scene || (gltf.scenes && gltf.scenes[0]);
    if (!model) return false;

    trajectNetMeshes = [];
    model.traverse(child => {
      if (child.isMesh) {
        child.castShadow = true;
        child.receiveShadow = true;
        const nm = (child.name || '').toLowerCase();
        const matNm = (child.material && child.material.name ? child.material.name : '').toLowerCase();

        if (nm.includes('rope') || nm.includes('net') || matNm.includes('rope') || matNm.includes('net')) {
          child.userData.isNetMesh = true;
          trajectNetMeshes.push(child);
          child.material = new THREE.MeshStandardMaterial({
            color: 0xffffff,
            roughness: 0.75,
            metalness: 0.02,
            side: THREE.DoubleSide,
            emissive: 0xffffff,
            emissiveIntensity: 0.06
          });
        } else if (nm.includes('pole') || matNm.includes('pole') || matNm.includes('material.003')) {
          child.material = new THREE.MeshStandardMaterial({
            color: 0x22252a,
            roughness: 0.45,
            metalness: 0.5
          });
        } else {
          child.material = new THREE.MeshStandardMaterial({
            color: 0xf8f8f8,
            roughness: 0.18,
            metalness: 0.25,
            emissive: 0xffffff,
            emissiveIntensity: 0.10
          });
        }
      }
    });

    const bbox = new THREE.Box3().setFromObject(model);
    const size = new THREE.Vector3();
    bbox.getSize(size);

    // Calibrate 3D goalpost model to exact FIFA regulation dimensions: 7.32m wide, 2.44m high
    const rotY = Math.PI;
    const scaleX = 7.32 / 5.0;  // 1.464 -> exact 7.32m post-to-post width
    const scaleY = 2.44 / 2.0;  // 1.220 -> exact 2.44m crossbar height
    const scaleZ = scaleX;      // 1.464 -> proportional net depth
    const posX = 0.0;
    const posY = 0.0;
    const posZ = 24.0 + (0.75 * scaleZ); // 25.098m -> front posts align precisely at goal line Z=24.0m

    model.rotation.y = rotY;
    model.scale.set(scaleX, scaleY, scaleZ);
    model.position.set(posX, posY, posZ);

    removeGoalModel();
    trajectGoalModel = model;
    window.trajectGoalModel = model;
    scene.add(trajectGoalModel);

    if (trajectProceduralGoal) {
      trajectProceduralGoal.visible = false;
    }

    console.log('[90+ SUPPLY] 3D GOALPOST MODEL LOADED & INTEGRATED', {
      source: sourceDesc,
      dimensions: { width: size.x, height: size.y, depth: size.z },
      scale: { x: scaleX, y: scaleY, z: scaleZ },
      position: { x: model.position.x, y: model.position.y, z: model.position.z },
      netMeshes: trajectNetMeshes.length
    });
    return true;
  }

  if (typeof GOAL_GLB_BASE64 !== 'undefined' && GOAL_GLB_BASE64.length > 1000) {
    try {
      const buffer = decodeBase64ToArrayBuffer(GOAL_GLB_BASE64);
      loader.parse(
        buffer,
        '',
        (gltf) => {
          setupGoalMesh(gltf, 'Embedded 3D Goal GLB');
        },
        (err) => {
          console.warn('[90+ SUPPLY] Embedded goal parse warning:', err);
          tryCandidatePaths();
        }
      );
      return;
    } catch (e) {
      console.warn('[90+ SUPPLY] Base64 decoding warning:', e);
    }
  }

  function tryCandidatePaths() {
    const candidatePaths = [
      'assets/models/goal/goal.glb',
      'assets/models/goal/football_goal.glb',
      'public/models/goal.glb',
      'public/models/goalkeeper.glb'
    ];
    function tryLoad(index) {
      if (index >= candidatePaths.length) {
        isGoalModelLoading = false;
        console.warn('[90+ SUPPLY] Goal GLB failed across all candidate paths.');
        return;
      }
      const modelPath = candidatePaths[index];
      loader.load(
        modelPath,
        (gltf) => {
          setupGoalMesh(gltf, modelPath);
        },
        undefined,
        () => {
          tryLoad(index + 1);
        }
      );
    }
    tryLoad(0);
  }

  tryCandidatePaths();
}

function removeFootballModel() {
  if (trajectFootballModel && trajectScene) {
    trajectScene.remove(trajectFootballModel);
    trajectFootballModel.traverse(child => {
      if (child.isMesh) {
        if (child.geometry) child.geometry.dispose();
        if (child.material) {
          if (Array.isArray(child.material)) {
            child.material.forEach(m => {
              if (m.map) m.map.dispose();
              m.dispose();
            });
          } else {
            if (child.material.map) child.material.map.dispose();
            child.material.dispose();
          }
        }
      }
    });
    trajectFootballModel = null;
  }
}

async function loadFootballModel(scene) {
  if (trajectFootballModel || isFootballLoading) return;
  isFootballLoading = true;

  const loader = await getGLTFLoader();
  if (!loader) {
    console.warn('[90+ SUPPLY] Football GLB loader unavailable — using fallback ball.');
    isFootballLoading = false;
    if (trajectBall) trajectBall.visible = true;
    return;
  }

  function applyFootballGLTF(gltf) {
    isFootballLoading = false;
    const model = gltf.scene || (gltf.scenes && gltf.scenes[0]);
    if (!model) return;

    let meshCount = 0;
    let matCount = 0;
    model.traverse(child => {
      if (child.isMesh) {
        meshCount++;
        child.castShadow = true;
        child.receiveShadow = true;
        child.geometry.computeVertexNormals();
        const isWhite = child.name.includes('_1') || child.name.includes('Solid001_1') || child.name.includes('Bianco');
        if (isWhite) {
          child.material = new THREE.MeshPhysicalMaterial({
            color: 0xf4f6fa,
            roughness: 0.28,
            metalness: 0.05,
            clearcoat: 0.5,
            clearcoatRoughness: 0.15
          });
        } else {
          child.material = new THREE.MeshPhysicalMaterial({
            color: 0x141618,
            roughness: 0.35,
            metalness: 0.1,
            clearcoat: 0.5,
            clearcoatRoughness: 0.15
          });
        }
        matCount++;
      }
    });

    // Bounding box & target 22cm regulation ball diameter
    const bbox = new THREE.Box3().setFromObject(model);
    const size = new THREE.Vector3();
    bbox.getSize(size);
    const center = new THREE.Vector3();
    bbox.getCenter(center);

    // Center the model pivot
    model.position.sub(center);
    const wrapper = new THREE.Group();
    wrapper.add(model);

    const maxDim = Math.max(size.x, size.y, size.z);
    const targetDiameter = 0.22; // 22cm regulation match ball diameter
    const calculatedScale = targetDiameter / (maxDim || 1.936);
    wrapper.scale.setScalar(calculatedScale);

    // Synchronize initial position with existing trajectBall
    const startZ = trajectMode === 'penalty' ? 13.0 : 0.0;
    wrapper.position.set(0, 0.11, startZ);

    removeFootballModel();
    trajectFootballModel = wrapper;
    scene.add(trajectFootballModel);

    // Hide simple procedural ball mesh while preserving its physics calculations
    if (trajectBall) {
      trajectBall.visible = false;
    }

    console.log('[90+ SUPPLY] Clooned 3D Football Model loaded into Free-Kick Studio', {
      dimensions: { x: size.x, y: size.y, z: size.z },
      calculatedScale: calculatedScale,
      position: { x: wrapper.position.x, y: wrapper.position.y, z: wrapper.position.z },
      rotation: { x: wrapper.rotation.x, y: wrapper.rotation.y, z: wrapper.rotation.z },
      meshes: meshCount,
      materials: matCount
    });
  }

  if (typeof FOOTBALL_GLB_BASE64 !== 'undefined' && FOOTBALL_GLB_BASE64.length > 1000) {
    try {
      const buffer = decodeBase64ToArrayBuffer(FOOTBALL_GLB_BASE64);
      loader.parse(buffer, '', (gltf) => {
        applyFootballGLTF(gltf);
      }, (err) => {
        tryCandidateFootballPaths();
      });
      return;
    } catch (e) {
      console.warn('[90+ SUPPLY] Base64 football parse failed, trying candidate paths...', e);
    }
  }

  function tryCandidateFootballPaths() {
    const candidatePaths = [
      'assets/models/football/football.glb',
      'assets/models/football/clooned_ball.glb',
      'public/models/football.glb'
    ];
    let idx = 0;
    function tryNext() {
      if (idx >= candidatePaths.length) {
        isFootballLoading = false;
        console.warn('[90+ SUPPLY] All football candidate paths failed — using fallback ball.');
        if (trajectBall) trajectBall.visible = true;
        return;
      }
      const p = candidatePaths[idx++];
      loader.load(p, (gltf) => applyFootballGLTF(gltf), undefined, () => tryNext());
    }
    tryNext();
  }

  tryCandidateFootballPaths();
}

/* 3D SCENE INITIALIZATION & RENDERING */
function initTrajectory3DScene() {
  const canvas = document.getElementById('trajectCanvas');
  if (!canvas || !THREE) return;

  const rect = canvas.parentElement.getBoundingClientRect();
  const width = rect.width || 700;
  const height = 480;

  trajectScene = new THREE.Scene();
  trajectScene.background = new THREE.Color(0x060709);
  trajectScene.fog = new THREE.FogExp2(0x060709, 0.018);

  trajectCamera = new THREE.PerspectiveCamera(48, width / height, 0.1, 140);
  trajectCamera.position.set(-1.6, 3.2, -5.0);
  trajectCamera.lookAt(0, 1.6, 20);

  trajectRenderer = new THREE.WebGLRenderer({ canvas, antialias: true, alpha: false });
  trajectRenderer.setSize(width, height);
  trajectRenderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
  trajectRenderer.shadowMap.enabled = true;
  trajectRenderer.shadowMap.type = THREE.PCFSoftShadowMap;
  trajectRenderer.toneMapping = THREE.ACESFilmicToneMapping;
  trajectRenderer.toneMappingExposure = 1.15;

  /* ================================================================
     MATCHDAY STADIUM LIGHTING, REALISTIC MOWED TURF & PENALTY BOX
     ================================================================ */
  const ambLight = new THREE.AmbientLight(0x708599, 0.65);
  trajectScene.add(ambLight);

  // Main Stadium Lighting Beams
  const floodMain = new THREE.DirectionalLight(0xffffff, 2.4);
  floodMain.position.set(12, 28, 14);
  floodMain.castShadow = true;
  floodMain.shadow.mapSize.width = 1024;
  floodMain.shadow.mapSize.height = 1024;
  floodMain.shadow.camera.near = 1;
  floodMain.shadow.camera.far = 70;
  floodMain.shadow.camera.left = -22;
  floodMain.shadow.camera.right = 22;
  floodMain.shadow.camera.top = 16;
  floodMain.shadow.camera.bottom = -6;
  trajectScene.add(floodMain);

  const floodAccent = new THREE.DirectionalLight(0xc8ff2e, 0.35);
  floodAccent.position.set(-14, 20, 24);
  trajectScene.add(floodAccent);

  const floodRim = new THREE.DirectionalLight(0x5588ff, 0.35);
  floodRim.position.set(0, 10, -8);
  trajectScene.add(floodRim);

  /* 1. HIGH-RESOLUTION MOWED STRIPED GRASS TURF */
  function buildGrassTexture() {
    const canvas = document.createElement('canvas');
    canvas.width = 1024;
    canvas.height = 2048;
    const ctx = canvas.getContext('2d');

    const numStripes = 22;
    const stripeH = canvas.height / numStripes;

    for (let i = 0; i < numStripes; i++) {
      const isLight = i % 2 === 0;
      ctx.fillStyle = isLight ? '#1c5523' : '#143f1b';
      ctx.fillRect(0, i * stripeH, canvas.width, stripeH);

      const grad = ctx.createLinearGradient(0, i * stripeH, 0, (i + 1) * stripeH);
      grad.addColorStop(0, 'rgba(255, 255, 255, 0.05)');
      grad.addColorStop(0.5, 'rgba(0, 0, 0, 0.04)');
      grad.addColorStop(1, 'rgba(255, 255, 255, 0.02)');
      ctx.fillStyle = grad;
      ctx.fillRect(0, i * stripeH, canvas.width, stripeH);
    }

    const imgData = ctx.getImageData(0, 0, canvas.width, canvas.height);
    const d = imgData.data;
    for (let p = 0; p < d.length; p += 4) {
      const n = (Math.random() - 0.5) * 18;
      d[p] = Math.min(255, Math.max(0, d[p] + n * 0.4));
      d[p + 1] = Math.min(255, Math.max(0, d[p + 1] + n));
      d[p + 2] = Math.min(255, Math.max(0, d[p + 2] + n * 0.3));
    }
    ctx.putImageData(imgData, 0, 0);

    const tex = new THREE.CanvasTexture(canvas);
    tex.wrapS = THREE.ClampToEdgeWrapping;
    tex.wrapT = THREE.ClampToEdgeWrapping;
    return tex;
  }

  const grassTexture = buildGrassTexture();
  const pitchGeo = new THREE.PlaneGeometry(46, 64);
  const pitchMat = new THREE.MeshStandardMaterial({
    map: grassTexture,
    roughness: 0.85,
    metalness: 0.04
  });
  const pitchMesh = new THREE.Mesh(pitchGeo, pitchMat);
  pitchMesh.rotation.x = -Math.PI / 2;
  pitchMesh.position.set(0, 0, 12);
  pitchMesh.receiveShadow = true;
  trajectScene.add(pitchMesh);

  /* 2. OFFICIAL UEFA REGULATION PENALTY BOX & PITCH MARKINGS */
  const lineMat = new THREE.MeshBasicMaterial({ color: 0xf5f8f5 });
  const addLine = (w, d, x, z) => {
    const g = new THREE.PlaneGeometry(w, d);
    const m = new THREE.Mesh(g, lineMat);
    m.rotation.x = -Math.PI / 2;
    m.position.set(x, 0.012, z);
    trajectScene.add(m);
    return m;
  };

  // Goal Line (Z = 24.0m)
  addLine(40.32, 0.12, 0, 24.0);

  // 18-Yard Penalty Box (Extends 16.5m out to Z = 7.5m, Width = 40.32m)
  addLine(40.32, 0.12, 0, 7.5);          // Front Line
  addLine(0.12, 16.5, -20.16, 15.75);    // Left Boundary Line
  addLine(0.12, 16.5, 20.16, 15.75);     // Right Boundary Line

  // 6-Yard Goal Box (Extends 5.5m out to Z = 18.5m, Width = 18.32m)
  addLine(18.32, 0.12, 0, 18.5);         // Front Line
  addLine(0.12, 5.5, -9.16, 21.25);      // Left Line
  addLine(0.12, 5.5, 9.16, 21.25);       // Right Line

  // Penalty Spot (11m from goal line, Z = 13.0m)
  const penSpotGeo = new THREE.CircleGeometry(0.13, 18);
  const penSpot = new THREE.Mesh(penSpotGeo, lineMat);
  penSpot.rotation.x = -Math.PI / 2;
  penSpot.position.set(0, 0.014, 13.0);
  trajectScene.add(penSpot);

  // Penalty Arc ("D-Box" Arc, Radius = 9.15m from Penalty Spot outside 18-yard box toward free-kick spot)
  const dArcGeo = new THREE.RingGeometry(9.09, 9.21, 40, 1, Math.PI * 0.5 - 0.926, 1.852);
  const dArc = new THREE.Mesh(dArcGeo, lineMat);
  dArc.rotation.x = -Math.PI / 2;
  dArc.position.set(0, 0.014, 13.0);
  trajectScene.add(dArc);

  // Free-Kick Spot (24m from goal line, Z = 0m)
  const fkSpotGeo = new THREE.CircleGeometry(0.14, 18);
  const fkSpotMat = new THREE.MeshBasicMaterial({ color: 0xc8ff2e });
  const fkSpot = new THREE.Mesh(fkSpotGeo, fkSpotMat);
  fkSpot.rotation.x = -Math.PI / 2;
  fkSpot.position.set(0, 0.014, 0);
  trajectScene.add(fkSpot);

  // Free-Kick Spot Outer Tactical Glow Ring
  const fkRingGeo = new THREE.RingGeometry(0.20, 0.23, 24);
  const fkRing = new THREE.Mesh(fkRingGeo, fkSpotMat);
  fkRing.rotation.x = -Math.PI / 2;
  fkRing.position.set(0, 0.014, 0);
  trajectScene.add(fkRing);

  // Pitch Touchlines & Halfway Line
  addLine(40.32, 0.12, 0, -8.0);         // Halfway Line
  addLine(0.12, 32.0, -20.16, 8.0);      // Left Pitch Touchline
  addLine(0.12, 32.0, 20.16, 8.0);       // Right Pitch Touchline

  // Center Circle Arc at Halfway Line (arcing onto match half toward goal)
  const centerArcGeo = new THREE.RingGeometry(9.09, 9.21, 40, 1, Math.PI, Math.PI);
  const centerArc = new THREE.Mesh(centerArcGeo, lineMat);
  centerArc.rotation.x = -Math.PI / 2;
  centerArc.position.set(0, 0.014, -8.0);
  trajectScene.add(centerArc);

  // Corner Flags & Corner Arcs (Z = 24.0m, X = +/-20.16m)
  [-20.16, 20.16].forEach((cx, idx) => {
    // Corner Quarter Arc (facing into pitch)
    const cArcGeo = new THREE.RingGeometry(0.94, 1.06, 16, 1, idx === 0 ? 0 : Math.PI * 0.5, Math.PI * 0.5);
    const cArc = new THREE.Mesh(cArcGeo, lineMat);
    cArc.rotation.x = -Math.PI / 2;
    cArc.position.set(cx, 0.014, 24.0);
    trajectScene.add(cArc);

    // Corner Flagpole
    const poleGeo = new THREE.CylinderGeometry(0.02, 0.02, 1.5, 8);
    const poleMat = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.3 });
    const pole = new THREE.Mesh(poleGeo, poleMat);
    pole.position.set(cx, 0.75, 24.0);
    trajectScene.add(pole);

    // Corner Flag Fabric (Yellow/Red)
    const flagGeo = new THREE.PlaneGeometry(0.35, 0.25);
    const flagMat = new THREE.MeshBasicMaterial({ color: 0xffcc00, side: THREE.DoubleSide });
    const flag = new THREE.Mesh(flagGeo, flagMat);
    flag.position.set(cx + (idx === 0 ? 0.18 : -0.18), 1.35, 24.0);
    trajectScene.add(flag);
  });

  /* 3. REAL 3D STADIUM FLOODLIGHT TOWERS ("LIGHTS OF THE FIELD") */
  const towerMat = new THREE.MeshStandardMaterial({ color: 0x22262c, metalness: 0.8, roughness: 0.3 });
  const bulbMat = new THREE.MeshStandardMaterial({
    color: 0xffffff,
    emissive: 0xffffff,
    emissiveIntensity: 2.8,
    roughness: 0.1
  });
  const beamMat = new THREE.MeshBasicMaterial({
    color: 0xf0f6ff,
    transparent: true,
    opacity: 0.04,
    side: THREE.DoubleSide,
    depthWrite: false
  });

  const towerPositions = [
    { x: -22.5, z: -4.5, rotY: Math.PI * 0.25 },  // Front Left
    { x: 22.5,  z: -4.5, rotY: -Math.PI * 0.25 }, // Front Right
    { x: -22.5, z: 27.0, rotY: Math.PI * 0.75 },  // Goal Left
    { x: 22.5,  z: 27.0, rotY: -Math.PI * 0.75 }  // Goal Right
  ];

  towerPositions.forEach((tp, tIdx) => {
    const towerGroup = new THREE.Group();
    towerGroup.position.set(tp.x, 0, tp.z);
    towerGroup.rotation.y = tp.rotY;

    // Main Column Pylon
    const mastGeo = new THREE.CylinderGeometry(0.22, 0.42, 16.0, 10);
    const mast = new THREE.Mesh(mastGeo, towerMat);
    mast.position.y = 8.0;
    mast.castShadow = true;
    towerGroup.add(mast);

    // Crossbar Trusses
    [4.0, 8.0, 12.0].forEach(yPos => {
      const crossGeo = new THREE.BoxGeometry(1.6, 0.08, 0.08);
      const cross = new THREE.Mesh(crossGeo, towerMat);
      cross.position.y = yPos;
      towerGroup.add(cross);
    });

    // Angled Floodlight Head Frame
    const headGroup = new THREE.Group();
    headGroup.position.set(0, 16.0, 0.4);
    headGroup.rotation.x = 0.55; // Angled down toward pitch

    const headFrameGeo = new THREE.BoxGeometry(2.4, 1.4, 0.25);
    const headFrame = new THREE.Mesh(headFrameGeo, towerMat);
    headGroup.add(headFrame);

    // 4x3 Grid of High-Intensity LED Floodlight Lenses
    for (let row = -1; row <= 1; row++) {
      for (let col = -1.5; col <= 1.5; col += 1.0) {
        const lensGeo = new THREE.BoxGeometry(0.42, 0.32, 0.1);
        const lens = new THREE.Mesh(lensGeo, bulbMat);
        lens.position.set(col * 0.52, row * 0.40, 0.14);
        headGroup.add(lens);
      }
    }

    // Dynamic Spotlight shining directly on pitch
    const spot = new THREE.SpotLight(0xf2f7ff, 2.8, 48, Math.PI / 4, 0.45, 1.2);
    spot.position.set(0, 0, 0.2);
    spot.target.position.set(0, -16, 12);
    headGroup.add(spot);
    headGroup.add(spot.target);

    // Soft Volumetric Light Beam Cone
    const coneGeo = new THREE.ConeGeometry(7.0, 18.0, 16, 1, true);
    const coneMesh = new THREE.Mesh(coneGeo, beamMat);
    coneMesh.position.set(0, -9.0, 6.0);
    coneMesh.rotation.x = Math.PI * 0.12;
    headGroup.add(coneMesh);

    towerGroup.add(headGroup);
    trajectScene.add(towerGroup);
  });

  /* 4. STADIUM GRANDSTAND & ROOF CANOPY BEHIND GOAL */
  const standGroup = new THREE.Group();
  standGroup.position.set(0, 0, 29.5);

  const standTierMat = new THREE.MeshStandardMaterial({ color: 0x181c20, roughness: 0.7 });
  const seatRedMat = new THREE.MeshStandardMaterial({ color: 0xd32f2f, roughness: 0.5 });
  const roofMat = new THREE.MeshStandardMaterial({ color: 0x242830, metalness: 0.4, roughness: 0.4 });

  // 8 Tiered Concrete Bleachers with Red Stadium Seats
  for (let s = 0; s < 8; s++) {
    const tierGeo = new THREE.BoxGeometry(34.0, 0.55, 0.9);
    const tier = new THREE.Mesh(tierGeo, standTierMat);
    tier.position.set(0, (s + 0.5) * 0.55, s * 0.9);
    standGroup.add(tier);

    const seatGeo = new THREE.BoxGeometry(32.0, 0.25, 0.45);
    const seat = new THREE.Mesh(seatGeo, seatRedMat);
    seat.position.set(0, (s + 1) * 0.55 + 0.12, s * 0.9);
    standGroup.add(seat);
  }

  // Grandstand Roof Canopy
  const roofGeo = new THREE.BoxGeometry(36.0, 0.4, 10.0);
  const roof = new THREE.Mesh(roofGeo, roofMat);
  roof.position.set(0, 8.5, 3.0);
  roof.rotation.x = -0.12;
  standGroup.add(roof);

  // Roof Support Columns
  [-16.0, 16.0].forEach(rx => {
    const colGeo = new THREE.CylinderGeometry(0.18, 0.22, 9.0, 10);
    const col = new THREE.Mesh(colGeo, towerMat);
    col.position.set(rx, 4.5, 6.5);
    standGroup.add(col);
  });

  // Ball Containment Safety Netting behind Goal (Z = 26.2m)
  const safetyNetGeo = new THREE.PlaneGeometry(28.0, 8.0);
  const safetyNetMat = new THREE.MeshStandardMaterial({
    color: 0x8899aa,
    transparent: true,
    opacity: 0.18,
    wireframe: true
  });
  const safetyNet = new THREE.Mesh(safetyNetGeo, safetyNetMat);
  safetyNet.position.set(0, 4.0, 26.2);
  trajectScene.add(safetyNet);

  trajectScene.add(standGroup);

  /* Official Goal Frame (7.32m wide, 2.44m high at Z=24.0m) */
  const goalPostMat = new THREE.MeshStandardMaterial({
    color: 0xf5f5f5,
    metalness: 0.85,
    roughness: 0.15,
    emissive: 0xffffff,
    emissiveIntensity: 0.08
  });
  const goalGroup = new THREE.Group();

  const postGeo = new THREE.CylinderGeometry(0.06, 0.06, 2.44, 16);
  const leftPost = new THREE.Mesh(postGeo, goalPostMat);
  leftPost.position.set(-3.66, 1.22, 24);
  leftPost.castShadow = true;
  goalGroup.add(leftPost);

  const rightPost = new THREE.Mesh(postGeo, goalPostMat);
  rightPost.position.set(3.66, 1.22, 24);
  rightPost.castShadow = true;
  goalGroup.add(rightPost);

  const barGeo = new THREE.CylinderGeometry(0.06, 0.06, 7.32, 16);
  const crossbar = new THREE.Mesh(barGeo, goalPostMat);
  crossbar.rotation.z = Math.PI / 2;
  crossbar.position.set(0, 2.44, 24);
  crossbar.castShadow = true;
  goalGroup.add(crossbar);

  // Hexagonal Netting Box (Clean white fallback, hidden by default)
  const netGeo = new THREE.BoxGeometry(7.32, 2.44, 1.8);
  const netMat = new THREE.MeshStandardMaterial({
    color: 0xffffff,
    roughness: 0.9,
    transparent: true,
    opacity: 0.15,
    wireframe: false
  });
  trajectNetMesh = new THREE.Mesh(netGeo, netMat);
  trajectNetMesh.position.set(0, 1.22, 24.9);
  goalGroup.add(trajectNetMesh);
  if (!trajectNetMeshes.includes(trajectNetMesh)) trajectNetMeshes.push(trajectNetMesh);

  trajectProceduralGoal = goalGroup;
  goalGroup.visible = false; // Hidden by default; replaced by real 3D GLB model
  trajectScene.add(goalGroup);
  loadGoalModel(trajectScene);

  /* Defensive Wall Mannequins (Z=9.15m from kick spot) */
  trajectWallGroup = new THREE.Group();
  const wallManMat = new THREE.MeshStandardMaterial({ color: 0x181c20, roughness: 0.55 });
  const wallHeadMat = new THREE.MeshStandardMaterial({ color: 0xd4a574, roughness: 0.7 });

  for (let i = -1.5; i <= 1.5; i += 1.0) {
    const xPos = i * 0.52 + 0.3; // Centered to guard the right side of goal
    // Mannequin Torso
    const manGeo = new THREE.CylinderGeometry(0.18, 0.23, 1.8, 12);
    const man = new THREE.Mesh(manGeo, wallManMat);
    man.position.set(xPos, 0.9, 9.15);
    man.castShadow = true;
    trajectWallGroup.add(man);

    // Head
    const headGeo = new THREE.SphereGeometry(0.115, 14, 14);
    const head = new THREE.Mesh(headGeo, wallHeadMat);
    head.position.set(xPos, 1.92, 9.15);
    trajectWallGroup.add(head);

    // Shielding Arms
    const armGeo = new THREE.CylinderGeometry(0.04, 0.04, 0.38, 8);
    const arm = new THREE.Mesh(armGeo, wallManMat);
    arm.rotation.x = -0.85;
    arm.position.set(xPos, 1.70, 8.96);
    trajectWallGroup.add(arm);
  }
  trajectScene.add(trajectWallGroup);

  /* Match Ball (Apex Volt Pro) — Glowing Optic Volt with Pentagons */
  const ballMat = new THREE.MeshPhysicalMaterial({
    color: 0xc8ff2e,
    roughness: 0.22,
    metalness: 0.15,
    emissive: 0xc8ff2e,
    emissiveIntensity: 0.35,
    clearcoat: 0.8,
    clearcoatRoughness: 0.1
  });
  const ballGeo = new THREE.SphereGeometry(0.11, 32, 32);
  trajectBall = new THREE.Mesh(ballGeo, ballMat);
  trajectBall.position.set(0, 0.11, 0); // starts at Free-Kick spot
  trajectBall.castShadow = true;
  trajectScene.add(trajectBall);
  window.trajectBall = trajectBall;
  window.NetPhysics = NetPhysics;
  window.GoalkeeperPhysics = GoalkeeperPhysics;
  window.executeFreeKickAnimation = executeFreeKickAnimation;
  loadFootballModel(trajectScene);

  /* Render Mode Presets & Calculations */
  renderPresetButtons();
  updateTrajectoryCalculations();

  /* Listeners: Mode Switcher */
  $('#btnModeFreekick')?.addEventListener('click', () => setTrajectMode('freekick'));
  $('#btnModePenalty')?.addEventListener('click', () => setTrajectMode('penalty'));

  /* Initialize Active 3D Striker Character */
  spawnKicker(currentKickerKey);

  /* Listeners: Camera Switcher */
  $('#btnCamAction')?.addEventListener('click', () => setCameraMode('action'));
  $('#btnCamBroadcast')?.addEventListener('click', () => setCameraMode('broadcast'));
  $('#btnCamBehind')?.addEventListener('click', () => setCameraMode('behind'));

  /* Listeners: Shootout Reset */
  $('#btnResetShootout')?.addEventListener('click', resetShootout);

  /* Sliders Listeners */
  ['rngSpeed', 'rngSpin', 'rngElev', 'rngAzimuth'].forEach(id => {
    document.getElementById(id)?.addEventListener('input', () => {
      resetTrajectoryBadge();
      updateTrajectoryCalculations();
      playSound('pop');
    });
  });

  /* Goalkeeper Card Selection */
  $$('.gk-card').forEach(card => {
    card.addEventListener('click', () => {
      $$('.gk-card').forEach(c => c.classList.remove('active'));
      card.classList.add('active');
      const gkKey = card.dataset.gk;
      selectedGk = GK_PROFILES[gkKey] || GK_PROFILES.none;

      // Rebuild 3D GK Mesh
      if (trajectGkGroup) trajectScene.remove(trajectGkGroup);
      if (gkKey !== 'none') {
        trajectGkGroup = buildGkMesh(selectedGk);
        if (trajectGkGroup) trajectScene.add(trajectGkGroup);
      } else {
        trajectGkGroup = null;
      }

      updateTrajectoryCalculations();
      playSound('click');
    });
  });

  /* Execute Strike Button */
  $('#btnExecuteStrike')?.addEventListener('click', executeFreeKickAnimation);

  /* 3D Render Loop with Breathing Camera & GK Idle Motion */
  let loopTime = 0;
  function renderLoop() {
    if (DOM.page && STATE.route === 'trajectory') {
      requestAnimationFrame(renderLoop);
      loopTime += 0.016;

      // Update turf particles & net elastic physics
      updateParticles();
      if (typeof NetPhysics !== 'undefined' && NetPhysics && NetPhysics.active) {
        NetPhysics.update(0.016);
      }

      // Striker Idle Animation (when aiming)
      if (!isStriking && trajectKickerData) {
        updateKickerIdle(loopTime);
      }

      // Camera Idle Animation (when not striking)
      if (!isStriking) {
        if (currentCameraMode === 'action') {
          const isCarlos = currentKickerKey === 'carlos';
          const isPen = trajectMode === 'penalty';
          const baseZ = isPen ? 7.8 : (isCarlos ? -7.8 : -4.8);
          const baseY = isPen ? 2.2 : (isCarlos ? 3.0 : 2.8);
          const baseX = isCarlos ? -2.2 : (trajectKickerData && trajectKickerData.profile.foot === 'left' ? -2.0 : -1.6);
          trajectCamera.position.x = baseX + Math.sin(loopTime * 0.4) * 0.12;
          trajectCamera.position.y = baseY + Math.sin(loopTime * 0.6) * 0.05;
          trajectCamera.position.z = baseZ;
          trajectCamera.lookAt(0, 1.4, 22);
        } else if (currentCameraMode === 'behind') {
          const isCarlos = currentKickerKey === 'carlos';
          const isCr7 = currentKickerKey === 'cr7';
          const isPen = trajectMode === 'penalty';
          const baseZ = isPen ? 8.5 : (isCarlos ? -8.2 : (isCr7 ? -5.8 : -5.4));
          const camX = isCr7 ? -0.85 : 0;
          const camY = isCr7 ? 2.05 : 2.2;
          trajectCamera.position.set(camX, camY, baseZ);
          trajectCamera.lookAt(isCr7 ? -0.15 : 0, 1.35, isCr7 ? 18 : 24);
        } else if (currentCameraMode === 'broadcast') {
          trajectCamera.position.set(16, 8, 12);
          trajectCamera.lookAt(0, 1.5, 20);
        }

        // Goalkeeper Idle Weight Bouncing & Head Tracking
        if (trajectGkGroup && trajectGkBody) {
          const bounce = Math.sin(loopTime * 3.5) * 0.03;
          trajectGkBody.position.y = Math.max(0, bounce);
          trajectGkBody.position.x = Math.sin(loopTime * 1.5) * 0.12;

          // Ready-stance arm bob
          if (trajectGkLeftArm && trajectGkRightArm) {
            trajectGkLeftArm.rotation.z = 0.55 + Math.sin(loopTime * 3.5) * 0.08;
            trajectGkRightArm.rotation.z = -0.55 - Math.sin(loopTime * 3.5) * 0.08;
          }
        }
      }

      if (trajectFootballModel && trajectBall) {
        trajectFootballModel.position.copy(trajectBall.position);
        trajectFootballModel.rotation.copy(trajectBall.rotation);
      }
      trajectRenderer.render(trajectScene, trajectCamera);
    }
  }
  requestAnimationFrame(renderLoop);
}

/* MODE SWITCHER (25M FREE-KICK vs 11M PENALTY) */
function setTrajectMode(mode) {
  trajectMode = mode;
  resetKickerToStance();
  resetTrajectoryBadge();
  $('#btnModeFreekick')?.classList.toggle('active', mode === 'freekick');
  $('#btnModePenalty')?.classList.toggle('active', mode === 'penalty');

  const isPen = mode === 'penalty';
  $('#trajectModeBadge').textContent = isPen ? '11M PENALTY SHOOTOUT' : '25M FREE-KICK';
  $('#btnStrikeText').textContent = isPen ? 'EXECUTE 11M PENALTY' : 'EXECUTE 25M FREE-KICK';
  $('#panelTitle').textContent = isPen ? 'PENALTY STRIKE CALIBRATION' : 'FREE-KICK CALIBRATION';
  $('#panelDesc').textContent = isPen ? 'Aim for corners or chip past the diving goalkeeper from 11 meters.' : 'Bend over the defensive wall with Magnus force aerodynamics.';
  $('#presetsGroupLabel').textContent = isPen ? 'PENALTY SHOOTOUT PRESETS' : 'LEGENDARY FREE-KICK PRESETS';

  // Toggle Shootout Tracker Box
  const scoreBox = document.getElementById('penaltyScoreStrip');
  if (scoreBox) scoreBox.style.display = isPen ? 'flex' : 'none';

  // Toggle Wall visibility
  if (trajectWallGroup) {
    trajectWallGroup.visible = !isPen;
  }

  // Set Ball position
  const startZ = isPen ? 13.0 : 0.0;
  if (trajectBall) {
    trajectBall.position.set(0, 0.11, startZ);
  }
  if (trajectFootballModel) {
    trajectFootballModel.position.set(0, 0.11, startZ);
    trajectFootballModel.rotation.set(0, 0, 0);
  }

  renderPresetButtons();
  // Auto-apply first preset of new mode
  const defaultPreset = isPen ? PENALTY_PRESETS[0] : FREEKICK_PRESETS[0];
  applyPreset(defaultPreset);
  playSound('click');
}

/* CAMERA ANGLE CONTROLLER */
function setCameraMode(mode) {
  currentCameraMode = mode;
  $('#btnCamAction')?.classList.toggle('active', mode === 'action');
  $('#btnCamBroadcast')?.classList.toggle('active', mode === 'broadcast');
  $('#btnCamBehind')?.classList.toggle('active', mode === 'behind');

  if (mode === 'broadcast') {
    trajectCamera.position.set(16, 8, 12);
    trajectCamera.lookAt(0, 1.5, 20);
  } else if (mode === 'behind') {
    const baseZ = trajectMode === 'penalty' ? 8.5 : -5.6;
    trajectCamera.position.set(-0.85, 2.05, baseZ);
    trajectCamera.lookAt(-0.15, 1.35, 18);
  }
  playSound('pop');
}

/* RENDER PRESET BUTTONS (FREE-KICK vs PENALTY) */
function renderPresetButtons() {
  const container = document.getElementById('presetButtonsRow');
  if (!container) return;

  const list = trajectMode === 'penalty' ? PENALTY_PRESETS : FREEKICK_PRESETS;
  container.innerHTML = list.map((p, idx) => `
    <button class="btn btn-sm btn-ghost preset-btn ${idx === 0 ? 'active' : ''}"
      data-kicker="${p.kickerId || 'messi'}"
      data-speed="${p.speed}" data-spin="${p.spin}" data-elev="${p.elev}" data-azimuth="${p.azimuth}" title="${p.desc}">
      ${p.name}
    </button>
  `).join('');

  // Wire preset buttons
  $$('.preset-btn').forEach(btn => {
    btn.addEventListener('click', () => {
      $$('.preset-btn').forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
      $('#rngSpeed').value = btn.dataset.speed;
      $('#rngSpin').value = btn.dataset.spin;
      $('#rngElev').value = btn.dataset.elev;
      $('#rngAzimuth').value = btn.dataset.azimuth;
      if (btn.dataset.kicker) {
        spawnKicker(btn.dataset.kicker);
      }
      resetTrajectoryBadge();
      updateTrajectoryCalculations();
      playSound('click');
    });
  });
}

function applyPreset(preset) {
  if (!preset) return;
  if ($('#rngSpeed')) $('#rngSpeed').value = preset.speed;
  if ($('#rngSpin')) $('#rngSpin').value = preset.spin;
  if ($('#rngElev')) $('#rngElev').value = preset.elev;
  if ($('#rngAzimuth')) $('#rngAzimuth').value = preset.azimuth;
  if (preset.kickerId) spawnKicker(preset.kickerId);
  resetTrajectoryBadge();
  updateTrajectoryCalculations();
}

/* ================================================================
   REAL 3D NET PHYSICS SIMULATION (SPRING-DAMPER & DEFORMATION BULGE)
   ================================================================ */
const NetPhysics = {
  active: false,
  impactPos: new THREE.Vector3(0, 1.2, 25.0),
  impactVel: new THREE.Vector3(0, 0, 20),
  time: 0,
  duration: 1.8,
  maxBulge: 0.50,
  damping: 3.6,
  frequency: 12.0,
  origVertMap: new WeakMap(),

  trigger(contactPos, incomingVel) {
    this.active = true;
    this.time = 0;
    this.impactPos.copy(contactPos);
    if (incomingVel) this.impactVel.copy(incomingVel);
    const speed = incomingVel ? incomingVel.length() : 22;
    this.maxBulge = Math.min(0.62, Math.max(0.22, speed * 0.024));
    this.frequency = 11.0 + Math.random() * 3.0;
    try { playNetSwish(); } catch(e) {}
    try { spawnTurfParticles(contactPos, 14); } catch(e) {}
  },

  update(dt) {
    if (!this.active) return;
    this.time += dt;
    if (this.time > this.duration) {
      this.active = false;
      this.reset();
      return;
    }

    const envelope = Math.exp(-this.damping * this.time);
    const wave = Math.sin(this.frequency * this.time);
    const bulge = this.maxBulge * envelope * wave;

    trajectNetMeshes.forEach(mesh => {
      if (!mesh || !mesh.geometry || !mesh.geometry.attributes.position) return;
      const posAttr = mesh.geometry.attributes.position;
      if (!this.origVertMap.has(mesh)) {
        this.origVertMap.set(mesh, new Float32Array(posAttr.array));
      }
      const orig = this.origVertMap.get(mesh);
      const arr = posAttr.array;
      const count = posAttr.count;

      const localImpact = mesh.worldToLocal(this.impactPos.clone());
      const radiusSq = 2.4 * 2.4;

      for (let i = 0; i < count; i++) {
        const i3 = i * 3;
        const ox = orig[i3];
        const oy = orig[i3 + 1];
        const oz = orig[i3 + 2];

        const dx = ox - localImpact.x;
        const dy = oy - localImpact.y;
        const d2 = dx * dx + dy * dy;

        if (d2 < radiusSq) {
          const dist = Math.sqrt(d2);
          const spatialFalloff = Math.exp(-d2 / 2.2);
          const phaseLag = Math.sin(this.frequency * this.time - dist * 3.2);
          const disp = this.maxBulge * envelope * phaseLag * spatialFalloff;

          arr[i3 + 2] = oz + disp;
          arr[i3] = ox + (dx > 0 ? -1 : 1) * Math.abs(disp) * 0.06;
        } else {
          arr[i3] = ox;
          arr[i3 + 1] = oy;
          arr[i3 + 2] = oz;
        }
      }
      posAttr.needsUpdate = true;
    });
  },

  reset() {
    trajectNetMeshes.forEach(mesh => {
      if (mesh && mesh.geometry && this.origVertMap.has(mesh)) {
        const orig = this.origVertMap.get(mesh);
        mesh.geometry.attributes.position.array.set(orig);
        mesh.geometry.attributes.position.needsUpdate = true;
      }
    });
  }
};

/* ================================================================
   REAL 3D GOALKEEPER BIOMECHANICS & PARABOLIC DIVE PHYSICS
   ================================================================ */
const GoalkeeperPhysics = {
  isDiving: false,
  time: 0,
  reactionDelay: 0.16,
  targetPos: new THREE.Vector3(0, 1.2, 23.6),
  willSave: false,
  isDeflected: false,
  hasLanded: false,
  diveDirection: 1,
  profile: null,

  reset() {
    this.isDiving = false;
    this.time = 0;
    this.isDeflected = false;
    this.hasLanded = false;
    if (trajectGkGroup) {
      trajectGkGroup.position.set(0, 0, 23.6);
      trajectGkGroup.rotation.set(0, 0, 0);
    }
    if (trajectGkBody) {
      trajectGkBody.rotation.set(0, 0, 0);
      trajectGkBody.position.set(0, 0, 0);
    }
    if (trajectGkLeftArm) {
      trajectGkLeftArm.rotation.set(0, 0, 0.55);
      trajectGkLeftArm.position.set(-0.30, 1.40, 0);
    }
    if (trajectGkRightArm) {
      trajectGkRightArm.rotation.set(0, 0, -0.55);
      trajectGkRightArm.position.set(0.30, 1.40, 0);
    }
    if (trajectGkLeftLeg) trajectGkLeftLeg.rotation.set(0, 0, 0);
    if (trajectGkRightLeg) trajectGkRightLeg.rotation.set(0, 0, 0);
  },

  startDive(targetBallPt, willSave, profile) {
    this.profile = profile || selectedGk;
    if (!trajectGkGroup || !trajectGkBody || this.profile?.name === 'Open Goal') return;
    this.isDiving = true;
    this.time = 0;
    this.willSave = willSave;
    this.isDeflected = false;
    this.hasLanded = false;

    const tx = targetBallPt.x;
    const ty = Math.max(0.25, Math.min(2.35, targetBallPt.y));
    this.diveDirection = Math.sign(tx || 1);

    const reachLimit = ((this.profile.reach || 85) / 100) * 3.4;
    const destX = willSave ? tx : (this.diveDirection * Math.min(reachLimit, Math.abs(tx) * 0.72));
    const destY = willSave ? ty : Math.min(1.75, ty * 0.75);
    this.targetPos.set(destX, destY, 23.6);
  },

  update(dt, ballPos, ballVel, ballSpin) {
    if (!this.isDiving || !trajectGkGroup || !trajectGkBody) return;
    this.time += dt;

    if (this.time < this.reactionDelay) {
      const readyProgress = this.time / this.reactionDelay;
      trajectGkBody.position.y = -0.05 * Math.sin(readyProgress * Math.PI);
      if (trajectGkLeftArm && trajectGkRightArm) {
        trajectGkLeftArm.rotation.z = 0.55 + 0.12 * Math.sin(readyProgress * Math.PI);
        trajectGkRightArm.rotation.z = -0.55 - 0.12 * Math.sin(readyProgress * Math.PI);
      }
      return;
    }

    const diveT = this.time - this.reactionDelay;
    const progress = Math.min(1.0, diveT / 0.58);
    const ease = 1 - Math.pow(1 - progress, 3);

    const currentX = this.targetPos.x * ease;
    const arcHeight = Math.sin(progress * Math.PI * 0.88) * Math.max(0.35, this.targetPos.y);
    trajectGkGroup.position.x = currentX;
    trajectGkGroup.position.y = Math.max(0, arcHeight);

    const maxTilt = -this.diveDirection * 1.42;
    trajectGkBody.rotation.z = maxTilt * ease;
    trajectGkBody.rotation.y = -this.diveDirection * 0.22 * ease;

    const scale = (this.profile?.height || 1.88) / 1.88;
    if (trajectGkLeftArm && trajectGkRightArm) {
      if (this.diveDirection > 0) {
        trajectGkRightArm.rotation.z = -2.15 * ease;
        trajectGkRightArm.position.y = (1.40 + 0.18 * ease) * scale;
        trajectGkLeftArm.rotation.z = -0.45 * ease;
      } else {
        trajectGkLeftArm.rotation.z = 2.15 * ease;
        trajectGkLeftArm.position.y = (1.40 + 0.18 * ease) * scale;
        trajectGkRightArm.rotation.z = 0.45 * ease;
      }
    }

    if (trajectGkLeftLeg && trajectGkRightLeg) {
      if (this.diveDirection > 0) {
        trajectGkRightLeg.rotation.z = -0.32 * ease;
        trajectGkLeftLeg.rotation.z = 0.62 * ease;
      } else {
        trajectGkLeftLeg.rotation.z = 0.32 * ease;
        trajectGkRightLeg.rotation.z = -0.62 * ease;
      }
    }

    // Realistic Goalkeeper Deflection Physics (Hand / Glove / Body Contact)
    if (this.willSave && !this.isDeflected && ballPos && ballPos.z >= 22.8 && ballPos.z <= 24.3) {
      const activeGlove = this.diveDirection > 0 ? trajectGkRightGlove : trajectGkLeftGlove;
      const glovePos = new THREE.Vector3();
      if (activeGlove) activeGlove.getWorldPosition(glovePos);
      else glovePos.set(currentX, Math.max(0.5, arcHeight), 23.6);

      const dist = glovePos.distanceTo(ballPos);
      if (dist < 0.85) {
        this.isDeflected = true;

        if (ballPos.y > 1.85) {
          // Tip-over save over the crossbar!
          ballVel.y = Math.abs(ballVel.y) * 0.65 + 5.2;
          ballVel.z = ballVel.z * 0.35 + 1.5;
          ballVel.x *= 0.45;
          if (ballSpin) { ballSpin.x = 220; ballSpin.y *= 0.3; }
        } else if (Math.abs(ballPos.x) > 1.8) {
          // Parried wide past the post into corner territory!
          ballVel.x += Math.sign(ballPos.x || this.diveDirection) * 6.2;
          ballVel.z = ballVel.z * 0.28;
          ballVel.y = Math.abs(ballVel.y) * 0.35 + 1.2;
          if (ballSpin) { ballSpin.y = -Math.sign(ballPos.x) * 350; }
        } else {
          // Block / punch rebound back into the penalty box!
          ballVel.z = -Math.abs(ballVel.z) * 0.52 - 1.8;
          ballVel.y = Math.abs(ballVel.y) * 0.45 + 3.0;
          ballVel.x = ballVel.x * 0.4 + (Math.random() - 0.5) * 3.5;
          if (ballSpin) { ballSpin.x = -180; }
        }

        playSound('bounce');
        spawnTurfParticles(glovePos, 25);
      }
    }

    if (progress >= 1.0 && trajectGkGroup.position.y <= 0.05) {
      trajectGkGroup.position.y = 0;
      if (!this.hasLanded) {
        this.hasLanded = true;
        spawnTurfParticles(new THREE.Vector3(currentX, 0, 23.6), 25);
      }
    }
  }
};

/* ================================================================
   PHYSICS ENGINE: RUNGE-KUTTA (MAGNUS SWING + DRAG CRISIS + KNUCKLE)
   ================================================================ */
function updateTrajectoryCalculations() {
  const speedKmh = parseFloat($('#rngSpeed')?.value || 118);
  const spinRpm = parseFloat($('#rngSpin')?.value || 440);
  const elevDeg = parseFloat($('#rngElev')?.value || 12.5);
  const azimuthDeg = parseFloat($('#rngAzimuth')?.value || 8.0);
  const startZ = trajectMode === 'penalty' ? 13.0 : 0.0;

  /* Update UI Labels */
  if ($('#valSpeed')) $('#valSpeed').textContent = `${speedKmh} km/h`;
  if ($('#valSpin')) {
    const dir = spinRpm > 0 ? 'In-Swinger' : spinRpm < 0 ? 'Trivela Out-Swinger' : 'Knuckle Zero-Spin';
    $('#valSpin').textContent = `${Math.abs(spinRpm)} RPM (${dir})`;
  }
  if ($('#valElev')) $('#valElev').textContent = `${elevDeg.toFixed(1)}°`;
  if ($('#valAzimuth')) {
    const dirTxt = azimuthDeg > 0 ? 'Aiming Right' : azimuthDeg < 0 ? 'Aiming Left' : 'Center';
    $('#valAzimuth').textContent = `${azimuthDeg > 0 ? '+' : ''}${azimuthDeg.toFixed(1)}° (${dirTxt})`;
  }

  /* Physics Integration Step-by-Step with True 3D Aerodynamics */
  const v0 = speedKmh * (1000 / 3600);
  const theta = (elevDeg * Math.PI) / 180;
  const phi = (azimuthDeg * Math.PI) / 180;
  const omegaY = (spinRpm * 2 * Math.PI) / 60;
  const omegaX = -0.15 * omegaY; // topspin coupling
  const omegaZ = 0.04 * omegaY;

  let vx = v0 * Math.sin(phi) * Math.cos(theta);
  let vy = v0 * Math.sin(theta);
  let vz = v0 * Math.cos(phi) * Math.cos(theta);

  let x = 0, y = 0.11, z = startZ;
  const dt = 0.003;
  const points = [];
  let apexY = 0;
  let wallY = 0;
  let wallX = 0;
  let passedWall = false;
  let hitWall = false;

  const g = 9.81;
  const rho = 1.225;
  const radius = 0.11;
  const area = Math.PI * radius * radius;
  const mass = 0.430;

  for (let t = 0; t < 2.5; t += dt) {
    points.push(new THREE.Vector3(x, y, z));
    if (y > apexY) apexY = y;

    // Sample point at Wall (Z = 9.15m) for telemetry
    if (z >= 9.15 && !passedWall && startZ < 9.0) {
      wallX = x;
      wallY = y;
      passedWall = true;
    }

    // Continuous Defensive Wall Collision Check (Z = 8.95m to 9.35m)
    if (!hitWall && startZ < 9.0 && z >= 8.95 && z <= 9.35) {
      if (x >= -0.65 && x <= 1.25 && y <= 1.95) {
        hitWall = true;
      }
    }

    if (z >= 24.0 || y <= 0.04) break;

    const speed = Math.sqrt(vx * vx + vy * vy + vz * vz);
    if (speed < 0.01) break;

    // Drag crisis transition around 23 m/s
    const cd = speed > 23.0 ? (0.16 + 0.08 * (1 - Math.exp(-(speed - 23.0) / 10))) : (0.22 + 0.16 * Math.exp(-speed / 16));
    const fDrag = 0.5 * rho * area * cd * speed * speed;

    const fDragX = -fDrag * (vx / speed);
    const fDragY = -fDrag * (vy / speed);
    const fDragZ = -fDrag * (vz / speed);

    /* 3D Magnus Lift & Lateral Curve Vector */
    const spinMag = Math.sqrt(omegaX * omegaX + omegaY * omegaY + omegaZ * omegaZ);
    let fMagX = 0, fMagY = 0, fMagZ = 0;
    if (spinMag > 0.1) {
      const spinParam = (radius * spinMag) / speed;
      const cl = Math.min(0.42, 0.38 * Math.pow(spinParam, 0.75));
      const fMagTotal = 0.5 * rho * area * cl * speed * speed;
      const crossX = omegaY * vz - omegaZ * vy;
      const crossY = omegaZ * vx - omegaX * vz;
      const crossZ = omegaX * vy - omegaY * vx;
      const crossLen = Math.sqrt(crossX * crossX + crossY * crossY + crossZ * crossZ) || 1;
      fMagX = fMagTotal * (crossX / crossLen);
      fMagY = fMagTotal * (crossY / crossLen);
      fMagZ = fMagTotal * (crossZ / crossLen);
    }

    /* Knuckleball Turbulence & Seam Aerodynamic Dip */
    let fKnuckleX = 0, fKnuckleY = 0;
    if (Math.abs(spinRpm) < 65 && speed > 20) {
      // Erratic lateral vortex shedding
      fKnuckleX = (Math.sin(t * 30) * Math.cos(t * 42) + 0.5 * Math.sin(t * 54)) * 1.8;
      // Boundary layer drag crisis plunge after clearing wall peak (z > 9.5m)
      const dipPlunge = z > 9.5 ? 1.6 : 0.0;
      fKnuckleY = (Math.sin(t * 38) + 0.4 * Math.cos(t * 26)) * 0.8 - dipPlunge;
    }

    const ax = (fDragX + fMagX + fKnuckleX) / mass;
    const ay = (fDragY + fMagY + fKnuckleY) / mass - g;
    const az = (fDragZ + fMagZ) / mass;

    vx += ax * dt;
    vy += ay * dt;
    vz += az * dt;

    x += vx * dt;
    y += vy * dt;
    z += vz * dt;
  }

  /* Render 3D Path Line with Glowing Volt Tube */
  if (typeof trajectScene !== 'undefined' && trajectScene && trajectPathLine) {
    trajectScene.remove(trajectPathLine);
  }
  if (points.length > 2 && typeof THREE !== 'undefined' && THREE) {
    const curve = new THREE.CatmullRomCurve3(points);
    const tubeGeo = new THREE.TubeGeometry(curve, 100, 0.022, 8, false);
    const tubeMat = new THREE.MeshStandardMaterial({
      color: 0xc8ff2e,
      emissive: 0xc8ff2e,
      emissiveIntensity: 0.6,
      transparent: true,
      opacity: 0.85,
      roughness: 0.3
    });
    trajectPathLine = new THREE.Mesh(tubeGeo, tubeMat);
    if (typeof trajectScene !== 'undefined' && trajectScene) {
      trajectScene.add(trajectPathLine);
    }
  }

  // Fallback wall check if not hit during loop
  if (!hitWall && startZ < 9.0) {
    if (wallX >= -0.65 && wallX <= 1.25 && wallY <= 1.95) {
      hitWall = true;
    }
  }

  /* Outcome Calculation */
  const lastPt = points.length > 0 ? points[points.length - 1] : { x: 0, y: 0, z: 0 };
  const flightSec = (points.length * dt).toFixed(2);
  const wallClearCm = Math.round((wallY - 1.95) * 100);

  /* Calculate Goalkeeper Save Probability */
  let gkSaveProb = 0;
  if (selectedGk.name !== 'Open Goal' && lastPt.z >= 23.5) {
    const reachFactor = selectedGk.reach / 100;
    const reflexFactor = selectedGk.reflex / 100;
    const diveFactor = selectedGk.dive / 100;
    const distFromCenter = Math.sqrt(lastPt.x * lastPt.x + (lastPt.y - 1.2) * (lastPt.y - 1.2));
    const cornerDifficulty = Math.min(1, distFromCenter / 3.8);
    const speedDifficulty = Math.min(1, speedKmh / 125);
    const curveDifficulty = Math.min(1, Math.abs(spinRpm) / 500);

    const baseSave = (reflexFactor * 0.45 + diveFactor * 0.35 + reachFactor * 0.20);
    gkSaveProb = Math.max(0, Math.min(90,
      baseSave * 100 * (1 - cornerDifficulty * 0.65) * (1 - speedDifficulty * 0.35) * (1 - curveDifficulty * 0.20)
    ));
  }

  /* Update Telemetry Strip */
  if ($('#ttExitSpeed')) $('#ttExitSpeed').textContent = `${speedKmh} km/h`;
  if ($('#ttSpinRate')) $('#ttSpinRate').textContent = `${Math.abs(spinRpm)} RPM`;
  if ($('#ttApexHeight')) $('#ttApexHeight').textContent = `${apexY.toFixed(2)} m`;
  if ($('#ttFlightTime')) $('#ttFlightTime').textContent = `${flightSec} s`;
  if ($('#ttWallClear')) {
    if (trajectMode === 'penalty') {
      $('#ttWallClear').textContent = 'NO WALL (11M)';
    } else {
      $('#ttWallClear').textContent = hitWall ? `BLOCKED (${wallClearCm} cm)` : (wallClearCm >= 0 ? `+${wallClearCm} cm` : 'AROUND WALL');
    }
  }
  if ($('#ttGkSave')) $('#ttGkSave').textContent = selectedGk.name === 'Open Goal' ? '—' : `${Math.round(gkSaveProb)}%`;

  /* Outcome Badge Determination */
  let outcome = 'OFF TARGET';
  let badgeClass = 'tag-orange';

  if (hitWall) {
    outcome = 'BLOCKED BY DEFENSIVE WALL';
    badgeClass = 'tag-red';
  } else if (lastPt.z >= 23.8 && Math.abs(lastPt.x) <= 3.66 && lastPt.y <= 2.44 && lastPt.y >= 0.1) {
    if (Math.abs(lastPt.x) > 2.3 && lastPt.y > 1.6) {
      outcome = 'GOAL! UPPER 90 TOP CORNER BANGER ⚽🔥';
      badgeClass = 'tag-volt';
    } else if (Math.abs(lastPt.x) > 2.0 && lastPt.y < 0.6) {
      outcome = 'GOAL! LOW DRIVEN BOTTOM CORNER ⚽';
      badgeClass = 'tag-volt';
    } else {
      outcome = 'GOAL! CLEAN CLINICAL FINISH ⚽';
      badgeClass = 'tag-volt';
    }
  } else if (lastPt.z >= 23.8 && Math.abs(lastPt.x) <= 3.8 && Math.abs(lastPt.y - 2.44) < 0.25) {
    outcome = 'OFF THE CROSSBAR! 🤦';
    badgeClass = 'tag-orange';
  } else if (lastPt.z >= 23.8 && Math.abs(Math.abs(lastPt.x) - 3.66) < 0.25 && lastPt.y <= 2.44) {
    outcome = 'OFF THE POST! ⚡';
    badgeClass = 'tag-orange';
  }

  if (typeof drawBallFlightRadar === 'function') {
    drawBallFlightRadar({ speedKmh, spinRpm, elevDeg, azimuthDeg });
  }

  // NOTE: trajectResultBadge is shown ONLY after the strike simulation is finished (in handleStrikeOutcome).
  return { points, outcome, gkSaveProb, hitWall, lastPt };
}

function resetTrajectoryBadge() {
  if (isStriking) return;
  const badgeEl = document.getElementById('trajectResultBadge');
  if (badgeEl) {
    badgeEl.textContent = 'READY FOR STRIKE';
    badgeEl.className = 'hud-badge';
  }
}

/* ================================================================
   DYNAMIC REAL-TIME STRIKE ANIMATION, SWING, NET & GK PHYSICS
   ================================================================ */
function executeFreeKickAnimation() {
  if (isStriking) return;
  isStriking = true;
  strikeCounter++;

  const sim = updateTrajectoryCalculations();
  const startZ = trajectMode === 'penalty' ? 13.0 : 0.0;
  const speedKmh = parseFloat(document.getElementById('rngSpeed')?.value || 118);
  const spinRpm = parseFloat(document.getElementById('rngSpin')?.value || 440);
  const elevDeg = parseFloat(document.getElementById('rngElev')?.value || 12.5);
  const azimuthDeg = parseFloat(document.getElementById('rngAzimuth')?.value || 8.0);

  // Reset ball to kick spot
  trajectBall.position.set(0, 0.11, startZ);
  trajectBall.quaternion.identity();
  if (trajectFootballModel) {
    trajectFootballModel.position.set(0, 0.11, startZ);
    trajectFootballModel.quaternion.identity();
  }

  // Animate striker run-up and strike toward ball
  animateKickerRunUpAndStrike(() => {
    // CONTACT MOMENT: Ball takes physical flight!
    const badgeEl = document.getElementById('trajectResultBadge');
    if (badgeEl) {
      badgeEl.textContent = 'IN FLIGHT... ⚡';
      badgeEl.className = 'hud-badge tag-volt';
    }

    playSound('kick');
    spawnTurfParticles(new THREE.Vector3(0, 0, startZ), 45);

    // Initialize Goalkeeper dive state
    const willSave = selectedGk.name !== 'Open Goal' && (Math.random() * 100 < sim.gkSaveProb);
    GoalkeeperPhysics.reset();
    GoalkeeperPhysics.startDive(sim.lastPt, willSave, selectedGk);

    startBallPhysicalFlight(sim, startZ, speedKmh, spinRpm, elevDeg, azimuthDeg, willSave);
  });
}

function startBallPhysicalFlight(sim, startZ, speedKmh, spinRpm, elevDeg, azimuthDeg, willSave) {

  // Physical State Variables
  const v0 = speedKmh * (1000 / 3600);
  const theta = (elevDeg * Math.PI) / 180;
  const phi = (azimuthDeg * Math.PI) / 180;

  let omegaY = (spinRpm * 2 * Math.PI) / 60;
  let omegaX = -0.15 * omegaY; // topspin coupling
  let omegaZ = 0.04 * omegaY;

  const ballPos = new THREE.Vector3(0, 0.11, startZ);
  const ballVel = new THREE.Vector3(
    v0 * Math.sin(phi) * Math.cos(theta),
    v0 * Math.sin(theta),
    v0 * Math.cos(phi) * Math.cos(theta)
  );

  const initialCamPos = trajectCamera.position.clone();
  const radius = 0.11;
  const mass = 0.430;
  const rho = 1.225;
  const area = Math.PI * radius * radius;
  const g = 9.81;

  let animTime = 0;
  let hasHitWall = false;
  let hasHitWoodwork = false;
  let hasHitNet = false;
  let groundBounces = 0;
  let isFinished = false;
  let settleTimer = 0;

  // Spin rotation axis in 3D
  const spinAxis = new THREE.Vector3(omegaX, omegaY, omegaZ).normalize();
  if (spinAxis.lengthSq() < 0.1) spinAxis.set(1, 0, 0);

  function physicsStep() {
    if (isFinished) return;

    const subSteps = 2;
    const dt = 0.016 / subSteps;

    for (let s = 0; s < subSteps; s++) {
      animTime += dt;
      const speed = ballVel.length();

      // Free aerodynamic flight forces (before net or severe deceleration)
      if (speed > 0.1 && !hasHitNet) {
        // Drag crisis transition
        const cd = speed > 23.0 ? (0.16 + 0.08 * (1 - Math.exp(-(speed - 23.0) / 10))) : (0.22 + 0.16 * Math.exp(-speed / 16));
        const fDrag = 0.5 * rho * area * cd * speed * speed;
        const fDragVec = ballVel.clone().multiplyScalar(-fDrag / speed);

        // 3D Magnus Force Vector
        const spinMag = Math.sqrt(omegaX * omegaX + omegaY * omegaY + omegaZ * omegaZ);
        let fMagVec = new THREE.Vector3();
        if (spinMag > 0.1) {
          const spinParam = (radius * spinMag) / speed;
          const cl = Math.min(0.42, 0.38 * Math.pow(spinParam, 0.75));
          const fMagTotal = 0.5 * rho * area * cl * speed * speed;
          const omegaVec = new THREE.Vector3(omegaX, omegaY, omegaZ);
          fMagVec.crossVectors(omegaVec, ballVel).normalize().multiplyScalar(fMagTotal);
        }

        // Knuckleball Lateral Turbulence & Seam Aerodynamic Dip
        let fKnuckleVec = new THREE.Vector3();
        if (Math.abs(spinRpm) < 65 && speed > 20) {
          fKnuckleVec.x = (Math.sin(animTime * 30) * Math.cos(animTime * 42) + 0.5 * Math.sin(animTime * 54)) * 1.8;
          const dipPlunge = ballPos.z > 9.5 ? 1.6 : 0.0;
          fKnuckleVec.y = (Math.sin(animTime * 38) + 0.4 * Math.cos(animTime * 26)) * 0.8 - dipPlunge;
        }

        const accel = fDragVec.add(fMagVec).add(fKnuckleVec).divideScalar(mass);
        accel.y -= g;
        ballVel.addScaledVector(accel, dt);
      } else if (hasHitNet) {
        // Viscoelastic net energy absorption and gravity fall
        ballVel.x *= 0.65;
        ballVel.z *= 0.65;
        // Gravity drop down the netting with rope friction
        ballVel.y = Math.max(-4.2, ballVel.y - g * 0.85 * dt);
        // Net boundary confinement
        if (ballPos.z > 25.85) { ballPos.z = 25.85; ballVel.z = -0.35; }
        if (Math.abs(ballPos.x) > 3.55) { ballPos.x = Math.sign(ballPos.x) * 3.55; ballVel.x = -Math.sign(ballPos.x) * 0.2; }
      }

      ballPos.addScaledVector(ballVel, dt);

      // 1. Defensive Wall Collision Check (Z = 9.15m)
      if (!hasHitWall && startZ < 9.0 && ballPos.z >= 8.95 && ballPos.z <= 9.35) {
        if (ballPos.x >= -0.65 && ballPos.x <= 1.25 && ballPos.y <= 1.95) {
          hasHitWall = true;
          ballVel.z = -Math.abs(ballVel.z) * 0.32;
          ballVel.y = Math.abs(ballVel.y) * 0.35 + 2.0;
          ballVel.x += (Math.random() - 0.5) * 3.5;
          omegaX = -150;
          playSound('bounce');
          spawnTurfParticles(ballPos.clone(), 22);
        }
      }

      // 2. Goal Frame (Posts & Crossbar) Collision Check (Z = 24.0m)
      if (!hasHitWoodwork && ballPos.z >= 23.82 && ballPos.z <= 24.28) {
        // Left Post (X = -3.66, Y <= 2.44)
        const distLeft = Math.hypot(ballPos.x - (-3.66), ballPos.z - 24.0);
        // Right Post (X = +3.66, Y <= 2.44)
        const distRight = Math.hypot(ballPos.x - 3.66, ballPos.z - 24.0);
        // Crossbar (Y = 2.44, |X| <= 3.66)
        const distBar = Math.hypot(ballPos.y - 2.44, ballPos.z - 24.0);

        if (distLeft < 0.17 && ballPos.y <= 2.44) {
          hasHitWoodwork = true;
          const normal = new THREE.Vector3(ballPos.x - (-3.66), 0, ballPos.z - 24.0).normalize();
          ballVel.sub(normal.clone().multiplyScalar(1.74 * ballVel.dot(normal)));
          omegaY = normal.x * 300;
          try { playCrossbarClang(); } catch(e) {}
          spawnTurfParticles(ballPos.clone(), 30);
        } else if (distRight < 0.17 && ballPos.y <= 2.44) {
          hasHitWoodwork = true;
          const normal = new THREE.Vector3(ballPos.x - 3.66, 0, ballPos.z - 24.0).normalize();
          ballVel.sub(normal.clone().multiplyScalar(1.74 * ballVel.dot(normal)));
          omegaY = normal.x * 300;
          try { playCrossbarClang(); } catch(e) {}
          spawnTurfParticles(ballPos.clone(), 30);
        } else if (distBar < 0.17 && Math.abs(ballPos.x) <= 3.66) {
          hasHitWoodwork = true;
          const normal = new THREE.Vector3(0, ballPos.y - 2.44, ballPos.z - 24.0).normalize();
          ballVel.sub(normal.clone().multiplyScalar(1.74 * ballVel.dot(normal)));
          if (normal.y < -0.15) {
            // Underside crossbar carom down into goal turf!
            ballVel.y = -Math.abs(ballVel.y) * 0.75 - 2.2;
            ballVel.z = ballVel.z * 0.65;
          }
          omegaX = -250;
          try { playCrossbarClang(); } catch(e) {}
          spawnTurfParticles(ballPos.clone(), 30);
        }
      }

      // 3. Goal Net Trapping & Ripple (Inside Goal Frame Z >= 24.0m)
      if (!hasHitNet && ballPos.z >= 24.0 && Math.abs(ballPos.x) <= 3.66 && ballPos.y <= 2.44) {
        if (ballPos.z >= 25.1 || Math.abs(ballPos.x) >= 3.48 || (ballPos.y >= 2.34 && ballPos.z >= 24.4)) {
          hasHitNet = true;
          NetPhysics.trigger(ballPos.clone(), ballVel.clone());
          ballVel.x *= 0.35;
          ballVel.z *= 0.35;
        }
      }

      // 4. Ground Turf Physics (Bouncing, Spin Traction, Rolling Deceleration)
      if (ballPos.y <= 0.11) {
        ballPos.y = 0.11;
        const vertSpeed = Math.abs(ballVel.y);

        if (vertSpeed > 0.22 && groundBounces < 6) {
          groundBounces++;
          const eTurf = Math.max(0.18, 0.58 * Math.pow(0.80, groundBounces));
          ballVel.y = vertSpeed * eTurf;

          // Traction impulse from spin coupling with grass
          ballVel.z -= omegaX * 0.0032;
          ballVel.x -= omegaY * 0.0032;

          // Turf friction on horizontal speed
          ballVel.x *= 0.82;
          ballVel.z *= 0.82;

          // Spin dissipation
          omegaX *= 0.45;
          omegaY *= 0.45;
          omegaZ *= 0.45;

          playSound('bounce');
          spawnTurfParticles(ballPos.clone(), Math.max(8, 22 - groundBounces * 3));
        } else {
          // Pure grass rolling resistance
          ballVel.y = 0;
          const horizSpeed = Math.hypot(ballVel.x, ballVel.z);
          if (horizSpeed > 0.03) {
            const aRoll = 1.75; // m/s^2 grass rolling friction
            const newSpeed = Math.max(0, horizSpeed - aRoll * dt);
            const factor = newSpeed / horizSpeed;
            ballVel.x *= factor;
            ballVel.z *= factor;
          } else {
            ballVel.x = 0;
            ballVel.z = 0;
          }
        }
      }
    }

    // Goalkeeper Biomechanical Physics Update
    const spinProxy = { x: omegaX, y: omegaY, z: omegaZ };
    GoalkeeperPhysics.update(0.016, ballPos, ballVel, spinProxy);

    // Apply Ball Position
    trajectBall.position.copy(ballPos);

    // Ball 3D Rotation Quaternion (In-air spin or ground roll)
    const horizSpeed = Math.hypot(ballVel.x, ballVel.z);
    if (ballPos.y <= 0.115 && horizSpeed > 0.03) {
      // Synchronized rolling rotation on ground
      const rollAxis = new THREE.Vector3(-ballVel.z, 0, ballVel.x).normalize();
      const rollAngle = (horizSpeed * 0.016) / radius;
      const rollQuat = new THREE.Quaternion().setFromAxisAngle(rollAxis, rollAngle);
      trajectBall.quaternion.multiplyQuaternions(rollQuat, trajectBall.quaternion);
    } else {
      // Aerodynamic in-air spin
      const frameSpeed = ballVel.length();
      const rotSpeed = (Math.hypot(omegaX, omegaY, omegaZ) * 0.0035 + frameSpeed * 0.06) * 0.016;
      const deltaQuat = new THREE.Quaternion().setFromAxisAngle(spinAxis, rotSpeed);
      trajectBall.quaternion.multiplyQuaternions(deltaQuat, trajectBall.quaternion);
    }

    if (trajectFootballModel) {
      trajectFootballModel.position.copy(trajectBall.position);
      trajectFootballModel.quaternion.copy(trajectBall.quaternion);
    }

    // Dynamic Action Camera Follow
    if (currentCameraMode === 'action') {
      const distTraveled = ballPos.z - startZ;
      const totalDist = 24.0 - startZ;
      const progress = Math.min(1.0, Math.max(0, distTraveled / totalDist));
      if (progress < 0.70 && !hasHitNet && !hasHitWoodwork && !GoalkeeperPhysics.isDeflected) {
        trajectCamera.position.x = ballPos.x * 0.35 - 1.2;
        trajectCamera.position.y = Math.max(1.8, ballPos.y + 1.1);
        trajectCamera.position.z = ballPos.z - 4.2;
        trajectCamera.lookAt(ballPos.x, ballPos.y, ballPos.z + 8);
      } else {
        trajectCamera.lookAt(ballPos.x * 0.5 + sim.lastPt.x * 0.5, Math.max(0.5, ballPos.y), Math.max(22.0, ballPos.z));
      }
    }

    // Settle & Natural Rest Detection
    const totalSpeed = ballVel.length();
    const isAtRestOnGround = (ballPos.y <= 0.115 && totalSpeed < 0.05);
    const isOutOfBounds = (ballPos.z > 28.0 || ballPos.z < -4.0 || Math.abs(ballPos.x) > 8.0);

    if (hasHitNet || hasHitWoodwork || GoalkeeperPhysics.isDeflected || hasHitWall || isAtRestOnGround) {
      settleTimer += 0.016;
    }

    if ((isAtRestOnGround && settleTimer > 0.4) || isOutOfBounds || animTime > 3.8) {
      isFinished = true;
      handleStrikeOutcome(sim, hasHitWall, hasHitWoodwork, hasHitNet, GoalkeeperPhysics.isDeflected || (willSave && !hasHitWall), initialCamPos);
      return;
    }

    requestAnimationFrame(physicsStep);
  }

  requestAnimationFrame(physicsStep);
}

/* HANDLE STRIKE OUTCOME, AUDIO, AND SHOOTOUT SCORE */
function handleStrikeOutcome(sim, hasHitWall, hasHitWoodwork, hasHitNet, wasSaved, initialCamPos) {
  let finalOutcome = sim.outcome;
  let finalBadgeClass = 'tag-volt';

  // 1. DEFENSIVE WALL COLLISION: If struck by barrier midway, strictly declare blocked!
  if (hasHitWall || sim.hitWall) {
    finalOutcome = 'BLOCKED BY DEFENSIVE WALL 🛑';
    finalBadgeClass = 'tag-red';
    playSound('bounce');
    toast('STRIKE RESULT: BLOCKED BY DEFENSIVE WALL', 'shield-alert');
  } else if (wasSaved) {
    const gkName = (selectedGk && selectedGk.name) ? selectedGk.name.toUpperCase() : 'GOALKEEPER';
    finalOutcome = 'SAVED BY ' + gkName + '! 🧤⚡';
    finalBadgeClass = 'tag-orange';
    playSound('error');
    toast('STRIKE RESULT: SAVED BY ' + gkName + '!', 'shield');
  } else if (hasHitWoodwork) {
    finalOutcome = (sim.outcome && sim.outcome.includes('POST')) ? 'OFF THE POST! ⚡' : 'OFF THE CROSSBAR! 🤦';
    finalBadgeClass = 'tag-orange';
    try { playCrossbarClang(); } catch(e) {}
    toast('STRIKE RESULT: ' + finalOutcome, 'alert-triangle');
  } else if (hasHitNet || (sim.outcome && sim.outcome.includes('GOAL'))) {
    finalOutcome = (sim.outcome && sim.outcome.includes('GOAL')) ? sim.outcome : 'GOAL! CLEAN CLINICAL FINISH ⚽';
    finalBadgeClass = 'tag-volt';
    playSound('success');
    try { playNetSwish(); } catch(e) {}
    try { playStadiumRoar(); } catch(e) {}
    toast('STRIKE RESULT: ' + finalOutcome, 'sparkles');
  } else {
    finalOutcome = 'OFF TARGET / MISSED 💨';
    finalBadgeClass = 'tag-red';
    playSound('bounce');
    toast('STRIKE RESULT: ' + sim.outcome, 'info');
  }

  // DISPLAY OUTCOME BADGE NOW THAT SIMULATION IS DONE
  const badgeEl = document.getElementById('trajectResultBadge');
  if (badgeEl) {
    badgeEl.textContent = finalOutcome;
    badgeEl.className = `hud-badge ${finalBadgeClass}`;
  }

  // Update Shootout Scoreboard (if in Penalty Mode)
  if (trajectMode === 'penalty') {
    const isGoal = finalOutcome.includes('GOAL');
    recordPenaltyShootout(isGoal);
  }

  // Reset Scene & GK Position after delay
  setTimeout(() => {
    if (trajectGkGroup) {
      trajectGkGroup.position.set(0, 0, 23.6);
      trajectGkGroup.position.y = 0;
      if (trajectGkBody) trajectGkBody.rotation.z = 0;
      if (trajectGkLeftArm) trajectGkLeftArm.rotation.z = 0.55;
      if (trajectGkRightArm) trajectGkRightArm.rotation.z = -0.55;
    }
    const startZ = trajectMode === 'penalty' ? 13.0 : 0.0;
    if (trajectBall) trajectBall.position.set(0, 0.11, startZ);
    if (trajectFootballModel) {
      trajectFootballModel.position.set(0, 0.11, startZ);
      trajectFootballModel.rotation.set(0, 0, 0);
    }
    resetKickerToStance();
    isStriking = false;
  }, 1800);
}

/* PENALTY SHOOTOUT ROUND TRACKER */
function recordPenaltyShootout(isGoal) {
  const roundIdx = penaltyScores.length % 5;
  penaltyScores.push(isGoal ? 'goal' : 'miss');

  const dot = document.querySelector(`.pen-dot[data-round="${roundIdx}"]`);
  if (dot) {
    dot.className = `pen-dot ${isGoal ? 'goal' : 'miss'}`;
    dot.textContent = isGoal ? '✓' : '✗';
  }

  // Check if 5 rounds completed
  if (penaltyScores.length === 5) {
    const goals = penaltyScores.filter(s => s === 'goal').length;
    setTimeout(() => {
      if (goals >= 3) {
        playSound('success');
        toast(`🏆 SHOOTOUT VICTORY: ${goals}/5 PENALTIES CONVERTED!`, 'sparkles');
      } else {
        toast(`SHOOTOUT FINISHED: ${goals}/5 Scored. Click RESET to try again.`, 'info');
      }
    }, 600);
  }
}

function resetShootout() {
  resetTrajectoryBadge();
  penaltyScores = [];
  $$('.pen-dot').forEach((dot, idx) => {
    dot.className = 'pen-dot';
    dot.textContent = `${idx + 1}`;
  });
  toast('Shootout reset. Step up for round 1!', 'zap');
  playSound('pop');
}

