function getRecommendedRoles(x, y) {
  if (x < 0.16) return ['GK', 'SK'];
  if (x < 0.35) {
    if (y < 0.28) return ['LB', 'LWB', 'IWB'];
    if (y > 0.72) return ['RB', 'RWB', 'IWB'];
    return ['CB', 'RCB', 'LCB', 'SW', 'DMF'];
  }
  if (x < 0.60) {
    if (y < 0.25) return ['LM', 'LWB', 'CMF'];
    if (y > 0.75) return ['RM', 'RWB', 'CMF'];
    return ['DMF', 'CMF', 'B2B', 'REGISTA', 'AMF'];
  }
  // Attacking third
  if (y < 0.28) return ['LW', 'LWF', 'IF', 'LM'];
  if (y > 0.72) return ['RW', 'RWF', 'IF', 'RM'];
  return ['AMF', 'SS', 'CF', 'ST', 'F9', 'POACHER'];
}

