  $('#btnManageCustomTactics')?.addEventListener('click', openManageCustomTacticsModal);
  $('#btnNewCustomTactic')?.addEventListener('click', openNewCustomTacticModal);

  $('#btnCloseSaveCustomModal')?.addEventListener('click', closeSaveCustomTacticModal);
  $('#btnCancelSaveCustomModal')?.addEventListener('click', closeSaveCustomTacticModal);
  $('#btnConfirmSaveCustomTactic')?.addEventListener('click', handleSaveCustomTactic);

  $('#btnCloseManageCustomModal')?.addEventListener('click', closeManageCustomTacticsModal);
