/* ================================================================
   AUDIO SYNTHESIZER FOR COUNTDOWN BEAT & REFEREE WHISTLE
   ================================================================ */
function playTimerBeep(freq = 880, duration = 0.08) {
  if (typeof STATE !== 'undefined' && STATE.soundEnabled === false) return;
  try {
    const AudioCtx = window.AudioContext || window.webkitAudioContext;
    if (!STATE.audioCtx && AudioCtx) STATE.audioCtx = new AudioCtx();
    const ctx = STATE.audioCtx;
    if (!ctx) return;
    if (ctx.state === 'suspended') ctx.resume();
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.type = 'sine';
    osc.frequency.setValueAtTime(freq, ctx.currentTime);
    gain.gain.setValueAtTime(0.2, ctx.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + duration);
    osc.connect(gain);
    gain.connect(ctx.destination);
    osc.start();
    osc.stop(ctx.currentTime + duration);
  } catch (e) {}
}

/* ================================================================
   ACADEMY TIMER ENGINE (STATE MACHINE & REALTIME TELEMETRY)
   ================================================================ */
class AcademyTimerEngine {
  constructor() {
    this.activeDrill = ACADEMY_DRILLS[0];
    this.phase = 'IDLE'; // 'IDLE' | 'PREP' | 'WORK' | 'REST' | 'PAUSED' | 'COMPLETE'
    this.previousPhase = 'WORK';
    this.currentSet = 1;
    this.totalSets = 5;
    this.workSeconds = 45;
    this.restSeconds = 15;
    this.prepSeconds = 3;
    this.remainingMs = 45000;
    this.totalPhaseMs = 45000;
    this.activeElapsedSeconds = 0;
    this.totalCalories = 0;
    this.tickerInterval = null;
    this.metronomeInterval = null;
    this.lastTick = null;
    this.lastBeepSecond = -1;

    // Settings
    this.soundWhistle = true;
    this.soundBeep = true;
    this.metronomeEnabled = false;
    this.metronomeBpm = 130;

    // Training History
    this.history = this.loadHistory();
    this.activeFilter = 'all';

    // Keyboard shortcut listeners
    this.bindKeyboardShortcuts();
  }

  loadHistory() {
    try {
      const stored = localStorage.getItem('90p_academy_history');
      return stored ? JSON.parse(stored) : [];
    } catch (e) {
      return [];
    }
  }

  saveHistory(record) {
    try {
      this.history.unshift(record);
      if (this.history.length > 20) this.history.pop();
      localStorage.setItem('90p_academy_history', JSON.stringify(this.history));
      if (window.PLAYER_AUTH && typeof window.PLAYER_AUTH.getCurrentUser === 'function') {
        const user = window.PLAYER_AUTH.getCurrentUser();
        if (user && user.profile) {
          user.profile.academySessions = this.history.length;
        }
      }
    } catch (e) {}
  }

  bindKeyboardShortcuts() {
    window.addEventListener('keydown', (e) => {
      if (e.target && (e.target.tagName === 'INPUT' || e.target.tagName === 'TEXTAREA')) return;
      if (window.location.hash !== '#/academy') return;

      if (e.code === 'Space') {
        e.preventDefault();
        this.togglePlayPause();
      } else if (e.code === 'KeyR') {
        e.preventDefault();
        this.resetInterval();
      } else if (e.code === 'KeyS') {
        e.preventDefault();
        this.skipPhase();
      }
    });
  }

  selectDrill(drillId, autoStart = false) {
    const drill = ACADEMY_DRILLS.find(d => d.id === drillId) || ACADEMY_DRILLS[0];
    this.activeDrill = drill;
    this.workSeconds = drill.workSeconds || 45;
    this.restSeconds = drill.restSeconds || 15;
    this.totalSets = drill.defaultSets || 5;
    this.metronomeBpm = drill.targetBpm || 130;
    this.currentSet = 1;
    this.activeElapsedSeconds = 0;
    this.totalCalories = 0;
    this.phase = 'IDLE';
    this.remainingMs = this.workSeconds * 1000;
    this.totalPhaseMs = this.workSeconds * 1000;

    clearInterval(this.tickerInterval);
    clearInterval(this.metronomeInterval);

    this.renderStation();
    const station = document.getElementById('drillTimerStation');
    if (station) {
      station.classList.add('active');
      station.scrollIntoView({ behavior: 'smooth', block: 'start' });
    }

    if (autoStart) {
      this.startPrepOrWork();
    }
  }

  startPrepOrWork() {
    clearInterval(this.tickerInterval);
    this.lastBeepSecond = -1;

    if (this.prepSeconds > 0) {
      this.phase = 'PREP';
      this.remainingMs = this.prepSeconds * 1000;
      this.totalPhaseMs = this.prepSeconds * 1000;
      if (this.soundBeep) playTimerBeep(440, 0.08);
    } else {
      this.phase = 'WORK';
      this.remainingMs = this.workSeconds * 1000;
      this.totalPhaseMs = this.workSeconds * 1000;
      if (this.soundWhistle && typeof playRefereeWhistle === 'function') playRefereeWhistle();
    }

    this.startTicker();
    this.startMetronome();
    this.updateUI();
  }

  startTicker() {
    this.lastTick = performance.now();
    clearInterval(this.tickerInterval);
    this.tickerInterval = setInterval(() => {
      const now = performance.now();
      const dt = (now - this.lastTick);
      this.lastTick = now;
      this.tick(dt);
    }, 100);
  }

  tick(dtMs) {
    this.remainingMs -= dtMs;

    if (this.phase === 'WORK') {
      this.activeElapsedSeconds += (dtMs / 1000);
      const met = (this.activeDrill && this.activeDrill.met) || 10.0;
      const calsPerSec = (met * 3.5 * 72) / (200 * 60);
      this.totalCalories += calsPerSec * (dtMs / 1000);
    }

    // 3-2-1 Audio Countdown Beeps
    const currentSec = Math.ceil(this.remainingMs / 1000);
    if (this.soundBeep && currentSec > 0 && currentSec <= 3 && currentSec !== this.lastBeepSecond) {
      this.lastBeepSecond = currentSec;
      playTimerBeep(600 + (3 - currentSec) * 150, 0.06);
    }

    if (this.remainingMs <= 0) {
      this.onPhaseComplete();
    } else {
      this.updateUI();
    }
  }

  onPhaseComplete() {
    this.lastBeepSecond = -1;

    if (this.phase === 'PREP') {
      this.phase = 'WORK';
      this.remainingMs = this.workSeconds * 1000;
      this.totalPhaseMs = this.workSeconds * 1000;
      if (this.soundWhistle && typeof playRefereeWhistle === 'function') playRefereeWhistle();
      this.startMetronome();
      this.updateUI();
    } else if (this.phase === 'WORK') {
      if (this.currentSet >= this.totalSets) {
        this.finishSession();
      } else {
        this.phase = 'REST';
        this.remainingMs = this.restSeconds * 1000;
        this.totalPhaseMs = this.restSeconds * 1000;
        if (this.soundWhistle && typeof playRefereeWhistle === 'function') playRefereeWhistle();
        this.stopMetronome();
        this.updateUI();
      }
    } else if (this.phase === 'REST') {
      this.currentSet += 1;
      this.phase = 'WORK';
      this.remainingMs = this.workSeconds * 1000;
      this.totalPhaseMs = this.workSeconds * 1000;
      if (this.soundWhistle && typeof playRefereeWhistle === 'function') playRefereeWhistle();
      this.startMetronome();
      this.updateUI();
    }
  }

  togglePlayPause() {
    if (this.phase === 'IDLE') {
      this.startPrepOrWork();
    } else if (this.phase === 'WORK' || this.phase === 'REST' || this.phase === 'PREP') {
      this.previousPhase = this.phase;
      this.phase = 'PAUSED';
      clearInterval(this.tickerInterval);
      this.stopMetronome();
      if (typeof playSound === 'function') playSound('pop');
      this.updateUI();
    } else if (this.phase === 'PAUSED') {
      this.phase = this.previousPhase;
      this.startTicker();
      if (this.phase === 'WORK') this.startMetronome();
      if (typeof playSound === 'function') playSound('click');
      this.updateUI();
    }
  }

  skipPhase() {
    if (this.phase === 'IDLE' || this.phase === 'COMPLETE') return;
    this.onPhaseComplete();
    if (typeof playSound === 'function') playSound('whoosh');
  }

  resetInterval() {
    this.remainingMs = this.totalPhaseMs;
    this.lastBeepSecond = -1;
    if (typeof playSound === 'function') playSound('pop');
    this.updateUI();
  }

  startMetronome() {
    this.stopMetronome();
    if (!this.metronomeEnabled || this.phase !== 'WORK') return;

    const intervalMs = 60000 / this.metronomeBpm;
    this.metronomeInterval = setInterval(() => {
      const dot = document.getElementById('metroPulseDot');
      if (dot) {
        dot.classList.add('beat');
        setTimeout(() => dot.classList.remove('beat'), 80);
      }
      playTimerBeep(1200, 0.02);
    }, intervalMs);
  }

  stopMetronome() {
    clearInterval(this.metronomeInterval);
  }

  finishSession() {
    clearInterval(this.tickerInterval);
    this.stopMetronome();
    this.phase = 'COMPLETE';

    if (this.soundWhistle && typeof playRefereeWhistle === 'function') {
      playRefereeWhistle();
      setTimeout(() => playRefereeWhistle(), 250);
    }
    if (typeof playSound === 'function') playSound('success');

    const totalMin = Math.max(1, Math.round(this.activeElapsedSeconds / 60));
    const caloriesBurned = Math.round(this.totalCalories || (totalMin * 11));

    const record = {
      id: 'session-' + Date.now(),
      drillId: this.activeDrill.id,
      title: this.activeDrill.title,
      category: this.activeDrill.categoryLabel || this.activeDrill.category,
      sets: this.totalSets,
      activeSeconds: Math.round(this.activeElapsedSeconds),
      calories: caloriesBurned,
      timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
      date: new Date().toLocaleDateString()
    };

    this.saveHistory(record);
    this.updateUI();
    this.openSummaryModal(record);
    this.renderHistory();
  }

  openSummaryModal(record) {
    const modal = document.getElementById('drillSummaryModal');
    if (!modal) return;
    const title = document.getElementById('sumDrillTitle');
    const sets = document.getElementById('sumSets');
    const workTime = document.getElementById('sumWorkTime');
    const calories = document.getElementById('sumCalories');
    const mins = Math.floor(record.activeSeconds / 60);
    const secs = record.activeSeconds % 60;

    if (title) title.textContent = record.title;
    if (sets) sets.textContent = `${record.sets} / ${record.sets}`;
    if (workTime) workTime.textContent = `${mins}m ${secs}s`;
    if (calories) calories.textContent = `${record.calories} kcal`;

    modal.classList.add('open');
  }

  closeSummaryModal() {
    const modal = document.getElementById('drillSummaryModal');
    if (modal) modal.classList.remove('open');
  }

  openSettingsModal(drillId = null) {
    if (drillId) {
      const drill = ACADEMY_DRILLS.find(d => d.id === drillId);
      if (drill) this.activeDrill = drill;
    }
    const modal = document.getElementById('drillTimerSettingsModal');
    if (!modal) return;

    // Set form controls
    const titleEl = document.getElementById('settingsDrillTitle');
    if (titleEl && this.activeDrill) titleEl.textContent = `CONFIGURING: ${this.activeDrill.title.toUpperCase()}`;

    const workSlider = document.getElementById('cfgWorkSlider');
    const workVal = document.getElementById('cfgWorkVal');
    if (workSlider && workVal) {
      workSlider.value = this.workSeconds;
      workVal.textContent = `${this.workSeconds}s`;
    }

    const restSlider = document.getElementById('cfgRestSlider');
    const restVal = document.getElementById('cfgRestVal');
    if (restSlider && restVal) {
      restSlider.value = this.restSeconds;
      restVal.textContent = `${this.restSeconds}s`;
    }

    const setsInput = document.getElementById('cfgSetsVal');
    if (setsInput) setsInput.textContent = `${this.totalSets} Sets`;

    const whistleToggle = document.getElementById('cfgWhistleToggle');
    if (whistleToggle) whistleToggle.checked = this.soundWhistle;

    const beepToggle = document.getElementById('cfgBeepToggle');
    if (beepToggle) beepToggle.checked = this.soundBeep;

    const metroToggle = document.getElementById('cfgMetroToggle');
    if (metroToggle) metroToggle.checked = this.metronomeEnabled;

    const bpmSlider = document.getElementById('cfgBpmSlider');
    const bpmVal = document.getElementById('cfgBpmVal');
    if (bpmSlider && bpmVal) {
      bpmSlider.value = this.metronomeBpm;
      bpmVal.textContent = `${this.metronomeBpm} BPM`;
    }

    modal.classList.add('open');
  }

  closeSettingsModal() {
    const modal = document.getElementById('drillTimerSettingsModal');
    if (modal) modal.classList.remove('open');
  }

  applyPreset(presetKey) {
    if (presetKey === 'tabata') {
      this.workSeconds = 20;
      this.restSeconds = 10;
      this.totalSets = 8;
    } else if (presetKey === 'hiit') {
      this.workSeconds = 45;
      this.restSeconds = 15;
      this.totalSets = 5;
    } else if (presetKey === 'endurance') {
      this.workSeconds = 90;
      this.restSeconds = 30;
      this.totalSets = 4;
    } else if (presetKey === 'recovery') {
      this.workSeconds = 60;
      this.restSeconds = 45;
      this.totalSets = 4;
    }

    // Refresh modal values
    const workSlider = document.getElementById('cfgWorkSlider');
    const workVal = document.getElementById('cfgWorkVal');
    if (workSlider && workVal) { workSlider.value = this.workSeconds; workVal.textContent = `${this.workSeconds}s`; }
    const restSlider = document.getElementById('cfgRestSlider');
    const restVal = document.getElementById('cfgRestVal');
    if (restSlider && restVal) { restSlider.value = this.restSeconds; restVal.textContent = `${this.restSeconds}s`; }
    const setsInput = document.getElementById('cfgSetsVal');
    if (setsInput) setsInput.textContent = `${this.totalSets} Sets`;

    if (typeof playSound === 'function') playSound('coin');
  }

  updateUI() {
    const clockEl = document.getElementById('timerDigitalClock');
    const phaseBadge = document.getElementById('timerPhaseBadge');
    const dialProgress = document.getElementById('timerDialProgress');
    const currentSetEl = document.getElementById('timerCurrentSet');
    const elapsedEl = document.getElementById('timerElapsed');
    const caloriesEl = document.getElementById('timerCalories');
    const hrZoneEl = document.getElementById('timerHrZone');
    const playBtn = document.getElementById('timerBtnPlayPause');

    // Format Digital Clock (mm:ss.tenths)
    const totalMs = Math.max(0, this.remainingMs);
    const mins = Math.floor(totalMs / 60000);
    const secs = Math.floor((totalMs % 60000) / 1000);
    const tenths = Math.floor((totalMs % 1000) / 100);
    const timeStr = `${String(mins).padStart(2, '0')}:${String(secs).padStart(2, '0')}.${tenths}`;
    if (clockEl) clockEl.textContent = timeStr;

    // SVG Dial Calculation (Circumference = 534.07)
    const circumference = 534.07;
    const progressFrac = Math.max(0, Math.min(1, this.remainingMs / (this.totalPhaseMs || 1)));
    const offset = circumference * (1 - progressFrac);
    if (dialProgress) {
      dialProgress.style.strokeDashoffset = offset;
      dialProgress.className.baseVal = 'timer-dial-progress' +
        (this.phase === 'REST' ? ' rest-phase' : this.phase === 'PREP' ? ' prep-phase' : '');
    }

    // Phase Badge Styling
    if (phaseBadge) {
      if (this.phase === 'WORK') {
        phaseBadge.textContent = 'WORK PHASE · EXPLOSIVE EFFORT';
        phaseBadge.className = 'timer-phase-badge';
      } else if (this.phase === 'REST') {
        phaseBadge.textContent = 'REST PHASE · RECOVER & BREATHE';
        phaseBadge.className = 'timer-phase-badge rest-phase';
      } else if (this.phase === 'PREP') {
        phaseBadge.textContent = `PREPARING IN ${Math.ceil(this.remainingMs/1000)}S`;
        phaseBadge.className = 'timer-phase-badge prep-phase';
      } else if (this.phase === 'PAUSED') {
        phaseBadge.textContent = 'SESSION PAUSED';
        phaseBadge.className = 'timer-phase-badge prep-phase';
      } else if (this.phase === 'COMPLETE') {
        phaseBadge.textContent = 'PROTOCOL COMPLETE';
        phaseBadge.className = 'timer-phase-badge';
      } else {
        phaseBadge.textContent = 'READY TO LAUNCH';
        phaseBadge.className = 'timer-phase-badge';
      }
    }

    // Sets Indicator
    if (currentSetEl) {
      currentSetEl.textContent = `SET ${this.currentSet} / ${this.totalSets}`;
    }

    // Set Pips Bar
    const pipsContainer = document.getElementById('stationSetsBar');
    if (pipsContainer) {
      let pipsHtml = '';
      for (let i = 1; i <= this.totalSets; i++) {
        if (i < this.currentSet) {
          pipsHtml += '<div class="set-pip completed"></div>';
        } else if (i === this.currentSet) {
          pipsHtml += '<div class="set-pip current"></div>';
        } else {
          pipsHtml += '<div class="set-pip"></div>';
        }
      }
      pipsContainer.innerHTML = pipsHtml;
    }

    // Elapsed Time (mm:ss)
    if (elapsedEl) {
      const eMins = Math.floor(this.activeElapsedSeconds / 60);
      const eSecs = Math.floor(this.activeElapsedSeconds % 60);
      elapsedEl.textContent = `${String(eMins).padStart(2, '0')}:${String(eSecs).padStart(2, '0')}`;
    }

    // Calories Burned
    if (caloriesEl) {
      caloriesEl.textContent = `${this.totalCalories.toFixed(1)} kcal`;
    }

    // Work / Rest Ratio & Sets Ratio
    const ratioEl = document.getElementById('timerWorkRestRatio');
    if (ratioEl) {
      ratioEl.textContent = `${this.workSeconds}s / ${this.restSeconds}s`;
    }
    const ratioHeaderEl = document.getElementById('stationSetsRatio');
    if (ratioHeaderEl) {
      ratioHeaderEl.textContent = `${this.currentSet} of ${this.totalSets}`;
    }
    const metroBpmEl = document.getElementById('stationMetroBpm');
    if (metroBpmEl) {
      metroBpmEl.textContent = `${this.metronomeBpm} BPM`;
    }

    // Heart Rate Zone
    if (hrZoneEl) {
      if (this.phase === 'WORK') {
        hrZoneEl.textContent = this.activeDrill ? this.activeDrill.targetHr : '160–175 BPM (Zone 4)';
      } else if (this.phase === 'REST') {
        hrZoneEl.textContent = '120–135 BPM (Zone 2 Recovery)';
      } else {
        hrZoneEl.textContent = 'RESTING (70–85 BPM)';
      }
    }

    // Play/Pause Button
    if (playBtn) {
      if (this.phase === 'WORK' || this.phase === 'REST' || this.phase === 'PREP') {
        playBtn.innerHTML = '<i data-lucide="pause"></i><span>PAUSE [SPACE]</span>';
      } else {
        playBtn.innerHTML = '<i data-lucide="play"></i><span>RESUME / START [SPACE]</span>';
      }
      if (window.lucide) lucide.createIcons();
    }
  }

  renderStation() {
    const station = document.getElementById('drillTimerStation');
    if (!station || !this.activeDrill) return;

    const titleEl = document.getElementById('stationDrillTitle');
    const catEl = document.getElementById('stationCategoryBadge');
    const diffEl = document.getElementById('stationDiffBadge');
    const gearEl = document.getElementById('stationGearWrap');

    if (titleEl) titleEl.textContent = this.activeDrill.title;
    if (catEl) catEl.textContent = (this.activeDrill.categoryLabel || this.activeDrill.category).toUpperCase();
    if (diffEl) {
      diffEl.textContent = this.activeDrill.difficulty;
      diffEl.className = `drill-badge ${this.activeDrill.difficulty.toLowerCase()}`;
    }

    if (gearEl && Array.isArray(this.activeDrill.gear)) {
      gearEl.innerHTML = this.activeDrill.gear.map(gid => {
        const p = typeof getProduct === 'function' ? getProduct(gid) : null;
        return p ? `<a href="#/product/${p.slug}" class="gear-chip"><i data-lucide="check"></i> ${p.name}</a>` : '';
      }).join('');
    }

    const metroBpmEl = document.getElementById('stationMetroBpm');
    if (metroBpmEl) metroBpmEl.textContent = `${this.metronomeBpm} BPM`;

    this.updateUI();
  }

  renderHistory() {
    const container = document.getElementById('academyHistoryList');
    if (!container) return;

    if (!this.history.length) {
      container.innerHTML = `<p style="color: #98a0a4; font-size: 0.85rem; font-family: var(--fm);">No training sessions logged yet today. Complete any drill above to start tracking your performance!</p>`;
      return;
    }

    container.innerHTML = this.history.map(item => `
      <div class="history-card">
        <div class="history-card-head">
          <span class="hud-tag" style="font-size: 0.58rem;">${item.category.toUpperCase()}</span>
          <span>${item.date} · ${item.timestamp}</span>
        </div>
        <div class="history-drill-title">${item.title}</div>
        <div class="history-meta-row">
          <span>${item.sets} SETS COMPLETED</span>
          <span>${Math.round(item.activeSeconds / 60)}M WORK · ${item.calories} KCAL</span>
        </div>
      </div>
    `).join('');

    if (window.lucide) lucide.createIcons();
  }
}

window.ACADEMY_TIMER = new AcademyTimerEngine();

