/* 8.2  PERFORMANCE TELEMETRY HUD (FPS & GPU MONITOR) */
let fpsCounter = 0;
let lastFpsTime = performance.now();
let currentFps = 60;

function initFpsMonitor() {
  function calcFps(now) {
    fpsCounter++;
    if (now - lastFpsTime >= 1000) {
      currentFps = fpsCounter;
      fpsCounter = 0;
      lastFpsTime = now;
      const el = document.getElementById('hudFpsVal');
      if (el) el.textContent = `${currentFps} FPS`;
    }
    requestAnimationFrame(calcFps);
  }
  requestAnimationFrame(calcFps);
}

/* 8.3  GLOBAL KEYBOARD SHORTCUTS */
function initKeyboardShortcuts() {
  document.addEventListener('keydown', e => {
    /* Ctrl+Shift+T: Open Self-Tests Suite */
    if (e.ctrlKey && e.shiftKey && (e.key === 'T' || e.key === 't')) {
      e.preventDefault();
      openTestModal();
      return;
    }

    if (['INPUT', 'TEXTAREA', 'SELECT'].includes(document.activeElement?.tagName)) return;

    if (e.key === 'c' || e.key === 'C') {
      e.preventDefault();
      DOM.cartDrawer?.classList.contains('open') ? closeCartDrawer() : openCartDrawer();
    } else if (e.key === 'w' || e.key === 'W') {
      e.preventDefault();
      DOM.wishDrawer?.classList.contains('open') ? closeWishlistDrawer() : openWishlistDrawer();
    } else if (e.key === 'h' || e.key === 'H') {
      window.location.hash = '';
    } else if (e.key === 's' || e.key === 'S') {
      window.location.hash = '#/shop';
    }
  });
}

